async function api(resource,data){
  if(resource==='payment'&&data!==undefined)data={...data,date:data.date||document.querySelector('#paymentDate')?.value||document.querySelector('[name="payment_date"]')?.value||new Date().toISOString().slice(0,10),note:data.note??document.querySelector('#paymentNote')?.value??document.querySelector('[name="note"]')?.value??'',currency:data.currency||document.querySelector('#paymentCurrency')?.value||document.querySelector('#admissionCurrency')?.value||'USD',branch:data.branch||'SC1'};
  const options=data===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':server?.csrf||''},body:JSON.stringify(data)};
  const response=await fetch(`${server?.api||'api.php'}?resource=${encodeURIComponent(resource)}`,options);
  const payload=await response.json();
  if(!response.ok)throw new Error(payload.error||'Request failed');
  return payload;
}
async function loadServerData(){if(!server)return;try{const data=await api('bootstrap');state.students=data.students.map(s=>({...s,balance:Number(s.balance),attendance:Number(s.attendance)}));state.admissions=data.admissions;state.payments=data.payments;state.records=data.records||state.records;state.financeSummary=data.finance_summary||null;state.currentUser=data.current_user||state.currentUser;state.attendanceRows=data.attendance||[];state.attendance={};for(const row of state.attendanceRows)if(!(String(row.student_id) in state.attendance))state.attendance[String(row.student_id)]=row.state;state.server=true;const localGeneral=JSON.parse(localStorage.getItem('scschool.generalSettings')||'{}');if(Object.keys(localGeneral).length&&!(state.records['setting-general']||[]).length&&canModule('settings','create')){const saved=await api('workflow',{workflow:'setting-general',payload:localGeneral});state.records['setting-general']=[{id:saved.id,...localGeneral}]}persist();restoreRememberedPage();applySignedInUser();navigate(state.page)}catch(error){toast(`Offline mode: ${error.message}`);try{navigate(state.page)}catch{state.page='dashboard';navigate('dashboard')}}}

