function iconSvg(name,cls='sr-icon'){const body=SR_ICONS[name]||SR_ICONS.settings;return `<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${body}</svg>`}
function enhanceActionIcons(root=document){
  const rules=[
    [/\b(delete|remove|trash)\b/i,'delete'],[/\b(edit|update)\b/i,'edit'],[/\b(save|submit|confirm)\b/i,'save'],
    [/\b(print|pdf format)\b/i,'print'],[/\b(download|excel|export)\b/i,'download'],[/\b(import|upload)\b/i,'upload'],
    [/\b(add|create|new|register)\b/i,'add'],[/\b(detail|view)\b/i,'eye']
  ];
  root.querySelectorAll('button,a.btn').forEach(el=>{
    if(el.querySelector('.sr-icon')||el.classList.contains('nav-item')||el.classList.contains('nav-child'))return;
    let text=(el.textContent||'').trim();
    const hit=rules.find(([rx])=>rx.test(text));
    if(!hit)return;
    // Remove old decorative text icons so every action has one system SVG icon only.
    el.childNodes.forEach(node=>{
      if(node.nodeType!==Node.TEXT_NODE)return;
      node.nodeValue=(node.nodeValue||'')
        .replace(/^\s*(?:\+|✚|✎|🗑|▣|▤|▮|⇩|↓|↑|◉|●|○|⌕|⚙|★|▶|▧|☷|♟|\u25aa|\u2022)\s*/u,'')
        .replace(/^\s*[^\p{L}\p{N}]+(?=[\p{L}\p{N}])/u,'');
    });
    el.insertAdjacentHTML('afterbegin',iconSvg(hit[1],'sr-icon action-icon'));
  });
}

// Keep action icons consistent for rows/buttons inserted after the first page render.
// This is especially important for Collect Fees / Student Admission where every
// new transaction row gets its own Delete button dynamically.
(function observeDynamicActionIcons(){
  let queued=false;
  const refresh=()=>{
    queued=false;
    enhanceActionIcons(document);
  };
  const queue=()=>{
    if(queued)return;
    queued=true;
    requestAnimationFrame(refresh);
  };
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',queue,{once:true});
  else queue();
  new MutationObserver(mutations=>{
    if(mutations.some(m=>[...m.addedNodes].some(n=>n.nodeType===1)))queue();
  }).observe(document.documentElement,{childList:true,subtree:true});
})();
