/* Shared transaction-table page size and pagination. */
const NUMBER_TO_SHOW_OPTIONS=[10,20,30,50,100,1000];
function bindNumberToShow(root=document){
  root.querySelectorAll('label select').forEach(select=>{
    const label=select.closest('label');
    const labelText=(label?.textContent||'').replace(/\s+/g,' ').trim();
    if(!(/Number to Show/i.test(labelText)||(/\bShow\b/i.test(labelText)&&/entries/i.test(labelText))))return;
    if(select.dataset.numberToShowBound==='1')return;
    select.dataset.numberToShowBound='1';
    label.classList.add('number-to-show');
    select.classList.add('number-to-show-select');
    select.innerHTML=NUMBER_TO_SHOW_OPTIONS.map(value=>`<option value="${value}" ${value===10?'selected':''}>${value}</option>`).join('');
    const scope=select.closest('section,article,.panel,.core-card,.setting-card')||root;
    const table=scope.querySelector('table');
    const tbody=table?.tBodies?.[0];
    if(!tbody)return;
    let page=1;
    const dataRows=()=>[...tbody.rows].filter(row=>!row.classList.contains('summary')&&!row.querySelector('td.empty,.class-empty')&&!row.hasAttribute('data-pagination-ignore'));
    const footer=scope.querySelector('.front-table-footer,footer,.school-pagination,.core-foot')||document.createElement('footer');
    if(!footer.isConnected){footer.className='system-table-footer';table.parentElement?.insertAdjacentElement('afterend',footer)}
    const footerChildren=[...footer.children];
    let info=footer.querySelector('.front-table-info,#studentDetailsInfo,#admissionInfo,#invoiceInfo,.system-page-info')||footerChildren.find(child=>child.tagName==='SPAN'&&!child.querySelector('button'));
    footer.childNodes.forEach(node=>{if(node.nodeType===Node.TEXT_NODE&&/(Showing|Page\s+\d+)/i.test(node.nodeValue||''))node.remove()});
    if(!info){info=document.createElement('span');info.className='system-page-info';footer.prepend(info)}
    let pager=footer.querySelector('.front-pagination,.system-pagination')||footerChildren.find(child=>child.querySelector?.('button'));
    if(!pager){pager=document.createElement('div');footer.append(pager)}
    pager.classList.add('system-pagination');
    const refresh=()=>{
      dataRows().forEach(row=>{if(row.dataset.pageHidden==='1'){row.hidden=false;delete row.dataset.pageHidden}});
      const filtered=dataRows().filter(row=>!row.hidden);
      const size=Number(select.value)||10,total=filtered.length,pages=Math.max(1,Math.ceil(total/size));
      page=Math.min(page,pages);
      const start=(page-1)*size,end=Math.min(start+size,total);
      filtered.forEach((row,index)=>{if(index<start||index>=end){row.hidden=true;row.dataset.pageHidden='1'}});
      info.textContent=`Showing ${total?start+1:0} to ${end} of ${total} ${total===1?'entry':'entries'}`;
      const first=Math.max(1,Math.min(page-2,pages-4)),last=Math.min(pages,first+4);
      pager.innerHTML=`<button type="button" data-page="prev" ${page<=1?'disabled':''}>Previous</button>${Array.from({length:last-first+1},(_,i)=>first+i).map(number=>`<button type="button" data-page="${number}" class="${number===page?'active':''}">${number}</button>`).join('')}<button type="button" data-page="next" ${page>=pages?'disabled':''}>Next</button>`;
      pager.querySelectorAll('[data-page]').forEach(button=>button.onclick=()=>{const target=button.dataset.page;page=target==='prev'?Math.max(1,page-1):target==='next'?Math.min(pages,page+1):Number(target);refresh()});
    };
    select.onchange=()=>{page=1;refresh()};
    scope.addEventListener('input',event=>{if(event.target!==select)setTimeout(()=>{page=1;refresh()},0)});
    scope.addEventListener('change',event=>{if(event.target!==select)setTimeout(()=>{page=1;refresh()},0)});
    refresh();
  });
}
new MutationObserver(()=>bindNumberToShow(document)).observe(document.documentElement,{childList:true,subtree:true});
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>bindNumberToShow(document));else bindNumberToShow(document);

/* Automatic codes for system-created items and categories. */
const AUTO_CODE_PREFIX={
 'academic-subject':'SUB','inventory-category':'CAT','inventory-product':'PRD','inventory-warehouse':'WH','inventory-brand':'BRD','inventory-unit':'UNT',
 'setting-fee':'FEE','setting-discount':'DSC','hr-position':'POS','hr-department':'DEP','transport-model':'VMD','branch-add':'BRN',branch:'BRN',assets:'AST','asset-add':'AST','accounting-account':'ACC'
};
function nextSystemCode(key,field='Code'){
 const prefix=AUTO_CODE_PREFIX[key]||String(key||'SYS').split('-').map(part=>part[0]).join('').toUpperCase().slice(0,4)||'SYS';
 const groups=Object.values(state.records||{}).flat().concat(state.subjects||[]),numbers=[];
 for(const row of groups)for(const [name,value] of Object.entries(row||{}))if(/code$/i.test(name)){const match=String(value||'').match(/(\d+)$/);if(match&&String(value).toUpperCase().startsWith(prefix))numbers.push(Number(match[1]))}
 return prefix+String(Math.max(0,...numbers)+1).padStart(3,'0')
}
function bindAutomaticCodes(root=document){
 root.querySelectorAll('form input[name]').forEach(input=>{
  if(!/(^|\s)code$/i.test(input.name))return;
  const form=input.form,key=form?.dataset.key||state.page;
  if(key==='setting-currency'||key==='academic-subject-teacher'||key==='inventory-barcode')return;
  if(input.dataset.autoCodeBound==='1'){if(!input.value.trim())input.value=nextSystemCode(key,input.name);return}
  input.dataset.autoCodeBound='1';input.readOnly=true;input.classList.add('system-auto-code');
  if(!input.value.trim())input.value=nextSystemCode(key,input.name);
 });
}
new MutationObserver(()=>bindAutomaticCodes(document)).observe(document.documentElement,{childList:true,subtree:true});
document.addEventListener('reset',event=>setTimeout(()=>bindAutomaticCodes(event.target),0));
document.addEventListener('submit',event=>bindAutomaticCodes(event.target),true);
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>bindAutomaticCodes(document));else bindAutomaticCodes(document);

