const $=s=>document.querySelector(s); const content=$('#content');
function initials(name){return name.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase()}
function currencyRows(){const rows=state.records?.['setting-currency']||[];return rows.length?rows:[{Currency:'USD',Code:'USD',Symbol:'$',Rate:1,'Is Default':'Yes'},{Currency:'KHR',Code:'KHR',Symbol:'៛',Rate:4100,'Is Default':'No'}]}
function currencyNumber(value,fallback=1){const number=Number(String(value??'').replace(/,/g,''));return Number.isFinite(number)&&number>0?number:fallback}
function defaultCurrency(){const rows=currencyRows();return rows.find(row=>String(row['Is Default']).toLowerCase()==='yes')||rows[0]||{Currency:'USD',Code:'USD',Symbol:'$',Rate:1}}
function currencyRecord(code=''){const wanted=String(code||defaultCurrency().Code||defaultCurrency().Currency).toUpperCase();return currencyRows().find(row=>String(row.Code||row.Currency).toUpperCase()===wanted)||defaultCurrency()}
function currencyCode(code=''){const row=currencyRecord(code);return String(row.Code||row.Currency||'USD').toUpperCase()}
function currencySymbol(code=''){return String(currencyRecord(code).Symbol||currencyCode(code))}
function currencyRate(code=''){return currencyNumber(currencyRecord(code).Rate,1)}
function convertCurrency(value,fromCode='',toCode=''){return Number(value||0)/currencyRate(fromCode)*currencyRate(toCode)}
function currencyOptions(selected=''){const chosen=currencyCode(selected);return currencyRows().map(row=>{const code=String(row.Code||row.Currency||'').toUpperCase();return `<option value="${esc(code)}" ${code===chosen?'selected':''}>${esc(code)} (${esc(row.Symbol||code)})</option>`}).join('')||'<option value="USD">USD ($)</option>'}
function money(v,code=''){const resolved=currencyCode(code),number=Number(v||0);return `${currencySymbol(resolved)} ${number.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}`}
function persist(){try{localStorage.setItem('northstar.students',JSON.stringify(state.students))}catch{}try{localStorage.setItem('scschool.records',JSON.stringify(state.records))}catch{try{const compact=JSON.parse(JSON.stringify(state.records));if(Array.isArray(compact['certificate-form-card']))compact['certificate-form-card']=compact['certificate-form-card'].map(row=>({...row,front_image:'',back_image:''}));if(Array.isArray(compact['setting-bank-account']))compact['setting-bank-account']=compact['setting-bank-account'].map(row=>({...row,'QR Image':''}));localStorage.setItem('scschool.records',JSON.stringify(compact))}catch{}}}
function toast(text){const el=document.createElement('div');el.className='toast';el.textContent=text;$('#toasts').append(el);setTimeout(()=>el.remove(),2800)}
function renderNav(){const activeParent=moduleMenus.find(m=>m[0]===state.page||m[3].some(x=>x[0]===state.page))?.[0];$('#nav').innerHTML=moduleMenus.map(([id,icon,label,children])=>`<div class="nav-module"><button class="nav-item ${activeParent===id?'active':''}" data-page="${children.length?'':id}" data-toggle="${id}"><span class="nav-icon">${iconSvg(icon)}</span>${label}${children.length?'<span class="nav-arrow">⌄</span>':''}</button>${children.length?`<div class="nav-children ${activeParent===id?'open':''}" data-menu="${id}">${children.map(([cid,clabel,cicon])=>`<button class="nav-child ${state.page===cid?'active':''}" data-page="${cid}"><span class="nav-child-icon">${iconSvg(cicon||'add','sr-icon small')}</span>${clabel}</button>`).join('')}</div>`:''}</div>`).join('');document.querySelectorAll('.nav-item').forEach(b=>b.onclick=()=>{if(b.dataset.page)navigate(b.dataset.page);else document.querySelector(`[data-menu="${b.dataset.toggle}"]`).classList.toggle('open')});document.querySelectorAll('.nav-child').forEach(b=>b.onclick=()=>navigate(b.dataset.page));bindAcademicNavGroups();translateDocument($('#nav'))}
function bindAcademicNavGroups(){const menu=document.querySelector('[data-menu="academic"]');if(!menu)return;const bilingual=[...menu.querySelectorAll('[data-page="academic-class-schedule"]')],khmer=[...menu.querySelectorAll('[data-page="academic-khmer-schedule"]')];if(bilingual.length<2||khmer.length<2)return;const bilingualToggle=bilingual[0],khmerToggle=khmer[0],bilingualItems=[bilingual[1],menu.querySelector('[data-page="academic-monthly"]'),menu.querySelector('[data-page="academic-quarterly"]'),menu.querySelector('[data-page="academic-semester"]'),menu.querySelector('[data-page="academic-teaching-schedule"]')],khmerItems=[khmer[1],menu.querySelector('[data-page="academic-khmer-monthly"]'),menu.querySelector('[data-page="academic-khmer-semester"]')];bilingualToggle.classList.add('academic-group-toggle');khmerToggle.classList.add('academic-group-toggle');bilingualItems.forEach(x=>x?.classList.add('academic-nested','bilingual-nested'));khmerItems.forEach(x=>x?.classList.add('academic-nested','khmer-nested'));const setup=(toggle,items,key)=>{let open=sessionStorage.getItem(key)!=='closed';const apply=()=>{items.forEach(x=>{if(x)x.hidden=!open});toggle.classList.toggle('expanded',open)};toggle.onclick=e=>{e.preventDefault();open=!open;sessionStorage.setItem(key,open?'open':'closed');apply()};apply()};setup(bilingualToggle,bilingualItems,'academic.bilingual');setup(khmerToggle,khmerItems,'academic.khmer')}
function isNavigablePage(page){return Boolean(page&&(moduleMenus.some(m=>m[0]===page||m[3].some(x=>x[0]===page))||workflowDefs[page]||['student-edit','student-detail-view','student-pending-detail','mobile-payment-proof'].includes(page)))}
function savedPage(){try{return localStorage.getItem('wg.lastPage')||sessionStorage.getItem('wg.lastPage')||''}catch{return ''}}
function rememberPage(page){
 if(!page)return;
 try{localStorage.setItem('wg.lastPage',page);sessionStorage.setItem('wg.lastPage',page)}catch{}
 try{const url=new URL(location.href);url.searchParams.set('page',page);history.replaceState({page},'',url)}catch{}
}
function restoreRememberedPage(){const requested=new URLSearchParams(location.search).get('page')||'',saved=savedPage(),restored=isNavigablePage(requested)?requested:(isNavigablePage(saved)?saved:'dashboard');state.page=restored;rememberPage(restored);return restored}
function navigate(page){if(page!=='user-add'){state.newUserTemporary=null;if(state.coreEdit?.key==='users')state.coreEdit=null}state.page=page;rememberPage(page);if(page==='accounting-operation')state.accountingOperationTab='journal';if(page==='accounting-account')state.accountingTab='accounting-income-type';renderNav();$('#sidebar').classList.remove('open');const parent=moduleMenus.find(m=>m[0]===page||m[3].some(x=>x[0]===page))||(page==='student-pending-detail'?moduleMenus.find(m=>m[0]==='student'):null);const title=page==='student-pending-detail'?'Admission Review':workflowDefs[page]?.[0]||parent?.[3].find(x=>x[0]===page)?.[1]||parent?.[2]||'Dashboard';$('#sectionLabel').textContent='Dashboard / '+(parent?.[2]||title);$('#pageTitle').textContent=title;render();requestAnimationFrame(()=>{window.scrollTo(0,0);document.documentElement.scrollTop=0;document.body.scrollTop=0;document.querySelector('.main')?.scrollTo?.(0,0)})}
function pageHead(title,desc,actions=''){return `<div class="page-head"><div><h1>${title}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`}
function stat(label,value,note,icon){return `<div class="stat"><div class="stat-top"><span>${label}</span><span class="stat-icon">${icon}</span></div><strong>${value}</strong><small>${note}</small></div>`}

