function setupFrontOfficeView(){const reference=state.page==='front-reference',key=reference?'front-reference':'front-source',title=reference?'Reference':'Source',field=title,saved=state.records[key]||[],hidden=JSON.parse(localStorage.getItem('scschool.frontHidden')||'[]');const defaults=reference?[{id:'default-reference-events',Reference:'School Events',Description:''}]:[{id:'default-source-website',Source:'Website',Description:''},{id:'default-source-advertisement',Source:'Advertisement',Description:''}];const rows=[...defaults.filter(row=>!hidden.includes(row.id)&&!saved.some(item=>item[field]===row[field])),...saved];return `<div class="front-breadcrumb"><span>⌂ Dashboard</span><i>/</i><span>Front Desk Registration</span><i>/</i><span>Setup Front Office</span><button type="button" data-go="dashboard">← Back</button></div><div class="front-office-layout"><aside class="front-office-menu"><h3>⚙ Setup Front Office</h3><button type="button" data-go="front-source" class="${reference?'':'active'}">» &nbsp;Source</button><button type="button" data-go="front-reference" class="${reference?'active':''}">» &nbsp;Reference</button></aside><section class="front-office-content"><header><span>◉</span><h1>${title}</h1><button class="front-add" type="button" id="frontAdd">✚ &nbsp;Add ${title}</button></header><form id="frontOfficeForm" class="front-office-form" data-key="${key}" data-field="${field}" hidden><input type="hidden" name="_id"><div class="form-group"><label>${title} <em>*</em></label><input name="${title}" required autocomplete="off"></div><div class="form-group"><label>Description</label><textarea name="Description" rows="3"></textarea></div><div class="front-form-actions"><button type="button" class="btn secondary" id="frontCancel">Cancel</button><button type="submit" class="btn primary">Save</button></div></form><div class="front-table-tools"><label>Show <select id="frontPageSize"><option>10</option><option>25</option><option selected>50</option><option>100</option></select> entries</label><label class="front-search-label">Search: <input id="frontSearch" class="field"></label></div><div class="table-scroll"><table><thead><tr><th>${title}</th><th>Description</th><th class="front-action-heading"></th></tr></thead><tbody id="frontRows">${rows.length?rows.map(row=>`<tr data-id="${esc(row.id)}" data-value="${esc(row[field]||'')}" data-description="${esc(row.Description||'')}"><td>${esc(row[field]||'')}</td><td>${esc(row.Description||'')}</td><td class="front-row-action"><button type="button" class="front-more" aria-label="Actions">•••⌄</button><div class="front-action-menu" hidden><button type="button" class="front-edit">▧ &nbsp;Edit</button><button type="button" class="front-delete">▮ &nbsp;Delete</button></div></td></tr>`).join(''):`<tr><td colspan="3" class="empty">No records found</td></tr>`}</tbody></table></div><div class="front-table-footer"><div class="front-table-info">Showing ${rows.length?'1':'0'} to ${rows.length} of ${rows.length} ${rows.length===1?'entry':'entries'}</div><div class="front-pagination"><button disabled>Previous</button><b>1</b><button disabled>Next</button></div></div></section></div>`}
function bindFrontOffice(){const search=$('#frontSearch');if(!search)return;const form=$('#frontOfficeForm'),add=$('#frontAdd'),key=form.dataset.key,field=form.dataset.field;const openForm=(id='',value='',description='')=>{form.reset();form.elements._id.value=id;form.elements[field].value=value;form.elements.Description.value=description;form.hidden=false;add.hidden=true;form.elements[field].focus()};add.onclick=()=>openForm();$('#frontCancel').onclick=()=>{form.reset();form.hidden=true;add.hidden=false};document.querySelectorAll('.front-more').forEach(button=>button.onclick=e=>{e.stopPropagation();const menu=button.nextElementSibling,opening=menu.hidden;document.querySelectorAll('.front-action-menu').forEach(item=>item.hidden=true);menu.hidden=!opening});document.querySelectorAll('.front-edit').forEach(button=>button.onclick=()=>{const row=button.closest('tr');openForm(row.dataset.id,row.dataset.value,row.dataset.description)});document.querySelectorAll('.front-delete').forEach(button=>button.onclick=async()=>{const row=button.closest('tr'),id=row.dataset.id;if(!confirm(`Delete ${row.dataset.value}?`))return;try{if(id.startsWith('default-')){const hidden=JSON.parse(localStorage.getItem('scschool.frontHidden')||'[]');if(!hidden.includes(id))hidden.push(id);localStorage.setItem('scschool.frontHidden',JSON.stringify(hidden))}else{if(state.server)await api('delete-workflow',{workflow:key,id});state.records[key]=(state.records[key]||[]).filter(item=>String(item.id)!==id);persist()}render();toast('Record deleted')}catch(error){toast(error.message)}});document.addEventListener('click',()=>document.querySelectorAll('.front-action-menu').forEach(item=>item.hidden=true),{once:true});form.onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(form)),editId=data._id||'';delete data._id;try{const isDefault=editId.startsWith('default-');let savedId=isDefault?'':editId;if(state.server){const result=await api('workflow',{workflow:key,id:savedId,payload:data});savedId=result.id}else savedId=savedId||String(Date.now());state.records[key]??=[];const found=state.records[key].find(item=>String(item.id)===savedId);if(found)Object.assign(found,data);else state.records[key].unshift({id:savedId,...data});if(isDefault){const hidden=JSON.parse(localStorage.getItem('scschool.frontHidden')||'[]');if(!hidden.includes(editId))hidden.push(editId);localStorage.setItem('scschool.frontHidden',JSON.stringify(hidden))}persist();render();toast(editId?'Record updated':'Record saved')}catch(error){toast(error.message)}};search.oninput=e=>{let visible=0;document.querySelectorAll('#frontRows tr').forEach(row=>{row.hidden=!row.textContent.toLowerCase().includes(e.target.value.toLowerCase());if(!row.hidden)visible++});$('.front-table-info').textContent=`Showing ${visible?'1':'0'} to ${visible} of ${visible} ${visible===1?'entry':'entries'}`}}
function classStartView(){const rows=state.records['front-class-start']||[],today=new Date().toISOString().slice(0,10),starting=rows.filter(r=>r['Start Date']===today).length,ending=rows.filter(r=>r['End Date']&&r['End Date']>=today).length,students=rows.reduce((sum,r)=>sum+(Number(r['Total Students'])||0),0),seats=rows.reduce((sum,r)=>sum+(Number(r['Available Seats'])||0),0),options=label=>`<option value="">Select</option>${[...new Set(rows.map(r=>r[label]).filter(Boolean))].map(value=>`<option>${esc(value)}</option>`).join('')}`;return `<div class="front-breadcrumb class-start-breadcrumb"><span>⌂ Dashboard</span><i>/</i><span>Front Desk Registration</span><i>/</i><span>Class Start</span></div><div class="class-start-page"><div class="class-start-stats">${[['Total Classes',rows.length],['Classes Starting Today',starting],['Classes Ending Soon',ending],['Total Students',students],['Available Seats',seats]].map(([label,value])=>`<article><span>${label}</span><b>${value}</b></article>`).join('')}</div><form id="classStartFilters" class="class-start-filters">${['Branch','Program','Category','Class','Academic Year / Session','Status'].map(label=>`<label>${label}<select name="${label}">${options(label)}</select></label>`).join('')}<label>Start Date<input type="date" name="Start Date"></label><label>End Date<input type="date" name="End Date"></label><div class="class-filter-actions"><button type="button" id="clearClassFilters">Clear</button><button type="submit">⚑ Filter</button></div></form><section class="class-start-table"><header><span>▣</span><h1>Class Start Dashboard</h1></header><div class="table-scroll"><table><thead><tr><th>ID</th><th>Class</th><th>Program</th><th>Branch</th><th>Start Date</th><th>End Date</th><th>Total Students</th><th>Available Seats</th><th>Status</th><th>Action</th></tr></thead><tbody id="classStartRows">${rows.length?rows.map((r,index)=>`<tr data-values="${esc(JSON.stringify(r))}"><td>${index+1}</td><td>${esc(r.Class||'')}</td><td>${esc(r.Program||'')}</td><td>${esc(r.Branch||'')}</td><td>${esc(r['Start Date']||'')}</td><td>${esc(r['End Date']||'')}</td><td>${esc(r['Total Students']||'0')}</td><td>${esc(r['Available Seats']||'0')}</td><td><span class="badge good">${esc(r.Status||'Active')}</span></td><td><button class="mini-btn">•••</button></td></tr>`).join(''):'<tr><td colspan="10" class="class-empty">No classes found.</td></tr>'}</tbody></table></div></section></div>`}
function bindClassStart(){const form=$('#classStartFilters');if(!form)return;const body=$('#classStartRows'),records=()=>[...body.querySelectorAll('tr[data-values]')];const removeMessage=()=>$('#classFilterEmpty')?.remove();const filter=()=>{removeMessage();const data=Object.fromEntries(new FormData(form)),active=Object.values(data).some(Boolean);let visible=0;records().forEach(row=>{let record={};try{record=JSON.parse(row.dataset.values)}catch{record={}}const matches=Object.entries(data).every(([key,value])=>{if(!value)return true;const current=String(record[key]||'').trim();if(key==='Start Date')return !current||current>=value;if(key==='End Date')return !current||current<=value;return current.toLowerCase()===String(value).trim().toLowerCase()});row.hidden=!matches;if(matches)visible++});if(!visible&&records().length)body.insertAdjacentHTML('beforeend','<tr id="classFilterEmpty"><td colspan="10" class="class-empty">No classes match the selected filters.</td></tr>');if(!records().length)toast('No class records are available to filter');else toast(active?`${visible} class${visible===1?'':'es'} found`:'All classes shown')};form.onsubmit=e=>{e.preventDefault();filter()};$('#clearClassFilters').onclick=()=>{form.reset();removeMessage();records().forEach(row=>row.hidden=false);toast('Class filters cleared')}}
function studentDetailsView(){
 const rows=state.students,classes=[...new Set(rows.map(student=>student.class).filter(Boolean))];
 return `<div class="front-breadcrumb"><span>⌂ Dashboard</span><i>/</i><span>⚙ Student List</span><button type="button" data-go="dashboard">← Back</button></div><section class="student-details-panel"><div class="student-detail-filters"><label>Program<select id="detailProgram"><option value="">All Programs</option><option>General Education</option></select></label><label>Class<select id="detailClass"><option value="">All Classes</option>${classes.map(value=>`<option>${esc(value)}</option>`).join('')}</select></label><label>Time<select id="detailTime"><option value="">All Times</option><option>Morning</option><option>Afternoon</option><option>Evening</option></select></label></div><div class="student-detail-tools"><label>Show <select><option selected>10</option><option>25</option><option>50</option><option>100</option></select> entries</label><label>Search: <input id="studentDetailsSearch" type="search"></label></div><div class="table-scroll"><table><thead><tr><th>ID</th><th>Admission No</th><th>Student Name (Khmer)</th><th>Student Name (Chinese)</th><th>Student Name (English)</th><th>Guardian</th><th>Main Contact</th><th>Class</th><th>Time</th><th>Status</th><th>Action</th></tr></thead><tbody id="studentDetailsRows">${rows.length?rows.map((student,index)=>`<tr data-search="${esc([student.name,student.id,student.guardian,student.phone,student.class,student.status,student.time].join(' ').toLowerCase())}" data-class="${esc(student.class||'')}" data-time="${esc(student.time||'')}"><td>${index+1}</td><td>${esc(student.id)}</td><td>${esc(student.name_khmer||'')}</td><td>${esc(student.name_chinese||'')}</td><td>${esc(student.name)}</td><td><span class="student-guardian-badge">${esc(student.guardian||'No guardian yet')}</span></td><td>${esc(student.phone||'')}</td><td>${esc(student.class||'')}</td><td>${esc(student.time||'Morning(7:30AM - 11:00AM)')}</td><td><span class="student-status-pill ${student.status==='Active'?'active':'stopped'}">${student.status==='Active'?'Studying':'Stop studying'}</span></td><td class="student-detail-action"><button type="button" class="student-detail-more">•••⌄</button><div class="student-detail-menu" hidden><button type="button" data-detail="${esc(student.id)}">${iconSvg('eye','sr-icon action-icon')}Detail Info</button><button type="button" data-pay="${esc(student.id)}">${iconSvg('card','sr-icon action-icon')}Pay Tuition Fees</button><button type="button" data-edit="${esc(student.id)}">${iconSvg('edit','sr-icon action-icon')}Edit</button><button type="button" data-enable="${esc(student.id)}">${iconSvg(student.status==='Active'?'disable':'enable','sr-icon action-icon')}${student.status==='Active'?'Disable':'Enable'}</button><button type="button" class="danger" data-delete-detail="${esc(student.id)}">${iconSvg('delete','sr-icon action-icon')}Delete</button></div></td></tr>`).join(''):'<tr><td colspan="11" class="empty">No students found.</td></tr>'}</tbody></table></div><footer><span id="studentDetailsInfo">Showing ${rows.length?'1':'0'} to ${rows.length} of ${rows.length} ${rows.length===1?'entry':'entries'}</span><div class="front-pagination"><button disabled>Previous</button><b>1</b><button disabled>Next</button></div></footer></section>`
}
function selectedStudent(){return state.students.find(x=>String(x.id)===String(state.selectedStudentId))||state.students[0]||null}
