function bindAcademicAssignment(){const form=$('#academicAssignForm');if(!form)return;const classMode=form.dataset.mode==='class',key=classMode?'academicClassAssignments':'academicSubjectAssignments',seed=classMode?[{class:'KGE-K2',time:'Morning(7:30AM - 11:00AM)',teacher:'Testing Teacher',room:'110'},{class:'KGE-K3',time:'Morning(7:30AM - 11:00AM)',teacher:'Testing Teacher',room:'111'},{class:'KGE-K1',time:'Afternoon(1:00PM - 4:30PM)',teacher:'Testing Teacher',room:'125'}]:[{teacher:'Testing Teacher',khmer:'គណិតវិទ្យា',english:'Mathematics',chinese:'',code:'003'},{teacher:'Testing Teacher',khmer:'អង់គ្លេស',english:'English',chinese:'',code:'002'},{teacher:'Testing Teacher',khmer:'ប្រវត្តិវិទ្យា',english:'History',chinese:'',code:'001'}];state[key]=state[key]?.length?state[key]:seed;const draw=()=>{const q=$('#academicAssignSearch').value.toLowerCase(),rows=state[key].filter(r=>Object.values(r).join(' ').toLowerCase().includes(q));$('#academicAssignRows').innerHTML=rows.map((r,i)=>`<tr><td>${i+1}</td>${(classMode?[r.class,r.time,r.teacher,r.room]:[r.teacher,r.khmer,r.english,r.chinese,r.code]).map(x=>`<td>${esc(x||'')}</td>`).join('')}<td><button class="subject-actions">•••⌄</button></td></tr>`).join('');$('#academicAssignShowing').textContent=`Showing 1 to ${rows.length} of ${rows.length} entries`};form.onsubmit=e=>{e.preventDefault();state[key].push(Object.fromEntries(new FormData(form)));form.reset();draw();toast('Assignment saved')};$('#academicAssignSearch').oninput=draw;$('#academicAssignExcel').onclick=()=>{const csv=state[key].map(r=>Object.values(r).join(',')).join('\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download=key+'.csv';a.click();URL.revokeObjectURL(a.href)};draw()}
