function schedulePreviewMarkup(d){
 const logo=systemLogoMarkup('system-doc-logo');
 const classHeads=d.classes.map((c,i)=>`<th class="schedule-class c${i%6}">${esc(c.name)}<small>(${esc(c.room||'')})</small></th>`).join('');
 const body=d.lessons.map(r=>{if(r.kind==='break')return `<tr><th>${esc(r.am)}</th><th>${esc(r.pm)}</th><td colspan="${d.classes.length}" class="schedule-break">${esc(r.label)}</td></tr>`;if(r.kind==='gap')return `<tr><th>${esc(r.am)}</th><th>${esc(r.pm)}</th><td colspan="${d.classes.length}" class="schedule-gap"></td></tr>`;return `<tr><th>${esc(r.am)}</th><th>${esc(r.pm)}</th>${d.classes.map((c,i)=>{const cell=(r.cells||[])[i]||['Testing Teacher','',''];return `<td><b>${esc(cell[0]||'')}</b><small>${esc(cell[1]||'')}</small>${cell[2]?`<small>${esc(cell[2])}</small>`:''}</td>`}).join('')}</tr>`}).join('');
 return `<div class="schedule-sheet schedule-preview-sheet" id="schedulePrintArea"><header><div class="schedule-logo">${logo}</div><h1>Class Schedule, Academic Year ${esc(d.year)}<small>(${esc(d.session)}) Start on ${esc(d.start)}</small></h1><strong>${esc(d.building)}</strong></header><div class="table-scroll academic-schedule-table-wrap"><div class="academic-schedule-watermark" aria-hidden="true">${scheduleWatermarkLogoMarkup('academic-schedule-watermark-logo')}</div><table><colgroup><col class="schedule-time-col"><col class="schedule-time-col">${d.classes.map(()=>'<col class="schedule-class-col">').join('')}</colgroup><thead><tr><th colspan="2" class="schedule-time">Time</th>${classHeads}</tr><tr><th>AM</th><th>PM</th>${d.classes.map(()=>'<th></th>').join('')}</tr></thead><tbody>${body}</tbody></table></div><div class="schedule-notices"><div><b>Notices:</b>${String(d.englishNotices||'').split('\n').filter(Boolean).map(x=>`<p>${esc(x)}</p>`).join('')}</div><div><b>注意事项:</b>${String(d.chineseNotices||'').split('\n').filter(Boolean).map(x=>`<p>${esc(x)}</p>`).join('')}</div></div></div>`;
}
function scheduleCreatorView(){const d=scheduleDraft();const classOptions=['KGE-K1','KGE-K2','KGE-K3','BP-K1','BP-K2','BP-K3','P1','P2','P3','P4','P5','P6','S1','S2','S3','S4','S5','S6'];const staffRows=[...(state.records?.employees||[]),...(state.records?.staff||[])];const teacherNames=[...new Set(['Testing Teacher',...staffRows.map(r=>r['Full Name English']||r.Employee||r.Name||r.name||'').filter(Boolean)])];const subjectRows=(state.subjects&&state.subjects.length?state.subjects:subjectSeed)||[];const englishSubjects=[...new Set(['English','History','Mathematics','Science',...subjectRows.map(s=>s.english||'').filter(Boolean)])];const chineseSubjects=[...new Set(['中文',...subjectRows.map(s=>s.chinese||'').filter(Boolean)])];const optionList=(items,current,placeholder)=>`<option value="">${placeholder}</option>${items.map(x=>`<option value="${esc(x)}" ${String(x)===String(current)?'selected':''}>${esc(x)}</option>`).join('')}`;const lessonRows=d.lessons.map((r,ri)=>`<tr data-schedule-row="${ri}"><th><input class="sch-am" value="${esc(r.am)}"></th><th><input class="sch-pm" value="${esc(r.pm)}"></th>${r.kind==='lesson'?d.classes.map((c,ci)=>{const cell=(r.cells||[])[ci]||['','',''];return `<td class="schedule-entry-cell"><div class="schedule-entry-stack"><label><span>Teacher</span><select class="sch-teacher">${optionList(teacherNames,cell[0],'-- Teacher --')}</select></label><label><span>Subject Name (English)</span><select class="sch-subject-en">${optionList(englishSubjects,cell[1],'-- Subject --')}</select></label><label><span>Subject Name (Chinese)</span><select class="sch-subject-zh">${optionList(chineseSubjects,cell[2],'-- Subject --')}</select></label></div></td>`}).join(''):`<td colspan="${d.classes.length}"><input class="sch-break-label" value="${esc(r.label||'')}" placeholder="Break / activity"><input type="hidden" class="sch-kind" value="${r.kind}"></td>`}</tr>`).join('');return `<section class="schedule-create-page"><header class="schedule-create-title"><h1>Create Class Schedule</h1><p>Bilingual Program (English-Chinese)</p></header><form id="scheduleCreateForm"><section class="schedule-create-card"><div class="schedule-card-head"><div><h2>Schedule Details</h2><p>Set the heading information used on the printable schedule.</p></div><div class="schedule-create-actions"><label class="btn warning schedule-file-btn">${iconSvg('upload','sr-icon action-icon')} Choose File<input type="file" id="scheduleImportFile" accept=".csv" hidden></label><button type="button" class="btn success" id="importSchedule">${iconSvg('upload','sr-icon action-icon')} Import Schedule</button><button type="submit" class="btn warning">${iconSvg('save','sr-icon action-icon')} Save Schedule</button><button type="button" class="btn secondary" id="printSchedule">${iconSvg('print','sr-icon action-icon')} Print</button></div></div><div class="schedule-detail-grid"><label>Program<select name="program"><option>${esc(d.program)}</option><option>English-Chinese Program</option></select></label><label>Academic Year<select name="year"><option>${esc(d.year)}</option><option>2026-2027</option></select></label><label>Session<input name="session" value="${esc(d.session)}"></label><label>Start Date<input type="date" name="start" value="${esc(d.start)}"></label><label>Branch<select name="branch"><option>${esc(d.branch)}</option></select></label><label>Section<select name="section"><option>${esc(d.section)}</option><option>Morning</option><option>Afternoon</option></select></label><label>Building<input name="building" value="${esc(d.building)}"></label></div></section><section class="schedule-create-card"><div class="schedule-card-head"><h2>Class Columns</h2><button type="button" class="btn warning" id="addScheduleClass">${iconSvg('add','sr-icon action-icon')} Add Class</button></div><div class="schedule-class-editor" id="scheduleClassEditor">${d.classes.map((c,i)=>`<div class="schedule-class-edit" data-class-index="${i}"><button type="button" class="remove-schedule-class" title="Remove">${iconSvg('delete','sr-icon action-icon')}</button><label>Class ${i+1}<select class="sch-class-name">${classOptions.map(x=>`<option ${x===c.name?'selected':''}>${x}</option>`).join('')}</select></label><label>Room<input class="sch-class-room" value="${esc(c.room||'')}"></label></div>`).join('')}</div></section><section class="schedule-create-card"><h2>Lesson Entries</h2><div class="table-scroll"><table class="schedule-entry-table"><thead><tr><th>AM</th><th>PM</th>${d.classes.map(c=>`<th>${esc(c.name)}</th>`).join('')}</tr></thead><tbody id="scheduleLessonRows">${lessonRows}</tbody></table></div></section><section class="schedule-create-card"><h2>Notices</h2><div class="schedule-notice-editor"><label>English Notices<textarea name="englishNotices">${esc(d.englishNotices)}</textarea></label><label>Chinese Notices<textarea name="chineseNotices">${esc(d.chineseNotices)}</textarea></label></div></section></form><section class="schedule-preview-wrap">${schedulePreviewMarkup(d)}</section>${schedulePrintModalMarkup(d)}</section>`}
function schedulePrintModalMarkup(d){return `<div id="schedulePrintModal" class="schedule-print-modal" hidden><div class="schedule-print-dialog" role="dialog" aria-modal="true" aria-label="Class schedule print preview"><header class="schedule-print-head"><div><h2>${iconSvg('print','sr-icon section-icon')} Print Class Schedule</h2><p>Class Schedule, Academic Year ${esc(d.year)}</p></div><div class="schedule-print-actions"><button type="button" id="closeSchedulePrint" class="btn secondary">Close</button><button type="button" id="printScheduleNow" class="btn primary">${iconSvg('print','sr-icon action-icon')} Print</button></div></header><div class="schedule-print-preview">${schedulePreviewMarkup(d)}</div></div></div>`}
function classScheduleView(){if(state.scheduleCreateMode)return scheduleCreatorView();const d=scheduleDraft();return `<section class="schedule-page"><div class="schedule-filters"><select><option>English-Chinese Program</option></select><select><option>All Curriculum</option></select><select><option>All Classes</option></select><select><option>All Sections</option></select><select><option>All Branches</option></select><div><button id="scheduleSearch">${iconSvg('search','sr-icon action-icon')}</button><button id="createSchedule">${iconSvg('add','sr-icon action-icon')} Create Schedule</button><button id="printSchedule">${iconSvg('print','sr-icon action-icon')} Print</button></div></div>${schedulePreviewMarkup(d)}${schedulePrintModalMarkup(d)}</section>`}
function collectScheduleDraftFromPage(){const form=$('#scheduleCreateForm');if(!form)return scheduleDraft();const fd=Object.fromEntries(new FormData(form));const classes=[...document.querySelectorAll('.schedule-class-edit')].map(x=>({name:x.querySelector('.sch-class-name')?.value||'',room:x.querySelector('.sch-class-room')?.value||''}));const lessons=[...document.querySelectorAll('#scheduleLessonRows tr')].map(row=>{const am=row.querySelector('.sch-am')?.value||'',pm=row.querySelector('.sch-pm')?.value||'',breakLabel=row.querySelector('.sch-break-label');if(breakLabel)return {am,pm,kind:row.querySelector('.sch-kind')?.value||'break',label:breakLabel.value};return {am,pm,kind:'lesson',cells:[...row.querySelectorAll('td')].map(td=>[td.querySelector('.sch-teacher')?.value||'',td.querySelector('.sch-subject-en')?.value||'',td.querySelector('.sch-subject-zh')?.value||''])}});return {...fd,classes,lessons}}
function bindClassSchedule(){
 if($('#createSchedule'))$('#createSchedule').onclick=()=>{state.scheduleCreateMode=true;render();window.scrollTo(0,0)};
 if($('#printSchedule'))$('#printSchedule').onclick=()=>{const modal=$('#schedulePrintModal');if(modal){const latest=$('#scheduleCreateForm')?collectScheduleDraftFromPage():scheduleDraft();const preview=modal.querySelector('.schedule-print-preview');if(preview)preview.innerHTML=schedulePreviewMarkup(latest);modal.hidden=false;document.body.classList.add('schedule-print-preview-open')}else printCurrentView()};
 const closeSchedulePrint=()=>{const modal=$('#schedulePrintModal');if(modal)modal.hidden=true;document.body.classList.remove('schedule-print-preview-open')};
 if($('#closeSchedulePrint'))$('#closeSchedulePrint').onclick=closeSchedulePrint;
 if($('#printScheduleNow'))$('#printScheduleNow').onclick=()=>{document.body.classList.add('schedule-template-printing');try{window.print()}finally{setTimeout(()=>document.body.classList.remove('schedule-template-printing'),300)}};
 if($('#scheduleSearch'))$('#scheduleSearch').onclick=()=>toast('Schedule updated');
 const form=$('#scheduleCreateForm');if(!form)return;
 const collect=()=>{const fd=Object.fromEntries(new FormData(form));const classes=[...document.querySelectorAll('.schedule-class-edit')].map(x=>({name:x.querySelector('.sch-class-name').value,room:x.querySelector('.sch-class-room').value}));const lessons=[...document.querySelectorAll('#scheduleLessonRows tr')].map(row=>{const am=row.querySelector('.sch-am')?.value||'',pm=row.querySelector('.sch-pm')?.value||'',breakLabel=row.querySelector('.sch-break-label');if(breakLabel)return {am,pm,kind:row.querySelector('.sch-kind')?.value||'break',label:breakLabel.value};return {am,pm,kind:'lesson',cells:[...row.querySelectorAll('td')].map(td=>[td.querySelector('.sch-teacher')?.value||'',td.querySelector('.sch-subject-en')?.value||'',td.querySelector('.sch-subject-zh')?.value||''])}});return {...fd,classes,lessons}};
 const persistScheduleDraft=()=>{state.classScheduleDraft=collect();localStorage.setItem('scschool.classScheduleDraft',JSON.stringify(state.classScheduleDraft));return state.classScheduleDraft};
 const syncScheduleClassHeaders=()=>{const d=persistScheduleDraft();const headers=document.querySelectorAll('.schedule-entry-table thead tr:first-child th');d.classes.forEach((c,i)=>{const th=headers[i+2];if(th)th.textContent=c.name||`Class ${i+1}`});const wrap=document.querySelector('.schedule-preview-wrap');if(wrap)wrap.innerHTML=schedulePreviewMarkup(d)};
 form.oninput=e=>{const d=persistScheduleDraft();const wrap=document.querySelector('.schedule-preview-wrap');if(wrap)wrap.innerHTML=schedulePreviewMarkup(d);if(e.target.matches('.sch-class-name'))syncScheduleClassHeaders()};
 form.onchange=e=>{if(e.target.matches('.sch-class-name,.sch-class-room'))syncScheduleClassHeaders()};
 form.onsubmit=e=>{e.preventDefault();const d=persistScheduleDraft();toast('Class schedule saved');const wrap=document.querySelector('.schedule-preview-wrap');if(wrap)wrap.innerHTML=schedulePreviewMarkup(d)};
 document.querySelectorAll('.remove-schedule-class').forEach(b=>b.onclick=()=>{if(document.querySelectorAll('.schedule-class-edit').length<=1)return toast('Keep at least one class');state.classScheduleDraft=collect();const idx=Number(b.closest('.schedule-class-edit').dataset.classIndex);state.classScheduleDraft.classes.splice(idx,1);state.classScheduleDraft.lessons.forEach(r=>{if(r.cells)r.cells.splice(idx,1)});localStorage.setItem('scschool.classScheduleDraft',JSON.stringify(state.classScheduleDraft));render()});
 $('#addScheduleClass').onclick=()=>{state.classScheduleDraft=collect();const used=new Set(state.classScheduleDraft.classes.map(c=>c.name));const options=['KGE-K1','KGE-K2','KGE-K3','BP-K1','BP-K2','BP-K3','P1','P2','P3','P4','P5','P6','S1','S2','S3','S4','S5','S6'];const nextName=options.find(x=>!used.has(x))||`Class ${state.classScheduleDraft.classes.length+1}`;state.classScheduleDraft.classes.push({name:nextName,room:''});state.classScheduleDraft.lessons.forEach(r=>{if(r.kind==='lesson'){r.cells=r.cells||[];r.cells.push(['','',''])}});localStorage.setItem('scschool.classScheduleDraft',JSON.stringify(state.classScheduleDraft));render()};
 $('#importSchedule').onclick=()=>{const file=$('#scheduleImportFile').files[0];if(!file)return toast('Choose a CSV file first');const reader=new FileReader();reader.onload=()=>{const lines=String(reader.result||'').trim().split(/\r?\n/).filter(Boolean);if(lines.length<2)return toast('CSV file is empty');const rows=lines.slice(1).map(line=>line.split(','));state.classScheduleDraft=collect();state.classScheduleDraft.lessons=rows.map(r=>({am:r[0]||'',pm:r[1]||'',kind:(r[2]||'lesson').trim(),label:r[3]||'',cells:state.classScheduleDraft.classes.map((c,i)=>[r[4+i*3]||'Testing Teacher',r[5+i*3]||'',r[6+i*3]||''])}));localStorage.setItem('scschool.classScheduleDraft',JSON.stringify(state.classScheduleDraft));render();toast('Schedule imported')};reader.readAsText(file)};
}

function evaluationView(){const mode=state.page==='academic-monthly'?'monthly':state.page==='academic-quarterly'?'quarterly':'semester',meta={monthly:{title:'Monthly Evaluation ( Report )',tab:'Student Report',panel:'Monthly Evaluation Results',report:"STUDENT'S MONTHLY EVALUATION",period:'Academic Year 2025-2026 (March)'},quarterly:{title:'Quarterly Exam ( Transcript )',tab:'Student Transcript',panel:'Quarter Results',report:'1st QUARTER EXAM',period:'Academic Year 2025-2026'},semester:{title:'Semester Exam ( Transcript )',tab:'Student Report Card',panel:'Semester Results',report:'1st SEMESTER',period:'Academic Year 2025-2026'}}[mode],skills=['Homework Completion','Student Personality','Work Independently','Talk Respectfully','Student Attention','Be on time','Communication','Reading','Quality'],monthlyGroups=['English','Chinese','Math'],examSkills=['Reading','Writing','Speaking','Listening','Quiz','H/W','Attendance'];let columns='';if(mode==='monthly')columns=monthlyGroups.map(group=>`<th colspan="9" class="eval-group">${group}</th>`).join('');else if(mode==='quarterly')columns='<th colspan="4" class="eval-group">ENGLISH / 英文</th><th colspan="2" class="eval-group">Monthly Quiz</th><th colspan="2" class="eval-group">Monthly Homework</th><th colspan="2" class="eval-group">Monthly Attendance</th><th colspan="3" class="eval-yellow">Quarter Result</th>';else columns='<th colspan="7" class="eval-quarter">First Quarter<br>ENGLISH / 英文</th><th colspan="7" class="eval-quarter">Second Quarter<br>ENGLISH / 英文</th>';const detail=mode==='monthly'?monthlyGroups.flatMap(()=>skills):mode==='quarterly'?['Reading','Writing','Speaking','Listening','Quiz','H1','H2','Att1','Att2','Total Quiz','Total H1','Total Att']:examSkills.concat(examSkills);return `<section class="evaluation-page"><header><h1>${meta.title}</h1><p>Bilingual Program ( English-Chinese )</p></header><nav class="evaluation-tabs"><button>Master Input</button><button>Import Excel</button><button>Result on Board</button><button>${meta.tab}</button><button>Export PDF / Excel</button></nav><form id="evaluationFilters"><label>Class<select name="class"><option>All</option><option>KGE-K1</option><option>KGE-K2</option></select></label><label>Section<select name="section"><option>All</option><option>Morning</option><option>Afternoon</option></select></label><label>Session<select name="session"><option>2025-2026</option></select></label><div><button type="submit">⚑ Filter</button><button type="button" id="evaluationImport">↥ Import</button><button type="button" id="evaluationTemplate">↧ Template</button><button type="button" id="evaluationPdf">▧ Export PDF</button><button type="button" id="evaluationExcel">▧ Export Excel</button></div></form><section class="evaluation-results"><h2>☷ ${meta.panel}</h2><div class="evaluation-sheet"><div class="evaluation-report-head"><span class="evaluation-logo">${systemLogoMarkup('system-doc-logo')}</span><div><b>${meta.report}</b><strong>${meta.period}</strong></div></div><div class="evaluation-meta"><span>Branch: iS-01 (Odem)</span><span>Level: All</span><span>Shift: Morning &amp; Afternoon</span></div><div class="table-scroll"><table><thead><tr><th>No<br>序号</th><th>ID No<br>学生编号</th><th>Khmer Name<br>柬文名</th><th>Latin Name<br>英文名</th><th>Chinese Name<br>中文名</th><th>Sex</th>${columns}</tr><tr>${'<th></th>'.repeat(6)}${detail.map(x=>`<th class="vertical-head"><span>${x}</span></th>`).join('')}</tr></thead><tbody><tr><td>1</td><td>IIS.003</td><td>Sonav</td><td>Sonav</td><td></td><td>Female</td>${detail.map(()=>'<td>0</td>').join('')}</tr><tr><td>2</td><td>IIS.009</td><td>test</td><td>test</td><td></td><td>Male</td>${detail.map(()=>'<td>0</td>').join('')}</tr></tbody></table></div></div></section></section>`}
function bindEvaluation(){const form=$('#evaluationFilters');if(!form)return;form.onsubmit=e=>{e.preventDefault();toast('Evaluation results filtered')};$('#evaluationImport').onclick=()=>toast('Choose an Excel file to import');$('#evaluationTemplate').onclick=()=>toast('Template download prepared');$('#evaluationPdf').onclick=()=>printCurrentView();$('#evaluationExcel').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['ID,Khmer Name,Latin Name,Sex\nIIS.003,Sonav,Sonav,Female\nIIS.009,test,test,Male'],{type:'text/csv'}));a.download='evaluation-results.csv';a.click();URL.revokeObjectURL(a.href)}}
let teachingCreateMode=false;
const teachingDefaultRows=[
  {am:'7:00-7:30',pm:'12:50-1:20',type:'break',label:'Snack Lineup'},
  {am:'7:30-7:40',pm:'1:20-1:30',type:'break',label:''},
  {am:'7:40-8:30',pm:'1:40-2:30',type:'lesson',teacher:'Testing Teacher',ta:'TA',days:[['English','Reading'],['English','Writing'],['English','Speaking'],['English','Writing'],['English','Writing']]},
  {am:'8:30-8:45',pm:'2:30-2:45',type:'break',label:'Break-Time'},
  {am:'8:45-9:30',pm:'2:45-3:30',type:'lesson',teacher:'Testing Teacher',ta:'TA',days:[['English','Reading'],['English','Writing'],['English','Speaking'],['English','Writing'],['English','Writing']]},
  {am:'9:30-9:45',pm:'3:30-3:45',type:'break',label:'Break-Time'},
  {am:'9:45-10:00',pm:'3:45-4:30',type:'lesson',teacher:'Testing Teacher',ta:'TA',days:[['English','Writing'],['English','Writing'],['English','Writing'],['English','Reading'],['English','Speaking']]}
];
function teachingPrintTemplate(data={}){
  const school=schoolIdentityData(), logo=school.logo||school.invoiceLogo;
  const d={title:'Teaching Schedule for Academic Year',year:'2025-2026',program:'All Programs',className:'KGE-K2',branch:'SC1',date:'2026-07-13',days:['Mon','Tue','Wed','Thu','Fri'],rows:teachingDefaultRows,noticesEn:'* This schedule will be affected on July 2, 2026.\n* The first week of September will be the welcoming week, teaching schedule providing, classroom rules instruction, students\' materials checkup and getting to know each other.\n* Homework will be assigned from course book on Mondays, Wednesdays and Fridays.\n* Tuesdays and Thursdays will be an extra assignment for students.\n* Dancing & Singing will be scheduled on every 1st and 3rd week.',noticesZh:'* 此时间表将于 2026年 9 月 9 日生效。\n* 9 月的第一周将是欢迎周，提供教学时间表、课堂规则指导、学生材料检查和相互了解。\n* 将在周一、周三和周五根据课本布置家庭作业。',footer:'Subject to be changed at any necessary time !',...data};
  const rowHtml=d.rows.map(r=>r.type==='break'
    ? `<tr class="teaching-break"><th>${esc(r.am)}<br>${esc(r.pm)}</th><td colspan="7">${esc(r.label||'')}</td></tr>`
    : `<tr><th>${esc(r.am)}<br>${esc(r.pm)}</th><td><b>${esc(r.teacher||'')}</b></td><td>${esc(r.ta||'')}</td>${(r.days||[]).map(x=>`<td><b>${esc((x&&x[0])||'')}</b><small>${esc((x&&x[1])||'')}</small></td>`).join('')}</tr>`).join('');
  return `<article class="teaching-sheet teaching-print-sheet"><div class="teaching-title"><span class="teaching-logo"><img class="system-doc-logo" src="${esc(logo)}" alt="School logo"></span><h2>${esc(d.title)} ${esc(d.year)}</h2><strong>Branch: ${esc(d.branch)}</strong></div><p class="teaching-address">${schoolContactLineMarkup('teaching-system-contact')}</p><div class="teaching-badges"><b>Class: ${esc(d.className)}</b><strong>${esc(d.date)}</strong></div><div class="table-scroll academic-schedule-table-wrap teaching-schedule-table-wrap"><div class="academic-schedule-watermark" aria-hidden="true">${scheduleWatermarkLogoMarkup('academic-schedule-watermark-logo')}</div><table><thead><tr><th>Time</th><th>Teacher</th><th>TA</th>${d.days.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${rowHtml}</tbody></table></div><div class="teaching-notices"><div><b>Notices:</b>${esc(d.noticesEn).split('\n').map(x=>`<p>${x}</p>`).join('')}<strong>✎ ${esc(d.footer)}</strong></div><div>${esc(d.noticesZh).split('\n').map(x=>`<p>${x}</p>`).join('')}</div></div></article>`;
}
function teachingScheduleListView(){return `<section class="teaching-page"><header><h1>Teaching Schedule</h1><p>Bilingual Program ( English-Chinese )</p></header><form id="teachingFilters"><select><option>All Branches</option><option>SC1</option></select><select><option>All Curriculum</option></select><select><option>All Classes</option><option>KGE-K2</option></select><select><option>All Time</option><option>Morning</option><option>Afternoon</option></select><button type="submit">⌕</button><span></span><button type="button" id="createTeaching">＋ Create Teaching Schedule</button><button type="button" id="printTeaching">${iconSvg('print','sr-icon action-icon')} Print</button></form>${teachingPrintTemplate()}<div id="teachingPrintModal" class="student-timetable-print-modal" hidden><div class="student-timetable-print-dialog"><header class="student-timetable-print-head"><div><strong>${iconSvg('print','sr-icon')} Teaching Schedule Print Preview</strong><small>Only the Teaching Schedule page below will be printed.</small></div><div><button type="button" id="closeTeachingPrint" class="system-icon-button secondary"><span>Close</span></button><button type="button" id="printTeachingNow" class="system-icon-button primary">${iconSvg('print','sr-icon action-icon')}<span>Print</span></button></div></header><div class="student-timetable-print-preview">${teachingPrintTemplate()}</div></div></div></section>`}
function teachingScheduleCreateView(){const school=schoolIdentityData(), teacherOpts=['Testing Teacher','Teacher 1','Teacher 2'].map(x=>`<option>${x}</option>`).join(''), subjectOpts=['English','Reading','Writing','Speaking','History','Mathematics'].map(x=>`<option>${x}</option>`).join('');
  const rows=teachingDefaultRows.map((r,i)=>{if(r.type==='break')return `<tr data-ts-row="${i}" data-type="break"><td><input class="ts-am" value="${esc(r.am)}"></td><td><input class="ts-pm" value="${esc(r.pm)}"></td><td><select class="ts-type"><option selected>Break</option><option>Lesson</option></select></td><td colspan="8"><input class="ts-label wide" value="${esc(r.label||'')}" placeholder="Activity label / Break-Time"></td></tr>`;return `<tr data-ts-row="${i}" data-type="lesson"><td><input class="ts-am" value="${esc(r.am)}"></td><td><input class="ts-pm" value="${esc(r.pm)}"></td><td><select class="ts-type"><option>Break</option><option selected>Lesson</option></select></td><td><select class="ts-teacher">${teacherOpts}</select></td><td><input class="ts-ta" value="${esc(r.ta||'TA')}" placeholder="TA"></td><td></td>${r.days.map((x,di)=>`<td><select class="ts-day-subject" data-day="${di}">${subjectOpts.replace(`>${x[0]}<`,` selected>${x[0]}<`)}</select><select class="ts-day-lesson" data-day="${di}">${subjectOpts.replace(`>${x[1]}<`,` selected>${x[1]}<`)}</select></td>`).join('')}</tr>`}).join('');
  return `<section class="teaching-create-page"><header><h1>Create Teaching Schedule</h1><p>Bilingual Program ( English-Chinese )</p></header><section class="ts-panel"><div class="ts-panel-head"><div><h2>Schedule Details</h2><p>Create the printable teaching schedule.</p></div><div><button type="button" id="saveTeachingCreate" class="btn-orange">${iconSvg('save','sr-icon action-icon')} Save Schedule</button><button type="button" id="viewTeachingCreate" class="btn-light">${iconSvg('eye','sr-icon action-icon')} View Schedule</button><button type="button" id="printTeachingCreate" class="btn-light">${iconSvg('print','sr-icon action-icon')} Print</button></div></div><div class="ts-details-grid"><label>Title<input id="tsTitle" value="Teaching Schedule for Academic Year"></label><label>Academic Year<input id="tsYear" value="2025-2026"></label><label>Program<select id="tsProgram"><option>All Programs</option></select></label><label>Class<select id="tsClass"><option>KGE-K2</option><option>KGE-K1</option><option>KGE-K3</option></select></label><label>Branch<select id="tsBranch"><option>SC1</option></select></label><label>Date<input type="date" id="tsDate" value="2026-07-13"></label><label class="span-3">Address<input value="${esc(school.address||'')}" readonly></label><label>Tel<input value="${esc(school.phone||'')}" readonly></label><label>Email<input value="${esc(school.email||'')}" readonly></label><label>Website<input value="${esc(school.website||'')}" readonly></label><label class="span-all">Days ( separate with | )<input id="tsDays" value="Mon|Tue|Wed|Thu|Fri"></label></div></section><section class="ts-panel"><h2>Schedule Rows</h2><div class="table-scroll"><table class="ts-edit-table"><thead><tr><th>AM</th><th>PM</th><th>Type</th><th>Teacher</th><th>TA</th><th>Activity Label</th><th>Mon</th><th>Tue</th><th>Wed</th><th>Thu</th><th>Fri</th></tr></thead><tbody>${rows}</tbody></table></div></section><section class="ts-panel ts-notices-editor"><label>Notices ( English )<textarea id="tsNoticesEn">* This schedule will be affected on July 2, 2026.\n* The first week of September will be the welcoming week, teaching schedule providing, classroom rules instruction, students' materials checkup and getting to know each other.\n* Homework will be assigned from course book on Mondays, Wednesdays and Fridays.\n* Tuesdays and Thursdays will be an extra assignment for students.\n* Dancing & Singing will be scheduled on every 1st and 3rd week.</textarea></label><label>Notices ( Chinese )<textarea id="tsNoticesZh">* 此时间表将于 2026年 9 月 9 日生效。\n* 9 月的第一周将是欢迎周，提供教学时间表、课堂规则指导、学生材料检查和相互了解。\n* 将在周一、周三和周五根据课本布置家庭作业。</textarea></label><label class="span-all">Footer Note<input id="tsFooter" value="Subject to be changed at any necessary time !"></label></section><section id="teachingCreatePreview" class="ts-preview-wrap">${teachingPrintTemplate()}</section><div id="teachingPrintModal" class="student-timetable-print-modal" hidden><div class="student-timetable-print-dialog"><header class="student-timetable-print-head"><div><strong>${iconSvg('print','sr-icon')} Teaching Schedule Print Preview</strong><small>Review the schedule clearly before printing.</small></div><div><button type="button" id="closeTeachingPrint" class="system-icon-button secondary"><span>Close</span></button><button type="button" id="printTeachingNow" class="system-icon-button primary">${iconSvg('print','sr-icon action-icon')}<span>Print</span></button></div></header><div class="student-timetable-print-preview" id="teachingPrintPreviewBody"></div></div></div></section>`}
function teachingScheduleView(){return teachingCreateMode?teachingScheduleCreateView():teachingScheduleListView()}
function collectTeachingCreateData(){const days=($('#tsDays')?.value||'Mon|Tue|Wed|Thu|Fri').split('|').map(x=>x.trim()).filter(Boolean).slice(0,5);const rows=[...document.querySelectorAll('.ts-edit-table tbody tr')].map(tr=>{const type=tr.querySelector('.ts-type')?.value==='Lesson'?'lesson':'break',base={am:tr.querySelector('.ts-am')?.value||'',pm:tr.querySelector('.ts-pm')?.value||'',type};if(type==='break')return {...base,label:tr.querySelector('.ts-label')?.value||''};return {...base,teacher:tr.querySelector('.ts-teacher')?.value||'',ta:tr.querySelector('.ts-ta')?.value||'',days:[...tr.querySelectorAll('td:nth-child(n+7)')].slice(0,5).map(td=>[td.querySelector('.ts-day-subject')?.value||'',td.querySelector('.ts-day-lesson')?.value||''])}});return {title:$('#tsTitle')?.value||'Teaching Schedule for Academic Year',year:$('#tsYear')?.value||'2025-2026',program:$('#tsProgram')?.value||'',className:$('#tsClass')?.value||'',branch:$('#tsBranch')?.value||'',date:$('#tsDate')?.value||'',days,rows,noticesEn:$('#tsNoticesEn')?.value||'',noticesZh:$('#tsNoticesZh')?.value||'',footer:$('#tsFooter')?.value||''}}
function openTeachingPrint(data){const modal=$('#teachingPrintModal');if(!modal)return;const body=$('#teachingPrintPreviewBody')||modal.querySelector('.student-timetable-print-preview');body.innerHTML=teachingPrintTemplate(data);modal.hidden=false;document.body.classList.add('modal-open')}
function bindTeachingSchedule(){if(state.page!=='academic-teaching-schedule')return;const form=$('#teachingFilters');if(form){form.onsubmit=e=>{e.preventDefault();toast('Teaching schedule updated')};$('#createTeaching').onclick=()=>{teachingCreateMode=true;render()};$('#printTeaching').onclick=()=>openTeachingPrint({});}
  if(teachingCreateMode){const refresh=()=>{const p=$('#teachingCreatePreview');if(p)p.innerHTML=teachingPrintTemplate(collectTeachingCreateData())};document.querySelectorAll('.teaching-create-page input,.teaching-create-page select,.teaching-create-page textarea').forEach(el=>{el.addEventListener('input',refresh);el.addEventListener('change',refresh)});$('#saveTeachingCreate').onclick=()=>{localStorage.setItem('sr.teachingSchedule',JSON.stringify(collectTeachingCreateData()));toast('Teaching schedule saved')};$('#viewTeachingCreate').onclick=()=>{refresh();document.querySelector('#teachingCreatePreview')?.scrollIntoView({behavior:'smooth'})};$('#printTeachingCreate').onclick=()=>openTeachingPrint(collectTeachingCreateData());refresh()}
  $('#closeTeachingPrint')?.addEventListener('click',()=>{$('#teachingPrintModal').hidden=true;document.body.classList.remove('modal-open')});$('#printTeachingNow')?.addEventListener('click',()=>{document.body.classList.add('teaching-template-printing');try{window.print()}finally{setTimeout(()=>document.body.classList.remove('teaching-template-printing'),300)}})}

let khmerScheduleCreateMode=false;
