function bindAttendanceByDate(){if(!$('#attendanceDateRows'))return;const draw=()=>{const q=$('#attendanceDateSearch').value.toLowerCase(),records=Object.entries(state.attendance||{}).map(([id,status])=>{const student=state.students.find(s=>String(s.id)===String(id));return student?{...student,status}:null}).filter(Boolean).filter(row=>Object.values(row).join(' ').toLowerCase().includes(q));$('#attendanceDateRows').innerHTML=records.length?records.map((row,i)=>`<tr><td>${i+1}</td><td>Testing Teacher</td><td>${esc(row.name)}</td><td>${esc(row.name)}</td><td>—</td><td>${esc(row.phone)}</td><td>${esc(row.class)}</td><td>—</td><td>${esc(row.status)}</td><td></td></tr>`).join(''):'<tr><td colspan="10" class="empty">No data available in table</td></tr>';$('#attendanceDateShowing').textContent=`Showing ${records.length?1:0} to ${records.length} of ${records.length} entries`};$('#attendanceDateSearch').oninput=draw;$('#attendanceDateFilters').onchange=draw;$('#recordStudentAttendance').onclick=()=>navigate('attendance-record');draw()}
