function bindApproveLeaves(){if(!$('#leaveRows'))return;state.leaveRequests=state.leaveRequests||[{name:'New',class:'KGE-K2',section:'Morning(7:30AM - 11:00AM)',apply:'2026-07-10',from:'2026-07-10',to:'2026-07-10',status:'Pending',approved:'-'},{name:'New',class:'KGE-K3',section:'Morning(7:30AM - 11:00AM)',apply:'2026-07-10',from:'2026-07-10',to:'2026-07-10',status:'Approved',approved:'-'}];let filters={};const draw=()=>{const rows=state.leaveRequests.filter(r=>(!filters.class||r.class===filters.class)&&(!filters.status||r.status===filters.status));$('#leaveRows').innerHTML=rows.map((r,i)=>`<tr><td>${r.name}</td><td>${r.class}</td><td>${r.section}</td><td>${r.apply}</td><td>${r.from}</td><td>${r.to}</td><td><span class="leave-status ${r.status.toLowerCase()}">${r.status}</span></td><td>${r.approved}</td><td><button class="leave-view" data-index="${i}">View</button></td></tr>`).join('');document.querySelectorAll('.leave-view').forEach(b=>b.onclick=()=>{const r=rows[Number(b.dataset.index)];if(r.status==='Pending'&&confirm('Approve this leave request?')){r.status='Approved';r.approved='Admin';draw()}else toast(`${r.name}: ${r.from} to ${r.to}`)})};$('#leaveFilters').onsubmit=e=>{e.preventDefault();filters=Object.fromEntries(new FormData(e.currentTarget));draw()};$('#leaveFilters').onreset=()=>{filters={};setTimeout(draw)};$('#addLeave').onclick=()=>{state.leaveRequests.unshift({name:'New',class:'KGE-K2',section:'Morning(7:30AM - 11:00AM)',apply:'2026-08-19',from:'2026-08-19',to:'2026-08-19',status:'Pending',approved:'-'});draw();toast('Leave request added')};$('#exportLeaves').onclick=()=>{const csv=['Student,Class,Section,Apply Date,From,To,Status,Approved By',...state.leaveRequests.map(r=>Object.values(r).join(','))].join('\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='approve-leaves.csv';a.click();URL.revokeObjectURL(a.href)};draw()}
function stockAdjustmentView(){return `<section class="stock-adjustment-page"><div class="front-breadcrumb"><span>⌂ Dashboard</span><i>/</i><span>＋ Add Stock Adjustment</span><button data-go="dashboard">← Back</button></div><form id="stockAdjustmentForm"><h2>Add Stock Adjustment</h2><p><i>Fields marked with <em>*</em> are required.</i></p><div class="stock-adjustment-grid"><label>Adjustment Date <em>*</em><input type="date" name="date" value="2026-08-19" required></label><label>Warehouse <em>*</em><select name="warehouse" required><option value=""></option><option>Main Warehouse</option></select></label><label>Reference No <em>*</em><input name="reference" required></label><label>Document<input type="file" name="document"></label></div><label class="stock-product-select">Select product <em>*</em><select id="adjustmentProduct"><option value="">Select product</option><option value="Notebook|NB001|Piece">Notebook</option><option value="School Bag|SB002|Piece">School Bag</option><option value="Uniform|UF003|Set">Uniform</option></select></label><div class="table-scroll"><table><thead><tr><th>No</th><th>Code</th><th>Product Name</th><th>Quantity</th><th>Unit</th><th>Type</th><th>Action</th></tr></thead><tbody id="adjustmentProductRows"><tr><td colspan="7" class="empty">No products added</td></tr></tbody></table></div><label class="stock-note">Note<textarea name="note"></textarea></label><button class="stock-save" type="submit">▣ Save</button></form></section>`}
