function bindStockAdjustment(){const form=$('#stockAdjustmentForm');if(!form)return;const products=[];const draw=()=>{$('#adjustmentProductRows').innerHTML=products.length?products.map((p,i)=>`<tr><td>${i+1}</td><td>${p.code}</td><td>${p.name}</td><td><input class="stock-qty" type="number" min="1" value="1"></td><td>${p.unit}</td><td><select><option>Add</option><option>Subtract</option></select></td><td><button class="remove-stock-product" data-index="${i}">Delete</button></td></tr>`).join(''):'<tr><td colspan="7" class="empty">No products added</td></tr>';document.querySelectorAll('.remove-stock-product').forEach(b=>b.onclick=()=>{products.splice(Number(b.dataset.index),1);draw()})};$('#adjustmentProduct').onchange=e=>{if(!e.target.value)return;const [name,code,unit]=e.target.value.split('|');if(!products.some(p=>p.code===code))products.push({name,code,unit});e.target.value='';draw()};form.onsubmit=e=>{e.preventDefault();if(!products.length)return toast('Please add at least one product');state.stockCounts=state.stockCounts||[];const data=Object.fromEntries(new FormData(form));state.stockCounts.unshift({date:data.date,reference:data.reference,warehouse:data.warehouse,categories:'All',brand:'—',type:'Adjustment',initial:'—',final:'—'});toast('Stock adjustment saved');navigate('inventory-count')};draw()}
function bindStockCount(){if(!$('#stockCountRows'))return;state.stockCounts=state.stockCounts||[];const draw=()=>{const q=$('#stockCountSearch').value.toLowerCase(),rows=state.stockCounts.filter(r=>Object.values(r).join(' ').toLowerCase().includes(q));$('#stockCountRows').innerHTML=rows.map((r,i)=>`<tr><td><input type="checkbox"></td><td>${r.date}</td><td>${r.reference}</td><td>${r.warehouse}</td><td>${r.categories}</td><td>${r.brand}</td><td>${r.type}</td><td>${r.initial}</td><td>${r.final}</td><td><button class="subject-actions">•••⌄</button></td></tr>`).join('')};$('#stockCountSearch').oninput=draw;$('#addStockCount').onclick=()=>navigate('inventory-adjustment');$('#exportStockCount').onclick=()=>{const csv=['Date,References,Warehouse,Categories,Brand,Type,Initial File,Final File',...state.stockCounts.map(r=>Object.values(r).join(','))].join('\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='stock-count.csv';a.click();URL.revokeObjectURL(a.href)};draw()}
function stockTransferView(){return `<section class="stock-transfer-page"><div class="front-breadcrumb"><span>⌂ Dashboard</span><i>/</i><span>⚙ Transfer</span><i>/</i><span>☷ List Stock Transfer</span><button data-go="dashboard">← Back</button></div><section><form id="stockTransferForm" hidden><label>Date<input type="date" name="date" value="2026-08-19" required></label><label>References<input name="reference" required></label><label>From Branch<select name="from" required><option>SC1</option><option>HQ</option></select></label><label>To Branch<select name="to" required><option>HQ</option><option>SC1</option></select></label><label>Shipping Fee<input type="number" name="shipping" min="0" value="0"></label><label>Miscellaneous<input type="number" name="misc" min="0" value="0"></label><div><button type="submit">▣ Save</button><button type="button" id="cancelTransfer">Cancel</button></div></form><div class="stock-transfer-tools"><button id="addTransfer">＋ Add New</button><button id="exportTransfers">↧ Download (Excel)</button><button class="stock-number">◉ <i>Number to Show</i>⌄</button><label><input id="transferSearch" placeholder="Search"><button>⌕</button></label></div><div class="table-scroll"><table><thead><tr><th>No</th><th>Date</th><th>References</th><th>From Branch (SO / SSO / Agency)</th><th>To Branch (SO / SSO / Agency)</th><th>Shipping Fee</th><th>Miscellaneous</th><th>Action</th></tr></thead><tbody id="transferRows"></tbody></table></div><footer>Page 1 Of 1</footer></section></section>`}
function bindStockTransfer(){if(!$('#transferRows'))return;state.stockTransfers=state.stockTransfers||[];const form=$('#stockTransferForm'),draw=()=>{const q=$('#transferSearch').value.toLowerCase(),rows=state.stockTransfers.filter(r=>Object.values(r).join(' ').toLowerCase().includes(q));$('#transferRows').innerHTML=rows.length?rows.map((r,i)=>`<tr><td>${i+1}</td><td>${r.date}</td><td>${r.reference}</td><td>${r.from}</td><td>${r.to}</td><td>${Number(r.shipping).toFixed(2)}</td><td>${Number(r.misc).toFixed(2)}</td><td><button class="subject-actions">•••⌄</button></td></tr>`).join(''):'<tr><td colspan="8" class="empty">No Transfers Found</td></tr>'};$('#addTransfer').onclick=()=>form.hidden=false;$('#cancelTransfer').onclick=()=>form.hidden=true;form.onsubmit=e=>{e.preventDefault();state.stockTransfers.unshift(Object.fromEntries(new FormData(form)));form.reset();form.hidden=true;draw();toast('Stock transfer saved')};$('#transferSearch').oninput=draw;$('#exportTransfers').onclick=()=>{const csv=['No,Date,References,From Branch,To Branch,Shipping Fee,Miscellaneous',...state.stockTransfers.map((r,i)=>[i+1,...Object.values(r)].join(','))].join('\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='stock-transfers.csv';a.click();URL.revokeObjectURL(a.href)};draw()}
function printBarcodeView(){return `<section class="barcode-page"><div class="front-breadcrumb"><span>⌂ Dashboard</span><i>/</i><span>▣ Print Barcode</span><button class="barcode-back" data-go="inventory-count">← Back</button></div><form id="barcodeForm"><label>Add Product <em>*</em><div class="barcode-product"><button type="button" id="barcodeScan">▥</button><select id="barcodeProduct"><option value=""></option><option value="Notebook|NB001|2.00|2.50">Notebook</option><option value="School Bag|SB002|12.00|15.00">School Bag</option><option value="Uniform|UF003|18.00|20.00">Uniform</option></select></div></label><div class="table-scroll"><table><thead><tr><th>No</th><th>Product Name</th><th>Code</th><th>Quantity</th><th>Action</th></tr></thead><tbody id="barcodeRows"></tbody></table></div><fieldset><legend>Print By Type:</legend><label><input type="checkbox" name="printName" checked> Product Name</label><label><input type="checkbox" name="printCode" checked> Code</label><label><input type="checkbox" name="printPrice"> Price</label><label><input type="checkbox" name="printAdvertising"> Advertising Price</label></fieldset><label class="barcode-paper">Paper Size<select name="paper" required><option value=""></option><option>A4</option><option>50mm × 30mm</option><option>40mm × 25mm</option></select></label><button class="barcode-save" type="submit">▣ Save</button></form><section id="barcodePrintArea" hidden></section></section>`}
function bindPrintBarcode(){const form=$('#barcodeForm');if(!form)return;const products=[];const draw=()=>{$('#barcodeRows').innerHTML=products.length?products.map((p,i)=>`<tr><td>${i+1}</td><td>${p.name}</td><td>${p.code}</td><td><input class="barcode-quantity" data-index="${i}" type="number" min="1" value="${p.quantity}"></td><td><button class="barcode-remove" data-index="${i}">Delete</button></td></tr>`).join(''):'<tr><td colspan="5" class="empty">No products added</td></tr>';document.querySelectorAll('.barcode-remove').forEach(b=>b.onclick=()=>{products.splice(Number(b.dataset.index),1);draw()});document.querySelectorAll('.barcode-quantity').forEach(input=>input.oninput=()=>products[Number(input.dataset.index)].quantity=Math.max(1,Number(input.value)||1))};$('#barcodeProduct').onchange=e=>{if(!e.target.value)return;const [name,code,price,advertising]=e.target.value.split('|');if(!products.some(p=>p.code===code))products.push({name,code,price,advertising,quantity:1});e.target.value='';draw()};$('#barcodeScan').onclick=()=>$('#barcodeProduct').focus();form.onsubmit=e=>{e.preventDefault();if(!products.length)return toast('Please add a product');if(!form.paper.value)return toast('Please select a paper size');const showName=form.printName.checked,showCode=form.printCode.checked,showPrice=form.printPrice.checked,showAd=form.printAdvertising.checked;$('#barcodePrintArea').innerHTML=products.flatMap(p=>Array.from({length:p.quantity},()=>`<article class="barcode-label">${showName?`<b>${p.name}</b>`:''}<div class="fake-barcode">|||| ||| ||||| || ||||</div>${showCode?`<span>${p.code}</span>`:''}${showPrice?`<strong>$${p.price}</strong>`:''}${showAd?`<small>$${p.advertising}</small>`:''}</article>`)).join('');printCurrentView()};draw()}
