function bindWarehouseSetup(){
 const form=$('#inventorySetupForm'),search=$('#inventorySetupSearch');if(!form||state.page!=='inventory-warehouse')return false;const rows=()=>inventorySetupRecords('inventory-warehouse');
 const reset=()=>{form.reset();form.elements._id.value='';$('#inventorySetupFormTitle').textContent='Create Warehouse';$('#inventorySetupSubmit').textContent='Save';$('#inventorySetupCancel').hidden=true};
 const edit=id=>{const r=rows().find(x=>String(x.id)===String(id));if(!r)return;form.elements._id.value=r.id;form.elements.Branch.value=r.Branch||r['Depo Name']||'SC1';form.elements.Warehouse.value=r.Warehouse||r['Warehouse Name']||'';form.elements.Code.value=r.Code||r['Stock Code']||'';form.elements.Description.value=r.Description||'';$('#inventorySetupFormTitle').textContent='Edit Warehouse';$('#inventorySetupSubmit').textContent='Update';$('#inventorySetupCancel').hidden=false;form.scrollIntoView({behavior:'smooth',block:'start'})};
 search.oninput=e=>document.querySelectorAll('#inventorySetupRows tr[data-id]').forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(e.target.value.toLowerCase()));
 $('#inventorySetupCancel').onclick=reset;
 document.querySelectorAll('.inventory-row-edit').forEach(b=>b.onclick=()=>edit(b.dataset.id));
 document.querySelectorAll('.inventory-row-delete').forEach(b=>b.onclick=async()=>{const id=b.dataset.id,r=rows().find(x=>String(x.id)===String(id));if(!r||!confirm(`Delete ${r.Warehouse||'this warehouse'}?`))return;try{if(state.server)await api('delete-workflow',{workflow:'inventory-warehouse',id});state.records['inventory-warehouse']=rows().filter(x=>String(x.id)!==String(id));persist();render();toast('Warehouse deleted')}catch(err){toast(err.message)}});
 form.onsubmit=async e=>{e.preventDefault();const id=form.elements._id.value||'',data={Branch:form.elements.Branch.value,Warehouse:form.elements.Warehouse.value.trim(),Code:form.elements.Code.value.trim(),Description:form.elements.Description.value.trim()};if(!data.Branch||!data.Warehouse||!data.Code||!data.Description)return toast('Please complete all required warehouse fields');try{let savedId=id||String(Date.now());if(state.server){const result=await api('workflow',{workflow:'inventory-warehouse',id,payload:data});savedId=result.id}const current=rows(),existing=current.find(x=>String(x.id)===String(id));if(existing)Object.assign(existing,data,{id:savedId});else current.unshift({id:savedId,...data});persist();render();toast(id?'Warehouse updated':'Warehouse saved')}catch(err){toast(err.message)}};
 enhanceActionIcons(document);return true;
}

