 document.querySelectorAll('.inventory-row-edit').forEach(b=>b.onclick=()=>edit(b.dataset.id));
 document.querySelectorAll('.inventory-row-delete').forEach(b=>b.onclick=async()=>{const id=b.dataset.id,r=rows().find(x=>String(x.id)===String(id));if(!r||!confirm(`Delete ${r.Brand||'this brand'}?`))return;try{if(state.server)await api('delete-workflow',{workflow:'inventory-brand',id});state.records['inventory-brand']=rows().filter(x=>String(x.id)!==String(id));persist();render();toast('Brand deleted')}catch(err){toast(err.message)}});
 form.onsubmit=async e=>{e.preventDefault();const id=form.elements._id.value||'',data={Branch:form.elements.Branch.value,Brand:form.elements.Brand.value.trim(),Image:form.dataset.existingImage||''};if(!data.Branch||!data.Brand)return toast('Please complete all required brand fields');const file=form.elements.ImageFile.files?.[0];if(file)data.Image=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});try{let savedId=id||String(Date.now());if(state.server){const result=await api('workflow',{workflow:'inventory-brand',id,payload:data});savedId=result.id}const current=rows(),existing=current.find(x=>String(x.id)===String(id));if(existing)Object.assign(existing,data,{id:savedId});else current.unshift({id:savedId,...data});persist();render();toast(id?'Brand updated':'Brand saved')}catch(err){toast(err.message)}};
