function bindPrintInvoices(){const form=$('#invoiceFilters');if(!form)return;const apply=()=>{const data=Object.fromEntries(new FormData(form)),query=$('#invoiceSearch').value.toLowerCase();let visible=0;document.querySelectorAll('#invoiceRows tr[data-method]').forEach(row=>{const show=(!data.method||row.dataset.method===data.method)&&(!data.start||row.dataset.date>=data.start)&&(!data.end||row.dataset.date<=data.end)&&row.dataset.search.includes(query);row.hidden=!show;if(show)visible++});$('#invoiceInfo').textContent=`Showing ${visible?'1':'0'} to ${visible} of ${visible} ${visible===1?'entry':'entries'}`};form.onsubmit=e=>{e.preventDefault();apply()};$('#invoiceSearch').oninput=apply;$('#clearInvoiceFilters').onclick=()=>{form.reset();$('#invoiceSearch').value='';apply()};document.querySelectorAll('.invoice-print').forEach(button=>button.onclick=()=>{const payment=state.payments.find(item=>String(item.id)===button.dataset.id);if(!payment)return;const popup=window.open('','invoice','width=760,height=700');if(!popup)return toast('Allow pop-ups to print invoices');popup.document.write(`<title>${esc(payment.receipt)}</title><style>body{font-family:Arial;padding:40px}header{border-bottom:2px solid #2679a7}table{width:100%;border-collapse:collapse;margin-top:30px}td,th{padding:12px;border:1px solid #ddd;text-align:left}</style><header><h1>WG SYSTEM</h1><h2>Invoice ${esc(payment.receipt)}</h2></header><p>Student: <b>${esc(payment.student_name||payment.student_id)}</b></p><p>Date Paid: ${String(payment.paid_at).slice(0,10)}</p><table><tr><th>Fees</th><th>Pay By</th><th>Amount Paid</th></tr><tr><td>${esc(payment.category)}</td><td>${esc(payment.method)}</td><td>${money(payment.amount)}</td></tr></table><script>print()<\/script>`);popup.document.close()})}
function collectFeesView(){const sections=['Tuition Information','Other Fee','DayCare Fee','Car Fee','Material Payment Infomation'];return `<div class="dashboard-title">Collect Fees</div><form id="collectFeesForm"><section class="panel fee-student"><div class="panel-head"><h2>♟ Student Information</h2></div><div class="panel-body form-grid"><div class="form-group full"><label>Search Student <em>*</em></label><select id="feeStudent" required><option value="">Select student</option>${state.students.map(s=>`<option value="${s.id}">${esc(s.name)} — ${esc(s.id)}</option>`).join('')}</select></div><div class="student-history" id="studentHistory">Select a student to view program, class, time and room.</div><div class="total-due"><span>Total Due Amount</span><b id="totalDue">$ 0.00</b></div></div></section>${sections.map((name,i)=>`<section class="panel fee-section"><div class="panel-head"><h2>${name}</h2><button type="button" class="btn fee-add" data-section="${i}">Add</button></div><div class="table-scroll"><table><thead><tr><th>Fee Item</th><th>${i===4?'Unit':'Start Date'}</th><th>${i===4?'Amount ($)':'Expiry Date'}</th><th>Amount ($)</th><th>Discount (%)</th><th>Discount ($)</th><th>Final Amount ($)</th><th>Action</th></tr></thead><tbody data-fee-rows="${i}">${feeRow(i)}</tbody></table></div></section>`).join('')}<section class="panel payment-details"><div class="panel-head"><h2>▣ Payment Details</h2></div><div class="panel-body form-grid"><div class="form-group"><label>Payment Date <em>*</em></label><input type="date" id="paymentDate" required value="${new Date().toISOString().slice(0,10)}"></div><div class="form-group"><label>Payment Method</label><select id="paymentMethod"><option>Cash</option><option>Bank</option><option>Card</option></select></div><div class="form-group full"><label>Note</label><textarea id="paymentNote" rows="3"></textarea></div><div class="form-group full fee-actions"><button type="button" class="btn secondary" id="clearFees">Clear Selected</button><button type="button" class="btn secondary" id="previewInvoice">Preview Invoice</button><button type="submit" class="btn primary">Save and Print</button></div></div></section></form>`}
