function bindCollectFees(){const form=$('#collectFeesForm');if(!form)return;const calculate=()=>{let grand=0;document.querySelectorAll('[data-fee-rows] tr').forEach(row=>{const amount=Number(row.querySelector('.fee-amount').value)||0,percent=Number(row.querySelector('.fee-percent').value)||0,fixed=Number(row.querySelector('.fee-discount').value)||0,total=Math.max(0,amount-(amount*percent/100)-fixed);row.querySelector('.fee-final').value=total.toFixed(2);grand+=total});$('#totalDue').textContent=money(grand);form.dataset.total=grand};form.oninput=calculate;document.querySelectorAll('.fee-add').forEach(b=>b.onclick=()=>{document.querySelector(`[data-fee-rows="${b.dataset.section}"]`).insertAdjacentHTML('beforeend',feeRow(Number(b.dataset.section)));bindCollectFees();calculate()});document.querySelectorAll('.fee-delete').forEach(b=>b.onclick=()=>{const body=b.closest('tbody');if(body.rows.length>1)b.closest('tr').remove();else b.closest('tr').querySelectorAll('input').forEach(x=>{if(!x.classList.contains('fee-name'))x.value=x.type==='date'?'':'0'});calculate()});$('#feeStudent').onchange=e=>{const s=state.students.find(x=>x.id===e.target.value);$('#studentHistory').innerHTML=s?`<b>${esc(s.name)}</b><span>Program: General Education</span><span>Class: ${esc(s.class)}</span><span>Status: ${esc(s.status)}</span>`:'Select a student to view program, class, time and room.'};$('#clearFees').onclick=()=>{form.reset();calculate()};$('#previewInvoice').onclick=()=>toast(`Invoice preview ready · ${$('#totalDue').textContent}`);form.onsubmit=async e=>{e.preventDefault();const student=$('#feeStudent').value,amount=Number(form.dataset.total)||0;if(!student)return toast('Select a student');if(amount<=0)return toast('Enter at least one fee amount');try{if(state.server)await api('payment',{student,category:'Combined school fees',amount,method:$('#paymentMethod').value});await refreshServer();toast('Payment saved and invoice prepared');render()}catch(error){toast(error.message)}};calculate()}
function esc(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function fieldControl(field,value=''){const name=field.toLowerCase();const type=name.includes('date')||name.includes('expiry')?'date':name.includes('amount')||name.includes('price')||name.includes('cost')||name.includes('salary')||name.includes('quantity')||name.includes('score')||name.includes('rate')?'number':name.includes('file')||name.includes('image')||name.includes('attachment')||name.includes('background')?'file':'text';if(name==='description'||name==='address'||name==='note'||name==='lesson entries'||name==='lesson contents')return `<textarea name="${esc(field)}" rows="3">${esc(value)}</textarea>`;if(/status|type|gender|currency|program|class|branch|teacher|student|warehouse|account|role|module|session|section|semester|quarter|month/.test(name))return `<select name="${esc(field)}"><option value="">Select ${esc(field)}</option>${[value,'Active','Inactive','USD','KHR','SC1','Morning','Afternoon','Present','Absent'].filter((x,i,a)=>x&&a.indexOf(x)===i).map(x=>`<option ${x===value?'selected':''}>${esc(x)}</option>`).join('')}</select>`;return `<input name="${esc(field)}" type="${type}" ${type==='number'?'step="any"':''} value="${type==='file'?'':esc(value)}">`}

async function saveWorkflowRecord(workflow,id,payload){
 const oldId=String(id||''),clean={...payload};delete clean.id;
 let savedId=oldId||String(Date.now());
 if(state.server){const result=await api('workflow',{workflow,id:oldId,payload:clean});savedId=String(result.id)}
 state.records[workflow]??=[];
 const existing=state.records[workflow].find(row=>String(row.id)===oldId);
 if(existing)Object.assign(existing,clean,{id:savedId});else state.records[workflow].unshift({id:savedId,...clean});
 persist();
 return savedId
}
