function autoPreInvoiceView(){const tab=state.autoPreTab||'generate',rows=preInvoiceRows();const candidates=state.students.filter(s=>s.status==='Active');return `${pageHead('Auto Pre-Invoice','Generate the next pre-invoices for multiple students at once.','')}
 <section class="panel auto-pre-panel"><div class="auto-pre-tabs"><button data-tab="generate" class="${tab==='generate'?'active':''}">Generate New</button><button data-tab="pending" class="${tab==='pending'?'active':''}">To Be Confirmed</button><button data-tab="confirmed" class="${tab==='confirmed'?'active':''}">Confirmed</button></div>
 ${tab==='generate'?`<form id="autoPreForm" class="auto-pre-filter"><label>Academic Year<select name="year"><option>2026-2027</option><option>2025-2026</option></select></label><label>Program<select name="program"><option>All Programs</option><option>Khmer Program</option><option>English Program</option><option>Chinese Program</option></select></label><label>Fee Description<input name="description" value="Monthly Tuition Fee" required></label><label>Amount<input name="amount" type="number" min="0" step="0.01" value="100" required></label><label>Due Date<input name="due_date" type="date" required></label><div class="full"><button class="btn primary" type="submit">Generate Selected</button></div></form><div class="table-scroll"><table><thead><tr><th><input id="autoAll" type="checkbox"></th><th>Student ID</th><th>Student</th><th>Class</th><th>Status</th></tr></thead><tbody>${candidates.map(s=>`<tr><td><input class="auto-student" type="checkbox" value="${esc(s.id)}"></td><td>${esc(s.id)}</td><td>${esc(s.name)}</td><td>${esc(s.class)}</td><td><span class="status-pill active">Active</span></td></tr>`).join('')}</tbody></table></div>`:`<div class="table-scroll"><table><thead><tr><th><input id="autoAllInvoice" type="checkbox"></th><th>Invoice</th><th>Student</th><th>Class</th><th>Amount</th><th>Due Date</th><th>Status</th></tr></thead><tbody>${rows.filter(r=>(r.auto_generated==='Yes')&&((tab==='confirmed')===(r.confirmed==='Yes'))).map(r=>`<tr><td><input class="auto-invoice" type="checkbox" value="${r.id}"></td><td>${esc(r.invoice_no)}</td><td>${esc(r.student)}</td><td>${esc(r.class)}</td><td>$${money2(r.total)}</td><td>${esc(r.due_date)}</td><td><span class="status-pill ${r.confirmed==='Yes'?'paid':'unpaid'}">${r.confirmed==='Yes'?'Confirmed':'Pending'}</span></td></tr>`).join('')||'<tr><td colspan="7" class="empty">No records found</td></tr>'}</tbody></table></div>${tab==='pending'?'<div class="auto-confirm-bar"><button id="confirmAutoInvoices" class="btn primary">Confirm Selected Pre-Invoices</button></div>':''}`}</section>`}
function bindAutoPreInvoices(){const tabs=document.querySelectorAll('.auto-pre-tabs button');if(!tabs.length)return;tabs.forEach(b=>b.onclick=()=>{state.autoPreTab=b.dataset.tab;render()});const form=$('#autoPreForm');if(form){const due=new Date();due.setDate(due.getDate()+30);form.elements.due_date.value=due.toISOString().slice(0,10);$('#autoAll').onchange=e=>document.querySelectorAll('.auto-student').forEach(x=>x.checked=e.target.checked);form.onsubmit=async e=>{e.preventDefault();const ids=[...document.querySelectorAll('.auto-student:checked')].map(x=>x.value);if(!ids.length)return toast('Select at least one student');const d=Object.fromEntries(new FormData(form));try{for(const id of ids){const st=state.students.find(x=>x.id===id);const payload={student_id:id,student:st.name,class:st.class,description:d.description,total:Number(d.amount),discount:0,paid:0,invoice_date:new Date().toISOString().slice(0,10),due_date:d.due_date,note:`Auto generated · ${d.year} · ${d.program}`,auto_generated:'Yes',confirmed:'No',invoice_no:`PI-${new Date().toISOString().slice(2,10).replaceAll('-','')}-${String(Date.now()+Math.random()).replace(/\D/g,'').slice(-5)}`};await saveWorkflowRecord('pre-invoices','',payload)}state.autoPreTab='pending';render();toast(`${ids.length} pre-invoice(s) generated`)}catch(err){toast(err.message)}}}const all=$('#autoAllInvoice');if(all)all.onchange=e=>document.querySelectorAll('.auto-invoice').forEach(x=>x.checked=e.target.checked);const confirmBtn=$('#confirmAutoInvoices');if(confirmBtn)confirmBtn.onclick=async()=>{const ids=[...document.querySelectorAll('.auto-invoice:checked')].map(x=>x.value);if(!ids.length)return toast('Select at least one pre-invoice');try{for(const id of ids){const row=preInvoiceRows().find(r=>String(r.id)===id);if(row)await saveWorkflowRecord('pre-invoices',id,{...row,confirmed:'Yes'})}state.autoPreTab='confirmed';render();toast('Selected pre-invoices confirmed')}catch(err){toast(err.message)}}}

function workflowView(key){const def=workflowDefs[key]||['Module',['Name','Description']];const [title,fields]=def;const rows=state.records[key]||[];const editId=state.editing?.key===key?state.editing.id:null;const editing=rows.find(r=>r.id===editId)||{};return `${pageHead(title,'Create, search, update, export and manage '+title.toLowerCase()+'.','<button class="btn secondary workflow-export">⇩ Excel</button>')}<div class="workflow-layout"><section class="panel workflow-form"><div class="panel-head"><h2>⚙ ${editId?'Edit':'Add'} ${title}</h2></div><form id="workflowForm" class="panel-body form-grid" data-key="${key}">${fields.map(f=>`<div class="form-group ${/description|address|note|lesson/i.test(f)?'full':''}"><label>${esc(f)} <em>*</em></label>${fieldControl(f,editing[f])}</div>`).join('')}<input type="hidden" name="_id" value="${editId||''}"><div class="form-group full workflow-submit"><button class="btn primary" type="submit">▣ Save</button>${editId?'<button class="btn secondary workflow-cancel" type="button">Cancel</button>':''}</div></form></section><section class="panel workflow-list"><div class="panel-head"><h2>☷ ${title} List</h2><input class="field workflow-search" placeholder="Search"></div><div class="table-scroll"><table><thead><tr><th>ID</th>${fields.slice(0,5).map(f=>`<th>${esc(f)}</th>`).join('')}<th>Action</th></tr></thead><tbody class="workflow-rows">${rows.length?rows.map((r,i)=>`<tr><td>${i+1}</td>${fields.slice(0,5).map(f=>`<td>${esc(r[f]||'—')}</td>`).join('')}<td><button class="mini-btn workflow-edit" data-id="${r.id}">Edit</button><button class="mini-btn workflow-delete" data-id="${r.id}">Delete</button></td></tr>`).join(''):`<tr><td colspan="${fields.slice(0,5).length+2}" class="empty">No records found</td></tr>`}</tbody></table></div></section></div>`}
function genericTable(title,desc,headers,rows,action){return `${pageHead(title,desc,`<button class="btn secondary">⇩ Export</button><button class="btn primary" id="genericAdd">${action}</button>`)}<section class="panel"><div class="table-tools"><input class="field" placeholder="Search…"><select class="select"><option>All statuses</option><option>Active</option></select></div><div class="table-scroll"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}<th></th></tr></thead><tbody>${rows.map(r=>`<tr>${r.map((v,i)=>`<td>${i===r.length-1?`<span class="badge ${/Active|Good|On time|Published/.test(v)?'good':'warn'}">${v}</span>`:v}</td>`).join('')}<td><button class="mini-btn">•••</button></td></tr>`).join('')}</tbody></table></div></section>`}
function openModal(type,id){const modal=$('#modal');$('#modalEyebrow').textContent=type==='student'?'Student record':type==='admission'?'Admission inquiry':'Finance';$('#modalTitle').textContent=type==='student'?(id?'Edit student':'Add student'):type==='admission'?'Add admission inquiry':'Record payment';$('#modalSubmit').textContent=type==='student'?'Save student':type==='admission'?'Save inquiry':'Record payment';if(type==='student'){const s=state.students.find(x=>x.id===id)||{};$('#modalBody').innerHTML=`<div class="form-grid"><div class="form-group"><label>Full name</label><input name="name" required value="${s.name||''}"></div><div class="form-group"><label>Student ID</label><input name="id" required value="${s.id||`ST-${2041+state.students.length}`}" ${id?'readonly':''}></div><div class="form-group"><label>Class</label><select name="class"><option ${s.class==='Grade 10 · A'?'selected':''}>Grade 10 · A</option><option ${s.class==='Grade 9 · B'?'selected':''}>Grade 9 · B</option><option ${s.class==='Grade 11 · A'?'selected':''}>Grade 11 · A</option><option ${s.class==='Grade 8 · C'?'selected':''}>Grade 8 · C</option></select></div><div class="form-group"><label>Status</label><select name="status"><option>Active</option><option ${s.status==='Pending'?'selected':''}>Pending</option></select></div><div class="form-group"><label>Guardian</label><input name="guardian" required value="${s.guardian||''}"></div><div class="form-group"><label>Phone</label><input name="phone" value="${s.phone||''}"></div></div>`;modal.dataset.type='student';modal.dataset.id=id||''}else if(type==='admission'){$('#modalBody').innerHTML=`<div class="form-grid"><div class="form-group"><label>Student name</label><input name="student_name" required></div><div class="form-group"><label>Guardian</label><input name="guardian" required></div><div class="form-group"><label>Phone</label><input name="phone"></div><div class="form-group"><label>Requested class</label><select name="requested_class"><option>Grade 8 · A</option><option>Grade 9 · B</option><option>Grade 10 · A</option><option>Grade 11 · A</option></select></div><div class="form-group full"><label>Inquiry source</label><select name="source"><option>Walk-in</option><option>Website</option><option>Referral</option><option>Phone</option></select></div></div>`;modal.dataset.type='admission'}else{$('#modalBody').innerHTML=`<div class="form-grid"><div class="form-group full"><label>Student</label><select name="student">${state.students.map(s=>`<option value="${s.id}">${s.name} · ${s.id}</option>`).join('')}</select></div><div class="form-group"><label>Fee category</label><select name="category"><option>Tuition</option><option>Material</option><option>Transport</option><option>Daycare</option><option>Other</option></select></div><div class="form-group"><label>Amount</label><input name="amount" type="number" min="1" required></div><div class="form-group"><label>Method</label><select name="method"><option>Card</option><option>Bank transfer</option><option>Cash</option></select></div></div>`;modal.dataset.type='payment'}modal.showModal()}
function bindPage(){document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>navigate(b.dataset.go));document.querySelectorAll('[data-modal]').forEach(b=>b.onclick=()=>openModal(b.dataset.modal));if($('#workflowForm')){$('#workflowForm').onsubmit=async e=>{e.preventDefault();const formData=new FormData(e.currentTarget),data={};for(const [key,value] of formData)data[key]=value instanceof File?value.name:value;const key=e.currentTarget.dataset.key,oldId=data._id||'';delete data._id;try{let id=oldId||String(Date.now());if(state.server){const result=await api('workflow',{workflow:key,id:oldId,payload:data});id=result.id}state.records[key]??=[];const found=state.records[key].find(r=>r.id===oldId);if(found)Object.assign(found,data,{id});else state.records[key].unshift({id,...data});state.editing=null;persist();render();toast(found?'Record updated':'Record saved')}catch(error){toast(error.message)}};document.querySelectorAll('.workflow-edit').forEach(b=>b.onclick=()=>{state.editing={key:state.page,id:b.dataset.id};render()});document.querySelectorAll('.workflow-delete').forEach(b=>b.onclick=async()=>{if(confirm('Delete this record?'))try{if(state.server)await api('delete-workflow',{workflow:state.page,id:b.dataset.id});state.records[state.page]=state.records[state.page].filter(r=>r.id!==b.dataset.id);persist();render();toast('Record deleted')}catch(error){toast(error.message)}});if($('.workflow-cancel'))$('.workflow-cancel').onclick=()=>{state.editing=null;render()};$('.workflow-search').oninput=e=>document.querySelectorAll('.workflow-rows tr').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(e.target.value.toLowerCase()));$('.workflow-export').onclick=()=>exportWorkflow()}if($('#studentSearch')){const filter=()=>{const q=$('#studentSearch').value.toLowerCase(),c=$('#classFilter').value;const list=state.students.filter(s=>(s.name+s.id+s.guardian).toLowerCase().includes(q)&&(c==='All classes'||s.class===c));$('#studentRows').innerHTML=studentRows(list);$('#studentCount').textContent=`${list.length} records`;bindStudentRows()};$('#studentSearch').oninput=filter;$('#classFilter').onchange=filter;bindStudentRows();$('#exportBtn').onclick=downloadStudents}document.querySelectorAll('.att').forEach(b=>b.onclick=()=>{b.parentElement.querySelectorAll('button').forEach(x=>x.classList.remove('active'));b.classList.add('active');state.attendance[b.closest('.attendance-card').dataset.id]=b.dataset.value});if($('#saveAttendance'))$('#saveAttendance').onclick=async()=>{try{if(state.server)await api('attendance',{date:new Date().toISOString().slice(0,10),session:'Morning',records:state.attendance});toast('Attendance saved')}catch(error){toast(error.message)}};document.querySelectorAll('.enroll-btn').forEach(b=>b.onclick=async()=>{try{await api('approve-admission',{id:Number(b.dataset.id)});await refreshServer();toast('Applicant enrolled and student record created');navigate('students')}catch(error){toast(error.message)}});bindAdmissionActions();if($('#downloadReport'))$('#downloadReport').onclick=()=>toast('Report prepared');if($('#saveSettings'))$('#saveSettings').onclick=()=>toast('Settings saved');if($('#genericAdd'))$('#genericAdd').onclick=()=>toast('New record workflow opened');bindCardTemplateForm()}
function bindAdmissionActions(){document.querySelectorAll('.admission-more').forEach(button=>button.onclick=e=>{e.stopPropagation();const menu=button.nextElementSibling,opening=menu.hidden;document.querySelectorAll('.admission-action-menu').forEach(item=>item.hidden=true);menu.hidden=!opening});document.querySelectorAll('.admission-status').forEach(b=>b.onclick=async()=>{try{if(state.server)await api('admission-status',{id:Number(b.dataset.id),status:b.dataset.status});const record=state.admissions.find(x=>String(x.id)===b.dataset.id);if(record)record.status=b.dataset.status;render();toast('Admission status updated')}catch(error){toast(error.message)}});if($('#admissionSearch'))$('#admissionSearch').oninput=e=>{let visible=0;document.querySelectorAll('#admissionRows tr').forEach(r=>{r.hidden=!r.textContent.toLowerCase().includes(e.target.value.toLowerCase());if(!r.hidden)visible++});$('#admissionInfo').textContent=`Showing ${visible?'1':'0'} to ${visible} of ${visible} ${visible===1?'entry':'entries'}`}}
function exportWorkflow(){const rows=state.records[state.page]||[];if(!rows.length)return toast('No records to export');const keys=Object.keys(rows[0]).filter(k=>k!=='id'),csv=[keys.join(','),...rows.map(r=>keys.map(k=>`"${String(r[k]||'').replaceAll('"','""')}"`).join(','))].join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download=`${state.page}.csv`;a.click();URL.revokeObjectURL(a.href)}
async function refreshServer(){if(!server)return;const data=await api('bootstrap');state.students=data.students.map(s=>({...s,balance:Number(s.balance),attendance:Number(s.attendance)}));state.admissions=data.admissions;state.payments=data.payments;state.records=data.records||state.records;state.financeSummary=data.finance_summary||null;state.currentUser=data.current_user||state.currentUser;state.attendanceRows=data.attendance||[];state.attendance={};for(const row of state.attendanceRows)if(!(String(row.student_id) in state.attendance))state.attendance[String(row.student_id)]=row.state;state.server=true;persist()}
function bindStudentRows(){document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openModal('student',b.dataset.edit));document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=async()=>{if(confirm('Remove this student record?')){try{if(state.server)await api('delete-student',{id:b.dataset.delete});state.students=state.students.filter(s=>s.id!==b.dataset.delete);persist();render();toast('Student removed')}catch(error){toast(error.message)}}})}
function sendAI(){const input=$('#aiInput'),text=input.value.trim();if(!text)return;state.messages.push({role:'user',text});const lower=text.toLowerCase();let reply='This prototype is ready for a server-side AI connection. I can pass the selected operational context to the configured model once an API endpoint is connected.';if(lower.includes('attendance'))reply='Attendance is 94.6% today. Twelve students are below the intervention threshold, with Grade 8 · C showing the highest concentration of absences.';if(lower.includes('payment')||lower.includes('overdue'))reply='There are 38 overdue accounts. I drafted a neutral reminder sequence segmented into 7-day, 14-day, and 30-day overdue groups for human review.';if(lower.includes('schedule'))reply='I found one likely conflict: Grade 10 science and Grade 11 practical both request Lab 2 on Thursday at 10:15. Moving Grade 10 science to Lab 1 resolves it.';if(lower.includes('leadership'))reply='This week: enrollment is up 4.2%, attendance is 0.4 points below target, fee collection reached 91%, and three staffing requirements remain open.';state.messages.push({role:'assistant',text:reply});render();setTimeout(()=>{const m=$('#messages');if(m)m.scrollTop=m.scrollHeight},0)}
function downloadStudents(){const csv=['ID,Name,Class,Guardian,Phone,Status,Balance',...state.students.map(s=>[s.id,s.name,s.class,s.guardian,s.phone,s.status,s.balance].map(v=>`"${v}"`).join(','))].join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='northstar-students.csv';a.click();URL.revokeObjectURL(a.href);toast('Student export downloaded')}
$('#modalForm').addEventListener('submit',async e=>{if(e.submitter?.value==='cancel')return;e.preventDefault();const modal=$('#modal'),data=Object.fromEntries(new FormData(e.target));try{if(modal.dataset.type==='student'){const existing=state.students.find(s=>s.id===modal.dataset.id);const record={...existing,...data,balance:existing?.balance||0,attendance:existing?.attendance||100};if(state.server)await api('student',record);if(existing)Object.assign(existing,record);else state.students.unshift(record);persist();toast(existing?'Student updated':'Student added');modal.close();navigate('students')}else if(modal.dataset.type==='admission'){if(state.server){await api('admission',data);await refreshServer()}else state.admissions.unshift({...data,id:Date.now(),status:'Inquiry',created_at:new Date().toISOString()});toast('Admission inquiry saved');modal.close();navigate('admissions')}else{const s=state.students.find(x=>x.id===data.student);if(state.server){const result=await api('payment',data);await refreshServer();toast(`Payment recorded · ${result.receipt}`)}else{if(s)s.balance=Math.max(0,s.balance-Number(data.amount));persist();toast(`Payment recorded for ${s?.name}`)}modal.close();navigate('finance')}}catch(error){toast(error.message)}});
function showApplication(isLoggedIn){
  document.body.classList.toggle('is-authenticated',isLoggedIn);
  document.body.classList.toggle('is-login',!isLoggedIn);
  $('#loginScreen').hidden=isLoggedIn;
  $('#appShell').hidden=!isLoggedIn;
  if(isLoggedIn){restoreRememberedPage();renderNav();if(server){$('#content').innerHTML='<div class="page-loading" role="status">Loading page...</div>';loadServerData()}else navigate(state.page)}
}
