const adminLoginForm=$('#loginForm'),adminLoginPassword=$('#adminLoginPassword'),adminPasswordToggle=$('#adminPasswordToggle'),rememberAdminUsername=$('#rememberAdminUsername'),savedAdminUsername=localStorage.getItem('wg.admin.username')||'';
const requiredPasswordDialog=$('#requiredPasswordDialog'),requiredPasswordForm=$('#requiredPasswordForm');
function enforceRequiredPasswordChange(){if(!state.currentUser?.must_change_password)return;if(requiredPasswordDialog&&!requiredPasswordDialog.open)requiredPasswordDialog.showModal()}
if(requiredPasswordForm)requiredPasswordForm.onsubmit=async event=>{event.preventDefault();const data=Object.fromEntries(new FormData(requiredPasswordForm)),error=$('#requiredPasswordError'),button=event.submitter;error.textContent='';button.disabled=true;try{await api('change-required-password',data);state.currentUser.must_change_password=false;requiredPasswordForm.reset();requiredPasswordDialog.close();toast('Your new password has been saved')}catch(problem){error.textContent=problem.message}finally{button.disabled=false}};
if(savedAdminUsername){adminLoginForm.elements.email.value=savedAdminUsername;rememberAdminUsername.checked=true}
adminPasswordToggle.onclick=()=>{const show=adminLoginPassword.type==='password';adminLoginPassword.type=show?'text':'password';adminPasswordToggle.setAttribute('aria-label',show?'Hide password':'Show password')};
$('#loginLanguage').onchange=e=>setLanguage(e.target.value,true);
adminLoginForm.onsubmit=async e=>{e.preventDefault();const data=new FormData(e.currentTarget);try{const result=await api('login',{email:data.get('email'),password:data.get('password')});if(data.get('remember'))localStorage.setItem('wg.admin.username',String(data.get('email')).trim());else localStorage.removeItem('wg.admin.username');state.currentUser=result.user||null;server.authenticated=true;$('#loginError').textContent='';showApplication(true);applySignedInUser();enforceRequiredPasswordChange()}catch(error){$('#loginError').textContent=error.message}};
