let knownPendingPaymentProofs=null,paymentNotificationPolling=false;
function paymentProofAlertKey(row){return `${row.id}:${row.submitted_at||row.updated_at||''}`}
let backendNotificationAudio=null;
function unlockBackendNotificationSound(){try{const AudioContext=window.AudioContext||window.webkitAudioContext;if(!AudioContext)return;backendNotificationAudio??=new AudioContext();if(backendNotificationAudio.state==='suspended')backendNotificationAudio.resume()}catch{}}
document.addEventListener('pointerdown',unlockBackendNotificationSound,{once:true});
function playBackendNotificationSound(){
 try{unlockBackendNotificationSound();const audio=backendNotificationAudio;if(!audio)return;const gain=audio.createGain(),tone=audio.createOscillator();tone.type='sine';tone.frequency.setValueAtTime(880,audio.currentTime);gain.gain.setValueAtTime(.0001,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.18,audio.currentTime+.02);gain.gain.exponentialRampToValueAtTime(.0001,audio.currentTime+.45);tone.connect(gain);gain.connect(audio.destination);tone.start();tone.stop(audio.currentTime+.48)}catch{}
}
async function pollBackendPaymentNotifications(){
 if(!state.server||paymentNotificationPolling||document.hidden)return;paymentNotificationPolling=true;
 try{const data=await api('bootstrap'),proofs=data.records?.['mobile-payment-proof']||[],pending=proofs.filter(row=>row.status==='Pending Verification'),current=new Set(pending.map(paymentProofAlertKey));state.records['mobile-payment-proof']=proofs;renderNotifications();if(knownPendingPaymentProofs===null){knownPendingPaymentProofs=current;return}const fresh=pending.filter(row=>!knownPendingPaymentProofs.has(paymentProofAlertKey(row)));knownPendingPaymentProofs=current;if(!fresh.length)return;playBackendNotificationSound();toast(fresh.length===1?`${fresh[0].student||'A student'} submitted a payment receipt`:`${fresh.length} new student payments need verification`);if(state.page==='mobile-payment-proof')render()}catch{}finally{paymentNotificationPolling=false}
}
setInterval(pollBackendPaymentNotifications,5000);

