const hrMenuItems=[['hr-import','Import Employee'],['staff','Employees'],['hr-contract','Contract'],['hr-payroll','Payroll'],['hr-print-payroll','Printing Payroll'],['hr-position','Position'],['hr-department','Department'],['hr-template','Template'],['hr-manage-payroll','Manage Payroll'],['hr-scan','Scan Attendance'],['hr-log','Attendance Log']];
function hrRows(key){const saved=state.records[key]||[];const hidden=new Set(JSON.parse(localStorage.getItem('scschool.hrHidden')||'[]'));const defaults=(hrSeed[key]||[]).filter(r=>!hidden.has(r.id));const ids=new Set(saved.map(r=>r.id));return [...saved,...defaults.filter(r=>!ids.has(r.id))]}
function hrTitle(key){return hrMenuItems.find(x=>x[0]===key)?.[1]||'Mini HR'}
function hrLayout(active,body,crumb=''){return `<section class="hr-page"><div class="hr-breadcrumb"><span>⌂ Dashboard</span><i>/</i><span>${crumb||hrTitle(active)}</span><button type="button" onclick="navigate('dashboard')">← Back</button></div><div class="hr-shell"><aside class="hr-submenu"><h3>⚙ Human<br>Resources</h3>${hrMenuItems.map(([key,label])=>`<button class="${active===key?'active':''}" type="button" onclick="navigate('${key}')">» <span>${label}</span></button>`).join('')}</aside><main class="hr-main">${body}</main></div></section>`}
function hrTools(key,add=true){return `<div class="hr-card hr-toolbar">${add?`<button class="hr-add" type="button" onclick="hrOpenForm('${key}')">✚ Add New</button>`:''}</div>`}
function hrDataTools(count){return `<div class="hr-data-tools"><label>Show <select><option>10</option><option>20</option><option>50</option></select> entries</label><label>Search: <input class="hr-search" oninput="hrFilterTable(this)"></label></div>`}
function hrPager(count){return `<div class="hr-table-footer"><span>Showing ${count?1:0} to ${count} of ${count} entries</span><div><button disabled>Previous</button><b>1</b><button disabled>Next</button></div></div>`}
function hrAction(key,id){return `<div class="hr-action"><button type="button" onclick="this.nextElementSibling.hidden=!this.nextElementSibling.hidden">•••⌄</button><div hidden><button type="button" onclick="hrOpenForm('${key}','${id}')">Edit</button><button type="button" onclick="hrDelete('${key}','${id}')">Delete</button></div></div>`}
function hrFilterTable(input){const q=input.value.toLowerCase(), table=input.closest('.hr-table-card')?.querySelector('tbody');if(!table)return;[...table.rows].forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(q));}
function hrEmployeeView(){const rows=hrRows('staff');const body=`${hrTools('staff')}<section class="hr-card hr-table-card">${hrDataTools(rows.length)}<div class="table-scroll"><table><thead><tr><th>ID</th><th>Profile</th><th>Staff Code</th><th>Branch</th><th>Name Khmer</th><th>Name English</th><th>Main Contact</th><th>Status</th><th>Action</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td>${i+1}</td><td><span class="hr-avatar">${r.Profile?`<img src="${esc(r.Profile)}" alt="">`:initials(r['Name English']||r['Name Khmer']||'HR')}</span></td><td>${esc(r['Staff Code']||'')}</td><td>${esc(r.Branch||'')}</td><td>${esc(r['Name Khmer']||'')}</td><td>${esc(r['Name English']||'')}</td><td>${esc(r['Main Contact']||'')}</td><td><span class="hr-status active">${esc(r.Status||'Active')}</span></td><td>${hrAction('staff',r.id)}</td></tr>`).join('')}</tbody></table></div>${hrPager(rows.length)}</section>`;return hrLayout('staff',body,'⚙ List of Staff Name')}
function hrContractView(){const rows=hrRows('hr-contract');const body=`${hrTools('hr-contract')}<section class="hr-card hr-table-card">${hrDataTools(rows.length)}<div class="table-scroll"><table><thead><tr><th>ID</th><th>Staff ID</th><th>Branch</th><th>Full Name (Khmer)</th><th>Full Name (English)</th><th>Position</th><th>Contract signing date</th><th>Contract End Date</th><th>Type</th><th>Status</th><th>Action</th></tr></thead><tbody>${rows.length?rows.map((r,i)=>`<tr><td>${i+1}</td><td>${esc(r['Staff ID']||r.Employee||'')}</td><td>${esc(r.Branch||'SC1')}</td><td>${esc(r['Full Name Khmer']||'')}</td><td>${esc(r['Full Name English']||r.Employee||'')}</td><td>${esc(r.Position||'')}</td><td>${esc(r['Start Date']||'')}</td><td>${esc(r['End Date']||'')}</td><td>${esc(r['Contract Type']||'')}</td><td>${esc(r.Status||'Active')}</td><td>${hrAction('hr-contract',r.id)}</td></tr>`).join(''):`<tr><td colspan="11" class="empty">No data available in table</td></tr>`}</tbody></table></div>${hrPager(rows.length)}</section>`;return hrLayout('hr-contract',body,'◉ List of contracted employees')}
function hrPayrollView(){const rows=hrRows('hr-payroll');const body=`${hrTools('hr-payroll')}<section class="hr-card hr-table-card">${hrDataTools(rows.length)}<div class="table-scroll"><table><thead><tr><th>ID</th><th>User</th><th>Date</th><th>Salary</th><th>Payment Status</th><th>Action</th></tr></thead><tbody>${rows.length?rows.map((r,i)=>{const salary=(Number(r['Basic Salary']||0)+Number(r.Allowance||0)-Number(r.Deduction||0));return `<tr><td>${i+1}</td><td>${esc(r.Employee||'')}</td><td>${esc(r.Month||r.Date||'')}</td><td>${salary.toFixed(2)}</td><td><span class="hr-status ${String(r['Payment Status']||'Pending').toLowerCase()==='paid'?'active':'pending'}">${esc(r['Payment Status']||'Pending')}</span></td><td>${hrAction('hr-payroll',r.id)}</td></tr>`}).join(''):`<tr><td colspan="6" class="empty">No data available in table</td></tr>`}</tbody></table></div>${hrPager(rows.length)}</section>`;return hrLayout('hr-payroll',body,'▤ Payroll')}
function hrPrintPayrollView(){const body=`<section class="hr-card hr-print-filter"><label>Date<input id="hrPayrollDate" type="date"></label><div><button class="hr-green" type="button" onclick="toast('Payroll filtered')">⚑ Filter</button><button class="hr-orange" type="button" onclick="printCurrentView()">▣ PDF Format</button><button class="hr-green" type="button" onclick="hrExportPayroll()">▧ Excel Format</button></div></section>`;return hrLayout('hr-print-payroll',body,'▣ Printing Payroll')}
function hrSimpleListView(key,columns){const rows=hrRows(key);const body=`${hrTools(key)}<section class="hr-card hr-table-card">${hrDataTools(rows.length)}<div class="table-scroll"><table><thead><tr><th>ID</th>${columns.map(c=>`<th>${c}</th>`).join('')}<th>Action</th></tr></thead><tbody>${rows.length?rows.map((r,i)=>`<tr><td>${i+1}</td>${columns.map(c=>`<td>${esc(r[c]||'')}</td>`).join('')}<td>${hrAction(key,r.id)}</td></tr>`).join(''):`<tr><td colspan="${columns.length+2}" class="empty">No data available in table</td></tr>`}</tbody></table></div>${hrPager(rows.length)}</section>`;return hrLayout(key,body,hrTitle(key)+' List')}
function hrManagePayrollView(){const rows=hrRows('hr-manage-payroll');const body=`${hrTools('hr-manage-payroll')}<section class="hr-card hr-table-card">${hrDataTools(rows.length)}<div class="table-scroll"><table><thead><tr><th>ID</th><th>Employee</th><th>Basic Salary</th><th>Allowance</th><th>Deduction</th><th>Currency</th><th>Net Salary</th><th>Action</th></tr></thead><tbody>${rows.length?rows.map((r,i)=>`<tr><td>${i+1}</td><td>${esc(r.Employee||'')}</td><td>${esc(r['Basic Salary']||'0')}</td><td>${esc(r.Allowance||'0')}</td><td>${esc(r.Deduction||'0')}</td><td>${esc(r.Currency||'USD')}</td><td>${(Number(r['Basic Salary']||0)+Number(r.Allowance||0)-Number(r.Deduction||0)).toFixed(2)}</td><td>${hrAction('hr-manage-payroll',r.id)}</td></tr>`).join(''):`<tr><td colspan="8" class="empty">No data available in table</td></tr>`}</tbody></table></div>${hrPager(rows.length)}</section>`;return hrLayout('hr-manage-payroll',body,'Manage Payroll')}
function hrImportView(){const body=`<section class="hr-card hr-import-card"><header>♟ Employee Import</header><div class="hr-import-body"><label><b>Select Branch <em>*</em></b><select id="hrImportBranch"><option value="">-- Choose Branch --</option><option>SC1</option><option>HQ</option></select></label><label class="hr-drop" for="hrImportFile"><strong>▣</strong><span>Upload Excel File</span><small id="hrImportName">Click or drag file here</small><input id="hrImportFile" type="file" accept=".csv,.xls,.xlsx" hidden onchange="hrImportPicked(this)"></label><div class="hr-import-actions"><button class="hr-outline-orange" type="button" onclick="hrDownloadTemplate()">⇩ Download Template</button><button class="hr-green" type="button" onclick="hrImportEmployees()">↥ Import Employees</button></div></div></section>`;return hrLayout('hr-import',body,'◉ Import Employee')}
function hrScanView(){const school=schoolIdentityData(),body=`<section class="hr-scan-sheet"><div class="hr-scan-logo">${systemLogoMarkup('system-doc-logo')}</div><h2>${esc(school.nameEng||school.name)}</h2><div class="hr-qr" aria-label="Attendance QR"><span>▦</span></div><footer>${esc(school.address)}</footer></section>`;return hrLayout('hr-scan',body,'Scan Attendance')}
function hrAttendanceLogView(){const rows=hrRows('hr-log');const totals={Present:0,Late:0,Absent:0,Permission:0};rows.forEach(r=>{const s=r.Status||'Present';totals[s]=(totals[s]||0)+1});const body=`<section class="hr-card hr-att-stats">${[['Present','present'],['Late','late'],['Absent','absent'],['Permission','permission']].map(([label,cls])=>`<article class="${cls}"><b>${totals[label]||0}</b><span>${label}</span></article>`).join('')}</section><section class="hr-card hr-att-filters"><input id="hrLogDate" type="date" oninput="hrFilterAttendance()"><select id="hrLogBranch" onchange="hrFilterAttendance()"><option>All Branch</option><option>SC1</option></select><select id="hrLogStaff" onchange="hrFilterAttendance()"><option>All Staff</option>${hrRows('staff').map(r=>`<option>${esc(r['Name English']||r['Name Khmer']||'')}</option>`).join('')}</select><select id="hrLogStatus" onchange="hrFilterAttendance()"><option>All Status</option><option>Present</option><option>Late</option><option>Absent</option><option>Permission</option></select></section><section class="hr-card hr-table-card">${hrDataTools(rows.length)}<div class="table-scroll"><table><thead><tr><th>#</th><th>Employees</th><th>Date</th><th>Morning In</th><th>Morning Out</th><th>Afternoon In</th><th>Afternoon Out</th><th>Status</th></tr></thead><tbody id="hrAttendanceRows">${rows.map((r,i)=>`<tr data-date="${esc(r.Date||'')}" data-status="${esc(r.Status||'')}" data-employee="${esc(r.Employee||'')}"><td>${i+1}</td><td>${esc(r.Employee||'')}</td><td>${esc(r.Date||'')}</td><td>${esc(r['Morning In']||'')}</td><td>${esc(r['Morning Out']||'')}</td><td>${esc(r['Afternoon In']||'')}</td><td>${esc(r['Afternoon Out']||'')}</td><td><span class="hr-log-status ${(r.Status||'present').toLowerCase()}">${esc(r.Status||'Present')}</span></td></tr>`).join('')}</tbody></table></div>${hrPager(rows.length)}</section>`;return hrLayout('hr-log',body,'✓ Attendance List / Approve Leave')}
function hrFilterAttendance(){const d=$('#hrLogDate')?.value||'',s=$('#hrLogStatus')?.value||'All Status',e=$('#hrLogStaff')?.value||'All Staff';document.querySelectorAll('#hrAttendanceRows tr').forEach(r=>r.hidden=(d&&r.dataset.date!==d)||(s!=='All Status'&&r.dataset.status!==s)||(e!=='All Staff'&&r.dataset.employee!==e))}
function hrFormFields(key){return {
 staff:['Staff Code','Branch','Name Khmer','Name English','Main Contact','Position','Status','Profile'],
 'hr-contract':['Staff ID','Branch','Full Name Khmer','Full Name English','Position','Contract Type','Start Date','End Date','Salary','Status'],
 'hr-payroll':['Employee','Month','Basic Salary','Allowance','Deduction','Payment Status'],
 'hr-position':['Position Code','Position Khmer','Position English'],
 'hr-department':['Department Code','Department Khmer','Department English'],
 'hr-template':['Name'],
 'hr-manage-payroll':['Employee','Basic Salary','Allowance','Deduction','Currency']
 }[key]||[]}
function hrInputControl(field,value=''){if(field==='Status')return `<select name="${field}"><option ${value==='Active'?'selected':''}>Active</option><option ${value==='Inactive'?'selected':''}>Inactive</option></select>`;if(field==='Payment Status')return `<select name="${field}"><option>Pending</option><option ${value==='Paid'?'selected':''}>Paid</option></select>`;if(field==='Currency')return `<select name="${field}"><option>USD</option><option>KHR</option></select>`;if(/Date|Month/.test(field))return `<input name="${field}" type="${field==='Month'?'month':'date'}" value="${esc(value)}">`;if(field==='Profile')return `<input name="${field}" type="file" accept="image/*">`;if(field==='Branch')return `<select name="${field}"><option>SC1</option><option>HQ</option></select>`;return `<input name="${field}" value="${esc(value)}" ${/Code|Name English|Employee|Name$/.test(field)?'required':''}>`}
function hrOpenForm(key,id=''){const row=hrRows(key).find(r=>r.id===id)||{};state.hrForm={key,id};const fields=hrFormFields(key);const form=`<section class="hr-card hr-edit-card"><header>${id?'Edit':'Add'} ${hrTitle(key)}</header><form id="hrEditForm">${fields.map(f=>`<label>${f}${hrInputControl(f,row[f]||'')}</label>`).join('')}<div class="hr-form-actions"><button class="hr-muted" type="button" onclick="render()">Cancel</button><button class="hr-green" type="submit">Save</button></div></form></section>`;const host=document.querySelector('.hr-main');if(host){host.insertAdjacentHTML('afterbegin',form);$('#hrEditForm').onsubmit=e=>hrSubmitForm(e,key,id);host.querySelector('.hr-edit-card input, .hr-edit-card select')?.focus()}}
async function hrSubmitForm(e,key,id){e.preventDefault();const fd=new FormData(e.currentTarget),payload={};for(const [k,v] of fd){if(v instanceof File){if(v.size){payload[k]=await hrFileData(v)}else payload[k]=''}else payload[k]=v}await hrSaveRecord(key,id,payload)}
function hrFileData(file){return new Promise(resolve=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>resolve('');r.readAsDataURL(file)})}
async function hrSaveRecord(key,id,payload){try{let savedId=id;if(state.server && !String(id).startsWith('hr-seed-')){const out=await api('workflow',{workflow:key,id:id||'',payload});savedId=out.id}else if(state.server && String(id).startsWith('hr-seed-')){const out=await api('workflow',{workflow:key,id:'',payload});savedId=out.id}else savedId=id||String(Date.now());state.records[key]??=[];let row=state.records[key].find(r=>r.id===id);if(row)Object.assign(row,payload);else state.records[key].unshift({id:savedId,...payload});if(String(id).startsWith('hr-seed-')){const hidden=JSON.parse(localStorage.getItem('scschool.hrHidden')||'[]');if(!hidden.includes(id))hidden.push(id);localStorage.setItem('scschool.hrHidden',JSON.stringify(hidden))}persist();state.hrForm=null;render();toast(id?'Record updated':'Record saved')}catch(err){toast(err.message)}}
async function hrDelete(key,id){if(!confirm('Delete this record?'))return;try{if(state.server&&!String(id).startsWith('hr-seed-'))await api('delete-workflow',{workflow:key,id});state.records[key]=(state.records[key]||[]).filter(r=>r.id!==id);if(String(id).startsWith('hr-seed-')){localStorage.setItem('scschool.hrHidden',JSON.stringify([...(JSON.parse(localStorage.getItem('scschool.hrHidden')||'[]')),id]));hrSeed[key]=(hrSeed[key]||[]).filter(r=>r.id!==id)}persist();render();toast('Record deleted')}catch(err){toast(err.message)}}
function hrImportPicked(input){$('#hrImportName').textContent=input.files[0]?.name||'Click or drag file here'}
function hrDownloadTemplate(){const csv='Staff Code,Branch,Name Khmer,Name English,Main Contact,Position,Status\nIIS.001,SC1,,Example Staff,012345678,Teacher,Active\n';downloadBlob(csv,'employee_import_template.csv','text/csv')}
function downloadBlob(text,name,type='text/plain'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
function hrImportEmployees(){const branch=$('#hrImportBranch')?.value,file=$('#hrImportFile')?.files[0];if(!branch)return toast('Please select Branch');if(!file)return toast('Please select an Excel or CSV file');if(!file.name.toLowerCase().endsWith('.csv'))return toast('File selected. For browser import, use the downloadable CSV template.');const reader=new FileReader();reader.onload=async()=>{const lines=String(reader.result).split(/\r?\n/).filter(Boolean);if(lines.length<2)return toast('No employee rows found');const headers=lines[0].split(',').map(x=>x.trim());for(const line of lines.slice(1)){const cols=line.split(',');const payload={};headers.forEach((h,i)=>payload[h]=(cols[i]||'').trim());payload.Branch=payload.Branch||branch;await hrSaveRecord('staff','',payload)}toast('Employees imported')};reader.readAsText(file)}
function hrExportPayroll(){const rows=hrRows('hr-payroll'),csv=['Employee,Date,Salary,Payment Status',...rows.map(r=>`${r.Employee||''},${r.Month||''},${Number(r['Basic Salary']||0)+Number(r.Allowance||0)-Number(r.Deduction||0)},${r['Payment Status']||'Pending'}`)].join('\n');downloadBlob(csv,'payroll.csv','text/csv')}
const miniHrWorkflowView=workflowView;
workflowView=function(key){if(key==='staff')return hrEmployeeView();if(key==='hr-import')return hrImportView();if(key==='hr-contract')return hrContractView();if(key==='hr-payroll')return hrPayrollView();if(key==='hr-print-payroll')return hrPrintPayrollView();if(key==='hr-position')return hrSimpleListView(key,['Position Code','Position Khmer','Position English']);if(key==='hr-department')return hrSimpleListView(key,['Department Code','Department Khmer','Department English']);if(key==='hr-template')return hrSimpleListView(key,['Name']);if(key==='hr-manage-payroll')return hrManagePayrollView();if(key==='hr-scan')return hrScanView();if(key==='hr-log')return hrAttendanceLogView();return miniHrWorkflowView(key)};

/* ================================================================
   TRANSPORT / BRANCH / USERS / FIXED ASSETS / SETTINGS
   Reference-screen views requested by user.
   ================================================================ */
const coreSeeds={
 'transport-route':[{id:'seed-route-1','Route Title':'271','Google Maps':'271','Note':'271'}],
 'transport':[{id:'seed-vehicle-1','Vehicle Number':'1AZ-1001001','Vehicle Model':'','Year Made':'','Driver Name':'Testing Father admin','Driver License':'','Driver Contact':'09876543','Note':''}],
 'user-access':[
  {id:'seed-role-0','Access rights':'Super Administrator'},{id:'seed-role-1','Access rights':'Testing'},{id:'seed-role-2','Access rights':'Parent'},{id:'seed-role-3','Access rights':'Administrative'},{id:'seed-role-4','Access rights':'Agency'},{id:'seed-role-5','Access rights':'Seller'},{id:'seed-role-6','Access rights':'Driver'},{id:'seed-role-7','Access rights':'Program Supervisor'},{id:'seed-role-8','Access rights':'Security'},{id:'seed-role-9','Access rights':'Cleaner'},{id:'seed-role-10','Access rights':'Vice School Director'}
 ]
};
function coreRows(key){const hidden=JSON.parse(localStorage.getItem('scschool.coreHidden')||'[]');const saved=state.records[key]||[];return [...(coreSeeds[key]||[]).filter(r=>!hidden.includes(r.id)&&!saved.some(s=>Object.keys(r).some(k=>k!=='id'&&r[k]&&s[k]===r[k]))),...saved]}
function branchSelectOptions(current=''){
 const active=coreRows('branch').filter(row=>String(row.Active??row.Status??'Yes').toLowerCase()!=='no'&&String(row.Active??row.Status??'Active').toLowerCase()!=='inactive');
 const choices=active.map(row=>{const value=String(row['Short Code']||row.Code||row['Branch Name Eng']||row['Branch Name']||'').trim(),name=String(row['Branch Name Eng']||row['Branch Name']||value).trim();return {value,name}}).filter(row=>row.value);
 if(!choices.length)choices.push({value:'SC1',name:'SC1'});
 if(current&&!choices.some(row=>row.value===current))choices.unshift({value:current,name:current});
 return [...new Map(choices.map(row=>[row.value,row])).values()].map(row=>`<option value="${esc(row.value)}" ${row.value===current?'selected':''}>${esc(row.name===row.value?row.value:`${row.value} - ${row.name}`)}</option>`).join('')
}
function coreBread(label,extra=''){return `<div class="core-bread"><span>⌂ Dashboard</span><i>/</i><span>${label}</span>${extra?`<i>/</i><span>${extra}</span>`:''}<button data-go="dashboard">← Back</button></div>`}
function coreAction(key,id){return `<button class="core-more" type="button" onclick="coreEdit('${key}','${id}')">•••⌄</button>`}
function coreInput(name,type='text',value='',required=false){if(type==='textarea')return `<textarea name="${name}" ${required?'required':''}>${esc(value||'')}</textarea>`;if(type==='select')return `<select name="${name}" ${required?'required':''}><option value="">Select</option></select>`;return `<input name="${name}" type="${type}" value="${esc(value||'')}" ${required?'required':''}>`}
async function coreSave(key,form){const data=Object.fromEntries(new FormData(form));const id=data._id||'';delete data._id;try{let savedId=id||String(Date.now());if(state.server&&!String(id).startsWith('seed-')){const r=await api('workflow',{workflow:key,id,payload:data});savedId=r.id}else if(state.server&&String(id).startsWith('seed-')){const r=await api('workflow',{workflow:key,id:'',payload:data});savedId=r.id;coreHideSeed(id)}state.records[key]??=[];const old=state.records[key].find(r=>String(r.id)===String(id));if(old)Object.assign(old,data,{id:savedId});else state.records[key].unshift({id:savedId,...data});persist();render();toast(id?'Record updated':'Record saved')}catch(e){toast(e.message)}}
function coreHideSeed(id){const h=JSON.parse(localStorage.getItem('scschool.coreHidden')||'[]');if(!h.includes(id))h.push(id);localStorage.setItem('scschool.coreHidden',JSON.stringify(h))}
function canDeleteSystemUser(row){const actor=String(state.currentUser?.role||'').trim().toLowerCase(),target=String(row?.Role||'').trim().toLowerCase();return !(actor==='vice school director'&&['super administrator','super admin'].includes(target))}
function canResetSystemUser(row){const actor=String(state.currentUser?.role||'').trim().toLowerCase(),target=String(row?.Role||'').trim().toLowerCase(),isSelf=String(state.currentUser?.workflow_id||'')===String(row?.id||'');return !isSelf&&['super administrator','super admin','vice school director'].includes(actor)&&!(actor==='vice school director'&&['super administrator','super admin'].includes(target))}
async function resetSystemUserPassword(id){const row=(state.records.users||[]).find(item=>String(item.id)===String(id));if(!canResetSystemUser(row))return toast('You cannot reset this account password');if(!confirm(`Generate a temporary password for ${row?.['User Name']||'this user'}?`))return;try{const result=await api('admin-reset-user-password',{id});alert(`Temporary password for ${row?.['User Name']||'user'}:\n\n${result.temporary_password}\n\nCopy it now. The user must create a new password after signing in.`);toast('Temporary password generated')}catch(error){toast(error.message)}}
async function coreDelete(key,id){const row=(state.records[key]||[]).find(r=>String(r.id)===String(id));if(key==='users'&&!canDeleteSystemUser(row))return toast('Vice School Director cannot delete a Super Administrator account');if(!confirm('Delete this record?'))return;try{if(state.server&&!String(id).startsWith('seed-'))await api('delete-workflow',{workflow:key,id});if(String(id).startsWith('seed-'))coreHideSeed(id);state.records[key]=(state.records[key]||[]).filter(r=>String(r.id)!==String(id));persist();render();toast('Record deleted')}catch(e){toast(e.message)}}
function coreEdit(key,id){state.coreEdit={key,id};const target={branch:'branch-add',users:'user-add',assets:'asset-add'}[key];if(target){navigate(target);return}render()}
function coreEditing(key){const id=state.coreEdit?.key===key?state.coreEdit.id:'';return {id,row:coreRows(key).find(r=>String(r.id)===String(id))||{}}}
async function copyNewUserTemporaryPassword(){const password=state.newUserTemporary?.password||'';if(!password)return;try{await navigator.clipboard.writeText(password);toast('Temporary password copied')}catch{const input=$('#newUserTemporaryPassword');input?.select();document.execCommand('copy');toast('Temporary password copied')}}
async function saveSystemUser(form){const fd=new FormData(form),id=String(fd.get('_id')||'');fd.delete('_id');const payload={};for(const [key,value] of fd){if(value instanceof File){if(value.size)payload[key]=await hrFileData(value)}else payload[key]=value}if(!payload['Allow Full'])payload['Allow Full']='No';try{let savedId=id,temporary='';if(state.server){const result=await api('workflow',{workflow:'users',id,payload});savedId=result.id;temporary=result.temporary_password||'';await refreshServer()}else{savedId=id||String(Date.now());state.records.users??=[];const old=state.records.users.find(row=>String(row.id)===id);if(old)Object.assign(old,payload);else state.records.users.unshift({id:savedId,...payload})}persist();if(temporary){state.coreEdit={key:'users',id:String(savedId)};state.newUserTemporary={id:String(savedId),username:payload['User Name'],password:temporary};navigate('user-add');toast('User created. Copy the temporary password shown below')}else{state.coreEdit=null;navigate('users');toast(id?'User updated':'User created with a temporary password')}}catch(error){toast(error.message)}}
function coreBind(key){const form=$('#coreForm');if(form)form.onsubmit=e=>{e.preventDefault();key==='users'?saveSystemUser(form):coreSave(key,form)};const search=$('#coreSearch');if(search)search.oninput=e=>document.querySelectorAll('.core-data-row').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(e.target.value.toLowerCase()))}
function transportRouteView(){const key='transport-route',rows=coreRows(key),ed=coreEditing(key);return `${coreBread('Student Transportation List','✚ Add Student Address')}<div class="core-split"><section class="core-card core-form-card"><h2>⚙ Add Route Information</h2><form id="coreForm"><input type="hidden" name="_id" value="${ed.id}"><label>Route Title${coreInput('Route Title','text',ed.row['Route Title'],true)}</label><label>Google Maps <em>*</em>${coreInput('Google Maps','text',ed.row['Google Maps'],true)}</label><label>Note <em>*</em>${coreInput('Note','textarea',ed.row.Note,true)}</label><button class="core-save">⚑ Save</button></form></section><section class="core-card"><h2>☷ Route List</h2>${coreTableTools()}<div class="table-scroll"><table><thead><tr><th>ID</th><th>Route Name</th><th>Google Maps</th><th>Other</th><th>Action</th></tr></thead><tbody>${rows.map((r,i)=>`<tr class="core-data-row"><td>${i+1}</td><td>${esc(r['Route Title']||'')}</td><td>${esc(r['Google Maps']||'')}</td><td>${esc(r.Note||'')}</td><td>${coreAction(key,r.id)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">No data available</td></tr>'}</tbody></table></div><div class="core-foot">Showing 1 to ${rows.length} of ${rows.length} entries</div></section></div>`}
function coreTableTools(){return `<div class="core-tools"><label class="number-to-show">◉ Number to Show <select><option>10</option><option>20</option><option>30</option><option>50</option><option>100</option><option>1000</option></select></label><label>Search <input id="coreSearch"><button type="button">⌕</button></label></div>`}
function filterSystemUsers(){const query=String($('#coreSearch')?.value||'').toLowerCase(),role=$('#userRoleFilter')?.value||'';document.querySelectorAll('.core-data-row').forEach(row=>row.hidden=!(row.textContent.toLowerCase().includes(query)&&(!role||row.dataset.role===role)))}
document.addEventListener('input',event=>{if(event.target.id==='coreSearch'&&state.page==='users')filterSystemUsers()});
document.addEventListener('change',event=>{if(event.target.id==='userRoleFilter')filterSystemUsers()});
function exportUsers(){const rows=coreRows('users'),columns=['Branche','Staff Code','First Name','Last Name','User Name','Phone','Email','Role','Status'];downloadBlob([columns.join(','),...rows.map(row=>columns.map(key=>`"${String(row[key]||'').replaceAll('"','""')}"`).join(','))].join('\n'),'system_users.csv','text/csv')}
function transportVehicleView(){const key='transport',rows=coreRows(key),ed=coreEditing(key),staff=hrRows('staff');return `${coreBread('Student Transportation List','✚ Create a new car information')}<div class="core-split"><section class="core-card core-form-card"><h2>⚙ Create a new car information</h2><form id="coreForm"><input type="hidden" name="_id" value="${ed.id}"><label>Vehicle Number${coreInput('Vehicle Number','text',ed.row['Vehicle Number'])}</label><label>Vihicle Model <em>*</em>${coreInput('Vehicle Model','text',ed.row['Vehicle Model'],true)}</label><label>Year Made <em>*</em>${coreInput('Year Made','text',ed.row['Year Made'],true)}</label><label>Driver Name <em>*</em><select name="Driver Name" required><option value="">Select driver</option>${staff.map(s=>{const n=s['Name English']||s['Name Khmer'];return `<option ${n===ed.row['Driver Name']?'selected':''}>${esc(n)}</option>`}).join('')}</select></label><label>Driver License <em>*</em>${coreInput('Driver License','text',ed.row['Driver License'],true)}</label><label>Driver Contact <em>*</em>${coreInput('Driver Contact','text',ed.row['Driver Contact'],true)}</label><label>Note${coreInput('Note','textarea',ed.row.Note)}</label><button class="core-save">▣ Save</button></form></section><section class="core-card"><h2>☷ Car information list</h2>${coreTableTools()}<div class="table-scroll"><table><thead><tr><th>ID</th><th>Vihicle Number</th><th>Driver Name</th><th>Driver Contact</th><th>Action</th></tr></thead><tbody>${rows.map((r,i)=>`<tr class="core-data-row"><td>${i+1}</td><td>${esc(r['Vehicle Number']||'')}</td><td>${esc(r['Driver Name']||'')}</td><td>${esc(r['Driver Contact']||'')}</td><td>${coreAction(key,r.id)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">No data available</td></tr>'}</tbody></table></div><div class="core-foot">Showing 1 to ${rows.length} of ${rows.length} entries</div></section></div>`}
function transportAssignView(){const key='transport-assign',rows=coreRows(key),routes=coreRows('transport-route'),vehicles=coreRows('transport'),ed=coreEditing(key);return `${coreBread('Student Transportation List','✚ Set the vehicle')}<div class="core-split"><section class="core-card core-form-card"><h2>⚙ Set the vehicle</h2><form id="coreForm"><input type="hidden" name="_id" value="${ed.id}"><label>Choose a vehicle <em>*</em><select name="Vehicle" required><option value="">Select vehicle</option>${vehicles.map(v=>`<option ${v['Vehicle Number']===ed.row.Vehicle?'selected':''}>${esc(v['Vehicle Number']||'')}</option>`).join('')}</select></label><label>Choose a Route <em>*</em><select name="Route" required><option value="">Select routes</option>${routes.map(r=>`<option ${r['Route Title']===ed.row.Route?'selected':''}>${esc(r['Route Title']||'')}</option>`).join('')}</select></label><button class="core-save">▣ Save</button></form></section><section class="core-card"><h2>☷ Set The Vehicle List</h2>${coreTableTools()}<table><thead><tr><th>ID</th><th>Vehicle Name</th><th>Route</th><th>Action</th></tr></thead><tbody>${rows.map((r,i)=>`<tr class="core-data-row"><td>${i+1}</td><td>${esc(r.Vehicle||'')}</td><td>${esc(r.Route||'')}</td><td>${coreAction(key,r.id)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">No data available</td></tr>'}</tbody></table><div class="core-foot">Showing ${rows.length?'1':'0'} to ${rows.length} of ${rows.length} entries</div></section></div>`}
function transportStudentView(){const rows=coreRows('transport-student');return `${coreBread('Student Transportation List','▣ Student Transportation Operations')}<section class="core-card core-filter-row"><label>Date <em>*</em><input type="date" value="${new Date().toISOString().slice(0,10)}"></label><label>Time <em>*</em><select><option>Morning</option><option>Afternoon</option></select></label><label>Vehical Driver <em>*</em><select><option>Testing Father admin</option></select></label><button class="core-save">⚑ Filter</button></section><section class="core-card"><div class="core-list-head"><h2>⚙ Student List</h2><div><button class="core-save" onclick="toast('Excel export prepared')">⇩ Excel</button> <button class="core-save" onclick="printCurrentView()">▣ Print</button></div></div><table><thead><tr><th>☐</th><th>Admission No</th><th>Student</th><th>Class</th><th>Time</th><th>Guardian</th><th>Route</th><th>Driver Name</th><th>Main Contact</th><th>Action</th></tr></thead><tbody>${rows.length?rows.map((r,i)=>`<tr><td>☐</td><td>${esc(r['Admission No']||'')}</td><td>${esc(r.Student||'')}</td><td>${esc(r.Class||'')}</td><td>${esc(r.Time||'')}</td><td>${esc(r.Guardian||'')}</td><td>${esc(r.Route||'')}</td><td>${esc(r['Driver Name']||'')}</td><td>${esc(r['Main Contact']||'')}</td><td>${coreAction('transport-student',r.id)}</td></tr>`).join(''):'<tr><td colspan="10" class="empty">No data available</td></tr>'}</tbody></table><div class="core-foot">Showing 0 to ${rows.length} entries</div></section>`}
function branchView(){const rows=coreRows('branch');return `${coreBread('Branchs')}<section class="core-card"><div class="core-list-head"><button class="core-orange" data-go="branch-add">✚ Add</button>${coreTableTools()}</div><table><thead><tr><th>ID</th><th>Branch Name</th><th>Branch Phone</th><th>Short Code</th><th>Code</th><th>Open Date</th><th>Action</th></tr></thead><tbody>${rows.map((r,i)=>`<tr class="core-data-row"><td>${i+1}</td><td>${esc(r['Branch Name']||'')}</td><td>${esc(r['Branch Phone']||'')}</td><td>${esc(r['Short Code']||'')}</td><td>${esc(r.Code||'')}</td><td>${esc(r['Open Date']||'')}</td><td>${coreAction('branch',r.id)}</td></tr>`).join('')}</tbody></table><div class="core-foot">Page 1 Of 1</div></section>`}
function branchAddView(){const ed=coreEditing('branch');return `${coreBread('Branchs','✚ Add')}<section class="core-card core-wide-form"><h2>Add Branch</h2><form id="coreForm"><input type="hidden" name="_id" value="${ed.id}"><div class="core-grid-5"><label>Short Code${coreInput('Short Code','text',ed.row['Short Code'])}</label><label>Code${coreInput('Code','text',ed.row.Code)}</label><label>Branch Name Eng${coreInput('Branch Name Eng','text',ed.row['Branch Name Eng'])}</label><label>Branch Name${coreInput('Branch Name','text',ed.row['Branch Name'])}</label><label>Open Date${coreInput('Open Date','date',ed.row['Open Date']||new Date().toISOString().slice(0,10))}</label></div><label>Address${coreInput('Address','textarea',ed.row.Address)}</label><div class="core-grid-2"><label>Branch Phone${coreInput('Branch Phone','textarea',ed.row['Branch Phone'])}</label><label>Note${coreInput('Note','textarea',ed.row.Note)}</label></div><label>Active<select name="Active"><option ${ed.row.Active!=='No'?'selected':''}>yes</option><option>No</option></select></label><div class="core-form-footer"><button class="core-save">▣ Save</button></div></form></section>`}
function usersView(){const rows=coreRows('users'),roles=[...new Set(rows.map(row=>row.Role).filter(Boolean))];return `${coreBread('⚙ User List')}<section class="core-card"><div class="core-list-head"><div><button class="core-orange" data-go="user-add">✚ Add</button> <button class="core-save" onclick="exportUsers()">⇩ Download (CSV)</button></div><label>Role <select id="userRoleFilter"><option value="">All Roles</option>${roles.map(role=>`<option>${esc(role)}</option>`).join('')}</select></label></div>${coreTableTools()}<div class="table-scroll"><table><thead><tr><th>ID</th><th>Branch</th><th>Photo</th><th>Staff Code</th><th>User Name</th><th>Phone</th><th>Email</th><th>Role</th><th>Status</th><th>Action</th></tr></thead><tbody>${rows.map((r,i)=>`<tr class="core-data-row" data-role="${esc(r.Role||'')}"><td>${i+1}</td><td>${esc(r.Branche||'-')}</td><td>${r.Photo?`<img class="core-avatar" src="${esc(r.Photo)}" alt="">`:'<span class="core-avatar">●</span>'}</td><td>${esc(r['Staff Code']||'')}</td><td>${esc(r['User Name']||'')}</td><td>${esc(r.Phone||'')}</td><td>${esc(r.Email||'')}</td><td><span class="core-badge">${esc(r.Role||'')}</span></td><td><span class="core-badge">${esc(r.Status||'Active')}</span></td><td>${coreAction('users',r.id)} ${canResetSystemUser(r)?`<button type="button" class="core-more" onclick="resetSystemUserPassword('${r.id}')">Reset PW</button>`:''} ${canDeleteSystemUser(r)?`<button type="button" class="core-more" onclick="coreDelete('users','${r.id}')">Delete</button>`:'<button type="button" class="core-more" disabled title="Vice School Director cannot delete a Super Administrator">Protected</button>'}</td></tr>`).join('')||'<tr><td colspan="10" class="empty">No users</td></tr>'}</tbody></table></div><div class="core-foot">Showing ${rows.length?'1':'0'} to ${rows.length} of ${rows.length} entries</div></section>`}
function userAddView(){const ed=coreEditing('users'),selected=(value,current)=>value===current?'selected':'',temporary=state.newUserTemporary&&String(state.newUserTemporary.id)===String(ed.id)?state.newUserTemporary:null;return `${coreBread('♟ User List',ed.id?'Edit User':'Add User')}<form id="coreForm" class="user-create"><input type="hidden" name="_id" value="${ed.id}"><fieldset><legend>Basic Information</legend><div class="core-grid-4"><label>Branch <em>*</em><select name="Branche" required>${branchSelectOptions(ed.row.Branche||'')}</select></label><label>Staff Code <em>*</em>${coreInput('Staff Code','text',ed.row['Staff Code']||`IIS.${String(coreRows('users').length+1).padStart(6,'0')}`,true)}</label><label>First Name <em>*</em>${coreInput('First Name','text',ed.row['First Name'],true)}</label><label>Last Name <em>*</em>${coreInput('Last Name','text',ed.row['Last Name'],true)}</label></div></fieldset><fieldset><legend>Contact & Role</legend><div class="core-grid-4"><label>Gender <em>*</em><select name="Gender" required><option ${selected('Male',ed.row.Gender)}>Male</option><option ${selected('Female',ed.row.Gender)}>Female</option></select></label><label>Phone <em>*</em>${coreInput('Phone','text',ed.row.Phone,true)}</label><label>Role <em>*</em><select name="Role" required><option value="">Select Role</option>${coreRows('user-access').map(r=>{const role=r['Access rights']||'';return `<option ${selected(role,ed.row.Role)}>${esc(role)}</option>`}).join('')}</select></label><label>Status <em>*</em><select name="Status"><option ${selected('Active',ed.row.Status||'Active')}>Active</option><option ${selected('Inactive',ed.row.Status)}>Inactive</option></select></label><label>Created Date <em>*</em>${coreInput('Created Date','date',ed.row['Created Date']||new Date().toISOString().slice(0,10),true)}</label></div></fieldset><fieldset><legend>Address</legend><div class="core-grid-4">${['Province','District','Commune','Village'].map(x=>`<label>${x}<input name="${x}" value="${esc(ed.row[x]||'')}"></label>`).join('')}</div></fieldset><fieldset><legend>Security & Profile Photo</legend><div class="core-grid-4"><label>Username <em>*</em>${coreInput('User Name','text',ed.row['User Name'],true)}</label><label>Email <em>*</em>${coreInput('Email','email',ed.row.Email,true)}</label><div class="user-password-notice ${temporary?'password-ready':''}"><b>${temporary?'Temporary password':(ed.id?'Password changes':'First-login password')}</b>${temporary?`<div class="temporary-password-copy"><input id="newUserTemporaryPassword" value="${esc(temporary.password)}" readonly><button type="button" onclick="copyNewUserTemporaryPassword()">Copy Password</button></div><small>Give this password to ${esc(temporary.username)}. It is shown only on this page.</small>`:`<small>${ed.id?'Use Reset PW from the Users List when a password reset is required.':'The system will generate a temporary password after this user is saved.'}</small>`}</div></div><div class="core-grid-4"><label>Photo${ed.row.Photo?`<img class="bank-qr-thumb" src="${esc(ed.row.Photo)}" alt="Current photo">`:''}<input type="file" name="Photo" accept="image/*"></label><label class="inline-check"><input type="checkbox" name="Allow Full" value="Yes" ${ed.row['Allow Full']==='Yes'?'checked':''}> Allow full system access</label></div></fieldset><div class="user-actions"><button type="button" data-go="users">${temporary?'✓ Done':'✖ Cancel'}</button>${temporary?'':`<button class="core-save">▣ ${ed.id?'Update User':'Save User'}</button>`}</div></form>`}
function userAccessView(){const rows=coreRows('user-access'),editing=state.coreEdit?.key==='user-access',ed=editing?coreEditing('user-access'):{id:'',row:{}};return `${coreBread('⚙ Access rights')}<section class="core-card"><div class="core-list-head"><button class="core-orange" type="button" onclick="state.coreEdit={key:'user-access',id:'new'};render()">✚ Add Role</button></div>${editing?`<form class="inline-core-form" onsubmit="event.preventDefault();coreSave('user-access',this)"><input type="hidden" name="_id" value="${ed.id==='new'?'':esc(ed.id)}"><label>Role Name <input name="Access rights" required value="${esc(ed.row['Access rights']||'')}"></label><button class="core-save">Save Role</button><button type="button" onclick="state.coreEdit=null;render()">Cancel</button></form>`:''}${coreTableTools()}<table><thead><tr><th>ID</th><th>Access rights</th><th>Action</th></tr></thead><tbody>${rows.map((r,i)=>`<tr class="core-data-row"><td>${i+1}</td><td>${esc(r['Access rights']||'')}</td><td>${coreAction('user-access',r.id)} <button type="button" class="core-more" onclick="coreDelete('user-access','${r.id}')">Delete</button></td></tr>`).join('')}</tbody></table><div class="core-foot">Showing ${rows.length?'1':'0'} to ${Math.min(rows.length,10)} of ${rows.length} entries</div></section>`}
function assetsView(){const rows=coreRows('assets');return `${coreBread('◉ Asset List')}<section class="core-card"><div class="core-list-head"><div><button class="core-orange" data-go="asset-add">✚ Add</button> <button class="core-save" onclick="printCurrentView()">▣ Print</button>　<label class="number-to-show">◉ Number to Show <select><option>10</option><option>20</option><option>30</option><option>50</option><option>100</option><option>1000</option></select></label></div><div><label>Branchs <select><option></option></select></label> <input id="coreSearch" placeholder="Search"> <button class="core-orange" type="button">⌕</button></div></div><table><thead><tr><th>Asset Name</th><th>Asset Code</th><th>Branchs</th><th>Type</th><th>Date</th><th>Asset Cost</th><th>Installment Period</th><th>Salvage Value</th><th>Current Value</th><th>Action</th></tr></thead><tbody>${rows.map(r=>`<tr class="core-data-row"><td>${esc(r['Asset Name']||'')}</td><td>${esc(r['Asset Code']||'')}</td><td>${esc(r.Branchs||'')}</td><td>${esc(r.Type||'')}</td><td>${esc(r.Date||'')}</td><td>${esc(r['Asset Cost']||'')}</td><td>${esc(r['Installment Period']||'')}</td><td>${esc(r['Salvage Value']||'')}</td><td>${esc(r['Current Value']||'')}</td><td>${coreAction('assets',r.id)}</td></tr>`).join('')}<tr class="summary"><td colspan="5">Total</td><td>${rows.reduce((a,r)=>a+Number(r['Asset Cost']||0),0).toFixed(2)}</td><td>0</td><td>0</td><td>0.00</td><td></td></tr></tbody></table><div class="core-foot">Page 1 Of 1</div></section>`}
function assetAddView(){const ed=coreEditing('assets');return `${coreBread('⚙ Asset List','✚ Add')}<section class="core-card core-wide-form"><form id="coreForm"><input type="hidden" name="_id" value="${ed.id}"><div class="core-grid-4"><label>Branchs<select name="Branchs"><option>SC1</option><option>HQ</option></select></label><label>Type<select name="Type"><option value="">Select</option>${coreRows('asset-type').map(r=>`<option>${esc(r.Name||'')}</option>`).join('')}</select></label><label>Asset Name${coreInput('Asset Name','text',ed.row['Asset Name'])}</label><label>Date${coreInput('Date','date',ed.row.Date)}</label><label>Currency<select name="Currency"><option>USD</option><option>KHR</option></select></label><label>Asset Cost${coreInput('Asset Cost','number',ed.row['Asset Cost'])}</label><label>Installment Period${coreInput('Installment Period','number',ed.row['Installment Period'])}</label><label>Depreciation Date${coreInput('Depreciation Date','date',ed.row['Depreciation Date'])}</label><label>Reference${coreInput('Reference','text',ed.row.Reference)}</label><label class="span3">Note${coreInput('Note','textarea',ed.row.Note)}</label></div><div class="core-form-footer"><button class="core-save">▣ Save</button></div></form></section>`}
function assetReportView(){return `${coreBread('✚ Report')}<section class="core-card core-filter-row"><label>Branchs<select><option>Select</option><option>SC1</option></select></label><label>Currency<select><option>Select</option><option>USD</option><option>KHR</option></select></label><label>Start Date<input type="date"></label><button class="core-save">⚑ Filter</button></section>`}
function assetTypeView(){const rows=coreRows('asset-type');return `${coreBread('◉ Asset Type')}<section class="core-card"><div class="core-list-head"><button class="core-orange" onclick="state.coreEdit={key:'asset-type',id:'new'};render()">✚ Add Type</button>${coreTableTools()}</div>${state.coreEdit?.key==='asset-type'?`<form id="coreForm" class="inline-core-form"><input type="hidden" name="_id" value="${state.coreEdit.id==='new'?'':state.coreEdit.id}"><label>Name${coreInput('Name','text',coreEditing('asset-type').row.Name,true)}</label><button class="core-save">Save</button></form>`:''}<table><thead><tr><th>ID</th><th>Name</th><th>Action</th></tr></thead><tbody>${rows.map((r,i)=>`<tr class="core-data-row"><td>${i+1}</td><td>${esc(r.Name||'')}</td><td>${coreAction('asset-type',r.id)}</td></tr>`).join('')}</tbody></table><div class="core-foot">Page 1 Of 1</div></section>`}
const settingSeed={
 'setting-content':[
  {id:'seed-slider-1',Title:'IIS1',Image:'',UpdatedBy:'Testing Father',UpdatedAt:'18 Jun 2026'},
  {id:'seed-slider-2',Title:'IIS2',Image:'',UpdatedBy:'Testing Father',UpdatedAt:'18 Jun 2026'},
  {id:'seed-slider-3',Title:'Banner',Image:'',UpdatedBy:'Testing Father',UpdatedAt:'18 Jun 2026'}
 ],
 'setting-activities':[
  {id:'seed-activity-1',Title:'Welcome to Ideally International School',Image:'',UpdatedBy:'Testing Father',UpdatedAt:'18/06/2026 10:10 AM',Status:'Active'},
  {id:'seed-activity-2',Title:'class activity',Image:'',UpdatedBy:'Testing Father',UpdatedAt:'18/06/2026 10:12 AM',Status:'Active'}
 ],
 'setting-announcement':[
  {id:'seed-announcement-1',Title:'QueenMother',Image:'',Description:'',UpdatedBy:'Testing Father',UpdatedAt:'18/06/2026 10:13 AM',Status:'Active'}
 ],
 'setting-currency':[
  {id:'seed-currency-1',Currency:'USD',Symbol:'$',Code:'USD',Rate:'1.00','Is Default':'Yes'},
  {id:'seed-currency-2',Currency:'KHR',Symbol:'៛',Code:'KHR',Rate:'4,100.00','Is Default':'No'}
 ]
};
function settingRows(key){const hidden=JSON.parse(localStorage.getItem('scschool.coreHidden')||'[]'),saved=state.records[key]||[];return [...(settingSeed[key]||[]).filter(r=>!hidden.includes(r.id)&&!saved.some(s=>s.id===r.id||(key==='setting-currency'&&String(s.Code||'').toUpperCase()===String(r.Code||'').toUpperCase()))),...saved]}
function settingSide(active){return `<aside class="setting-side"><h2>⚙ Setting Slider</h2>${[['setting-content','Slider'],['setting-activities','Activities'],['setting-announcement','Announcement'],['setting-currency','Currency'],['setting-fee','Payment Type']].map(([p,l])=>`<button data-go="${p}" class="${active===p?'active':''}">» ${l}</button>`).join('')}</aside>`}
function settingCrumb(label,back=true){return `<div class="setting-bread"><span>⌂ Dashboard</span><i>/</i><span>${esc(label)}</span>${back?'<button data-go="setting-organisation">← Back</button>':''}</div>`}
function settingThumb(row,kind='image'){const src=row.Image||'';if(src)return `<img class="setting-thumb" src="${esc(src)}" alt="${esc(row.Title||kind)}">`;return `<span class="setting-thumb setting-thumb-empty">▧</span>`}
function settingActions(key,row){return `<div class="setting-actions"><button type="button" class="setting-edit" onclick="settingEdit('${key}','${row.id}')">✎</button><button type="button" class="setting-delete" onclick="settingDelete('${key}','${row.id}')">▰</button></div>`}
function settingSliderView(){const key='setting-content',rows=settingRows(key),ed=state.settingEdit?.key===key?rows.find(r=>String(r.id)===String(state.settingEdit.id))||{}:{};return `${settingCrumb('▣ Slider')}<div class="setting-layout">${settingSide(key)}<main class="setting-main setting-slider-grid"><section class="setting-card setting-add-card"><header>⊕ Add Slider</header><form id="settingForm" data-key="${key}"><input type="hidden" name="_id" value="${esc(ed.id||'')}"><label>Title <em>*</em><input name="Title" value="${esc(ed.Title||'')}" required></label><label>Image <em>*</em><div class="setting-upload"><input id="settingImage" type="file" accept="image/jpeg,image/png,image/gif,image/webp"><div id="settingUploadPreview">${ed.Image?`<img src="${esc(ed.Image)}">`:'<b>☁</b><span>Upload Image</span><small>JPG, PNG, GIF, WEBP</small>'}</div></div></label><input type="hidden" name="Image" value="${esc(ed.Image||'')}"><button class="setting-save">▣ Save</button></form></section><section class="setting-card setting-list-card"><header>▣ Slider List</header><table><thead><tr><th>#</th><th>Title</th><th>Image</th><th>Updated By</th><th>Update At</th><th>Action</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td>${i+1}</td><td>${esc(r.Title||'')}</td><td>${settingThumb(r)}</td><td>${esc(r.UpdatedBy||'Testing Father')}</td><td>${esc(r.UpdatedAt||'')}</td><td>${settingActions(key,r)}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No slider data</td></tr>'}</tbody></table></section></main></div>`}
function settingActivitiesView(){const key='setting-activities',rows=settingRows(key),show=state.settingEdit?.key===key,ed=show?rows.find(r=>String(r.id)===String(state.settingEdit.id))||{}:{};return `${settingCrumb('Activities',false)}<div class="setting-layout">${settingSide(key)}<main class="setting-main"><section class="setting-card setting-list-card orange-top"><header><span>☷ Activities List</span><button class="setting-new" onclick="settingEdit('${key}','new')">✚ Create New Activity</button></header>${show?settingContentForm(key,ed,'Activity'):''}<table><thead><tr><th>#</th><th>Image</th><th>Title</th><th>Updated By</th><th>Update At</th><th>Status</th><th>Action</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td>${i+1}</td><td>${settingThumb(r)}</td><td>${esc(r.Title||'')}</td><td>${esc(r.UpdatedBy||'Testing Father')}</td><td>${esc(r.UpdatedAt||'')}</td><td><span class="setting-status">${esc(r.Status||'Active')}</span></td><td>${settingActions(key,r)}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">No activities</td></tr>'}</tbody></table></section></main></div>`}
function settingAnnouncementView(){const key='setting-announcement',rows=settingRows(key),show=state.settingEdit?.key===key,ed=show?(rows.find(r=>String(r.id)===String(state.settingEdit.id))||{}):{};if(show)return settingAnnouncementFormView(ed);return `${settingCrumb('Announcement',false)}<div class="setting-layout">${settingSide(key)}<main class="setting-main"><section class="setting-card setting-list-card announcement-list-card"><header><span>☷ Announcement List</span><button class="setting-new" onclick="settingEdit('${key}','new')">✚ Create New Announcement</button></header><div class="table-scroll"><table><thead><tr><th>#</th><th>Image</th><th>Title</th><th>Updated By</th><th>Update At</th><th>Status</th><th>Action</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td>${i+1}</td><td>${settingThumb(r)}</td><td>${esc(r.Title||'')}</td><td>${esc(r.UpdatedBy||'Testing Father')}</td><td>${esc(r.UpdatedAt||'')}</td><td><span class="setting-status ${r.Status==='Inactive'?'inactive':''}">${esc(r.Status||'Active')}</span></td><td>${settingActions(key,r)}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">No announcements</td></tr>'}</tbody></table></div></section></main></div>`}
function settingAnnouncementFormView(ed={}){const editing=!!(ed.id&&ed.id!=='new'),description=String(ed.Description||'');return `<div class="setting-bread announcement-bread"><span>⌂ Dashboard</span><i>/</i><button type="button" data-go="setting-announcement">Announcement</button><i>/</i><span>${editing?'Edit':'Create'}</span></div><div class="setting-layout announcement-layout">${settingSide('setting-announcement')}<main class="setting-main"><section class="announcement-form-card"><header><span>⊕</span><h2>${editing?'Edit Announcement':'Create New Announcement'}</h2></header><form id="settingForm" data-key="setting-announcement" class="announcement-form"><input type="hidden" name="_id" value="${editing?esc(ed.id):''}"><div class="announcement-field"><label>TITLE <em>*</em></label><input name="Title" value="${esc(ed.Title||'')}" placeholder="Enter announcement title..." required maxlength="180"></div><div class="announcement-field"><label>DESCRIPTION <em>*</em></label><div class="announcement-editor"><div class="announcement-toolbar" role="toolbar" aria-label="Description formatting"><select id="announcementFont" aria-label="Font"><option value="Arial">Sans Serif</option><option value="Georgia">Serif</option><option value="monospace">Monospace</option></select><select id="announcementBlock" aria-label="Paragraph style"><option value="p">Normal</option><option value="h2">Heading</option><option value="h3">Subheading</option></select><button type="button" data-editor-cmd="bold"><b>B</b></button><button type="button" data-editor-cmd="italic"><i>I</i></button><button type="button" data-editor-cmd="underline"><u>U</u></button><button type="button" data-editor-cmd="strikeThrough"><s>S</s></button><span class="announcement-toolbar-sep"></span><button type="button" data-editor-cmd="justifyLeft">≡</button><button type="button" data-editor-cmd="insertUnorderedList">•☰</button><button type="button" data-editor-cmd="insertOrderedList">1☰</button><button type="button" data-editor-cmd="createLink">🔗</button><button type="button" id="announcementClearFormat">Tx</button></div><div id="announcementEditor" class="announcement-editor-body" contenteditable="true" data-placeholder="Write a detailed announcement description...">${esc(description)}</div><input type="hidden" name="Description" id="announcementDescription" value="${esc(description)}"></div></div><div class="announcement-field announcement-image-section"><label>IMAGE <small>(JPEG, PNG, GIF, WEBP · Max 5 MB)</small></label><div class="announcement-upload" id="announcementUpload"><input id="settingImage" type="file" accept="image/jpeg,image/png,image/gif,image/webp"><div id="settingUploadPreview">${ed.Image?`<img src="${esc(ed.Image)}" alt="Announcement image preview">`:'<span class="announcement-upload-icon">☁</span><b>Click to upload</b><small>JPG, PNG, GIF, WEBP · up to 5 MB</small>'}</div></div><input type="hidden" name="Image" value="${esc(ed.Image||'')}"><p class="announcement-file-name" id="announcementFileName"></p></div><div class="announcement-field"><label>STATUS</label><div class="announcement-status-toggle"><label class="${ed.Status!=='Inactive'?'selected':''}"><input type="radio" name="Status" value="Active" ${ed.Status!=='Inactive'?'checked':''}> <span>✓</span> Active</label><label class="${ed.Status==='Inactive'?'selected':''}"><input type="radio" name="Status" value="Inactive" ${ed.Status==='Inactive'?'checked':''}> <span>×</span> Inactive</label></div></div><div class="announcement-info">ⓘ &nbsp; Upload date &amp; time will be recorded automatically upon saving.</div><footer class="announcement-form-actions"><button type="submit" class="announcement-save">▣ &nbsp;${editing?'Update Announcement':'Save Announcement'}</button><button type="button" class="announcement-cancel" onclick="state.settingEdit=null;render()">× &nbsp;Cancel</button></footer></form></section></main></div>`}
function settingContentForm(key,ed,type){return `<form id="settingForm" data-key="${key}" class="setting-inline-form"><input type="hidden" name="_id" value="${ed.id&&ed.id!=='new'?esc(ed.id):''}"><label>Title <em>*</em><input name="Title" value="${esc(ed.Title||'')}" required></label><label>Image<input id="settingImage" type="file" accept="image/*"></label><input type="hidden" name="Image" value="${esc(ed.Image||'')}">${type==='Announcement'?`<label>Description<textarea name="Description">${esc(ed.Description||'')}</textarea></label>`:''}<label>Status<select name="Status"><option ${ed.Status!=='Inactive'?'selected':''}>Active</option><option ${ed.Status==='Inactive'?'selected':''}>Inactive</option></select></label><div class="setting-form-actions"><button type="button" onclick="state.settingEdit=null;render()">Cancel</button><button class="setting-save">▣ Save ${type}</button></div></form>`}
function settingCurrencyView(){const key='setting-currency',rows=settingRows(key),show=state.settingEdit?.key===key,ed=show?rows.find(r=>String(r.id)===String(state.settingEdit.id))||{}:{};return `${settingCrumb('⚙ Currency',false)}<div class="setting-layout">${settingSide(key)}<main class="setting-main"><section class="setting-card setting-list-card currency-card"><header><button class="setting-new" onclick="settingEdit('${key}','new')">✚ Add Currency</button><span>🔧⌄</span><label class="setting-search">Search <input id="settingSearch"></label></header>${show?`<form id="settingForm" data-key="${key}" class="setting-inline-form currency-form"><input type="hidden" name="_id" value="${ed.id&&ed.id!=='new'?esc(ed.id):''}">${['Currency','Symbol','Code'].map(f=>`<label>${f}<input name="${f}" value="${esc(ed[f]||'')}" required></label>`).join('')}<label>Rate<input name="Rate" type="number" min="0.000001" step="any" value="${esc(String(ed.Rate||'').replace(/,/g,''))}" required><small>Units per 1 default currency</small></label><label>Is Default<select name="Is Default"><option value="No" ${ed['Is Default']!=='Yes'?'selected':''}>No</option><option value="Yes" ${ed['Is Default']==='Yes'?'selected':''}>Yes</option></select></label><div class="setting-form-actions"><button type="button" onclick="state.settingEdit=null;render()">Cancel</button><button class="setting-save">Save</button></div></form>`:''}<table><thead><tr><th>Currency</th><th>Symbol</th><th>Code</th><th>Rate</th><th>Is Default</th><th>Action</th></tr></thead><tbody>${rows.map(r=>`<tr class="setting-filter-row"><td>${esc(r.Currency||'')}</td><td>${esc(r.Symbol||'')}</td><td>${esc(r.Code||'')}</td><td>${currencyNumber(r.Rate).toLocaleString()}</td><td>${r['Is Default']==='Yes'?'<span class="setting-status">Is Default</span>':'<b class="not-default">Not Default</b>'}</td><td>${settingActions(key,r)}</td></tr>`).join('')}</tbody></table><div class="core-foot">Page 1 Of 1</div></section></main></div>`}
function settingPaymentTypeView(){const key='setting-fee',rows=settingRows(key),show=state.settingEdit?.key===key,ed=show?rows.find(r=>String(r.id)===String(state.settingEdit.id))||{}:{};return `${settingCrumb('⚙ Payment type',false)}<div class="setting-layout">${settingSide(key)}<main class="setting-main"><section class="setting-card setting-list-card currency-card"><header><button class="setting-new" onclick="settingEdit('${key}','new')">✚ Add</button><span>🔧⌄</span><label class="setting-search">Search <input id="settingSearch"></label></header>${show?`<form id="settingForm" data-key="${key}" class="setting-inline-form"><input type="hidden" name="_id" value="${ed.id&&ed.id!=='new'?esc(ed.id):''}"><label>Payment type<input name="Payment type" value="${esc(ed['Payment type']||'')}" required></label><label>Account Name<input name="Account Name" value="${esc(ed['Account Name']||'')}" required></label><label>Currency<select name="Currency"><option>USD</option><option>KHR</option></select></label><label>Description<textarea name="Description">${esc(ed.Description||'')}</textarea></label><div class="setting-form-actions"><button type="button" onclick="state.settingEdit=null;render()">Cancel</button><button class="setting-save">Save</button></div></form>`:''}<table><thead><tr><th>ID</th><th>Payment type</th><th>Account Name</th><th>Currency</th><th>Description</th><th>Action</th></tr></thead><tbody>${rows.map((r,i)=>`<tr class="setting-filter-row"><td>${i+1}</td><td>${esc(r['Payment type']||'')}</td><td>${esc(r['Account Name']||'')}</td><td>${esc(r.Currency||'')}</td><td>${esc(r.Description||'')}</td><td>${settingActions(key,r)}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No payment type</td></tr>'}</tbody></table><div class="core-foot">Page 1 Of 1</div></section></main></div>`}
function settingEdit(key,id){state.settingEdit={key,id};render()}
async function settingDelete(key,id){if(!confirm('Delete this record?'))return;if(String(id).startsWith('seed-'))coreHideSeed(id);else{try{if(state.server)await api('delete-workflow',{workflow:key,id})}catch(e){toast(e.message);return}state.records[key]=(state.records[key]||[]).filter(r=>String(r.id)!==String(id));persist()}state.settingEdit=null;render();toast('Record deleted')}
function readSettingImage(file){return new Promise(resolve=>{if(!file||!file.size)return resolve('');const reader=new FileReader();reader.onload=()=>resolve(String(reader.result||''));reader.onerror=()=>resolve('');reader.readAsDataURL(file)})}
async function saveSettingForm(form){const key=form.dataset.key,fd=new FormData(form),id=String(fd.get('_id')||'');fd.delete('_id');const file=$('#settingImage')?.files?.[0];if(file?.size)fd.set('Image',await readSettingImage(file));const payload=Object.fromEntries(fd);payload.UpdatedBy=payload.UpdatedBy||'Testing Father';payload.UpdatedAt=payload.UpdatedAt||new Date().toLocaleString('en-GB',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'});try{let savedId=id;if(state.server&&!String(id).startsWith('seed-')){const out=await api('workflow',{workflow:key,id:id||'',payload});savedId=out.id}else if(state.server&&String(id).startsWith('seed-')){const out=await api('workflow',{workflow:key,id:'',payload});savedId=out.id;coreHideSeed(id)}else savedId=id||String(Date.now());if(String(id).startsWith('seed-'))coreHideSeed(id);state.records[key]??=[];const old=state.records[key].find(r=>String(r.id)===String(id));if(old)Object.assign(old,payload,{id:savedId});else state.records[key].unshift({id:savedId,...payload});if(key==='setting-currency'&&payload['Is Default']==='Yes')state.records[key].forEach(row=>{row['Is Default']=String(row.id)===String(savedId)?'Yes':'No';if(String(row.id)===String(savedId))row.Rate='1'});if(key==='setting-currency'&&state.server)await refreshServer();persist();state.settingEdit=null;render();toast(id?'Record updated':'Record saved')}catch(e){toast(e.message)}}
function bindOrganisationSettings(){
 const form=$('#settingForm'),editor=$('#announcementEditor'),description=$('#announcementDescription');
 const syncEditor=()=>{if(editor&&description)description.value=editor.innerHTML.trim()};
 if(form)form.onsubmit=e=>{e.preventDefault();syncEditor();if(editor&&!editor.textContent.trim()){toast('Please enter an announcement description');editor.focus();return}saveSettingForm(form)};
 if(editor){
  editor.oninput=syncEditor;
  document.querySelectorAll('[data-editor-cmd]').forEach(button=>button.onclick=()=>{editor.focus();const cmd=button.dataset.editorCmd;if(cmd==='createLink'){const url=prompt('Enter link URL');if(url)document.execCommand('createLink',false,url)}else document.execCommand(cmd,false,null);syncEditor()});
  const font=$('#announcementFont');if(font)font.onchange=()=>{editor.focus();document.execCommand('fontName',false,font.value);syncEditor()};
  const block=$('#announcementBlock');if(block)block.onchange=()=>{editor.focus();document.execCommand('formatBlock',false,block.value);syncEditor()};
  const clear=$('#announcementClearFormat');if(clear)clear.onclick=()=>{editor.focus();document.execCommand('removeFormat',false,null);syncEditor()}
 }
 const image=$('#settingImage');
 if(image)image.onchange=async()=>{const file=image.files?.[0];if(!file)return;if(file.size>5*1024*1024){toast('Image must be 5 MB or smaller');image.value='';return}if(!/^image\/(jpeg|png|gif|webp)$/i.test(file.type)){toast('Use JPEG, PNG, GIF or WEBP image');image.value='';return}const data=await readSettingImage(file),hidden=form?.querySelector('input[name="Image"]');if(hidden)hidden.value=data;const prev=$('#settingUploadPreview');if(prev)prev.innerHTML=`<img src="${data}" alt="Image preview">`;const name=$('#announcementFileName');if(name)name.textContent=file.name};
 document.querySelectorAll('.announcement-status-toggle input').forEach(input=>input.onchange=()=>{document.querySelectorAll('.announcement-status-toggle label').forEach(label=>label.classList.toggle('selected',label.contains(input)&&input.checked))});
 const search=$('#settingSearch');if(search)search.oninput=e=>document.querySelectorAll('.setting-filter-row').forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(e.target.value.toLowerCase()))
}
function organisationSettingsView(){return `${settingCrumb('⚙ Organisation Settings')}<div class="setting-layout">${settingSide('')}<section class="core-card setting-content"><h1>Welcome to Content Area</h1><p>Main Content Description</p></section></div>`}
function generalSettingsData(){
 const saved=(state.records['setting-general']||[])[0];if(saved)return saved;try{return JSON.parse(localStorage.getItem('scschool.generalSettings')||'{}')}catch(e){return {}}
}
function generalLogoBox(id,title,src){return `<label class="general-logo-card" for="${id}"><div class="general-logo-preview" id="${id}Preview">${src?`<img src="${esc(src)}" alt="${esc(title)}">`:'<span class="general-logo-placeholder">SC</span>'}</div><small>Click to upload</small><strong>${esc(title)}</strong><input id="${id}" type="file" accept="image/jpeg,image/png,image/gif,image/webp" hidden></label>`}

function schoolIdentityData(){
 const d={companyName:'សាលារៀន ហ្គ្រែនវីយូ',companyNameEng:'Grandview School',companyAddress:'',companyEmail:'',phoneNumber:'',phoneNumber2:'',companyWebsite:'',urlMap:'',companyLogo:'',companyInvoice:'',...generalSettingsData()};
 const logo=(d.companyLogo||d.companyInvoice||'assets/sr-logo.png').trim();
 const invoiceLogo=(d.companyInvoice||d.companyLogo||'assets/sr-logo.png').trim();
 const website=(d.companyWebsite||'').trim();
 return {
  name:(d.companyName||'សាលារៀន ហ្គ្រែនវីយូ').trim(),
  nameEng:(d.companyNameEng||'Grandview School').trim(),
  address:([d.companyAddress,d.companyAddressLine2].map(value=>String(value||'').trim()).filter(Boolean).join(', ')||'Please set the school address in Settings → General Settings.'),
  email:(d.companyEmail||'').trim(),
  phone:([d.phoneNumber,d.phoneNumber2].map(value=>String(value||'').trim()).filter(Boolean).join(' / ')),
  website,
  mapUrl:(d.urlMap||'').trim(),
  logo,
  invoiceLogo
 };
}
function schoolWebsiteHref(value){const v=String(value||'').trim();if(!v)return '#';return /^https?:\/\//i.test(v)?v:'https://'+v}
function schoolContactLineMarkup(className='system-school-contact'){
 const school=schoolIdentityData(),parts=[];
 if(school.address)parts.push(`<span data-system-address>${esc(school.address)}</span>`);
 if(school.phone)parts.push(`<span>Tel. <b data-system-phone>${esc(school.phone)}</b></span>`);
 if(school.email)parts.push(`<span>Email: <a data-system-email href="mailto:${esc(school.email)}">${esc(school.email)}</a></span>`);
 if(school.website)parts.push(`<span>Website: <a data-system-website href="${esc(schoolWebsiteHref(school.website))}" target="_blank" rel="noopener">${esc(school.website)}</a></span>`);
 return `<span class="${esc(className)}">${parts.join(' &nbsp; ')}</span>`;
}
function systemLogoMarkup(className='',purpose='company',extra=''){
 const school=schoolIdentityData();
 const src=purpose==='invoice'?school.invoiceLogo:school.logo;
 return `<img class="${esc(className)}" data-system-logo="${purpose}" src="${esc(src)}" alt="${esc(school.name)} logo" ${extra||''}>`;
}
function scheduleWatermarkLogoMarkup(className='academic-schedule-watermark-logo'){
 const school=schoolIdentityData();
 const primary=(school.logo||'').trim();
 const fallback=(school.invoiceLogo||'assets/sr-logo.png').trim();
 const src=primary||fallback||'assets/sr-logo.png';
 return `<img class="${esc(className)}" data-system-watermark-logo src="${esc(src)}" data-fallback-src="${esc(fallback||'assets/sr-logo.png')}" alt="" aria-hidden="true">`;
}
function applySystemBranding(){
 const school=schoolIdentityData();
 document.querySelectorAll('[data-system-logo="company"]').forEach(img=>{if(img.tagName==='IMG')img.src=school.logo});
 document.querySelectorAll('[data-system-logo="invoice"]').forEach(img=>{if(img.tagName==='IMG')img.src=school.invoiceLogo});
 document.querySelectorAll('[data-system-watermark-logo]').forEach(img=>{if(img.tagName!=='IMG')return;const fallback=img.dataset.fallbackSrc||school.invoiceLogo||'assets/sr-logo.png';img.onerror=()=>{const current=String(img.getAttribute('src')||'');if(current!==fallback){img.src=fallback;return}img.onerror=null;img.src='assets/sr-logo.png'};if(!img.getAttribute('src'))img.src=school.logo||fallback||'assets/sr-logo.png'});
 document.querySelectorAll('[data-system-name]').forEach(el=>el.textContent=school.nameEng||school.name);
 document.querySelectorAll('[data-system-address]').forEach(el=>el.textContent=school.address);
 document.querySelectorAll('[data-system-phone]').forEach(el=>el.textContent=school.phone);
 document.querySelectorAll('[data-system-email]').forEach(el=>{el.textContent=school.email;if(el.tagName==='A')el.href=school.email?'mailto:'+school.email:'#'});
 document.querySelectorAll('[data-system-website]').forEach(el=>{el.textContent=school.website;if(el.tagName==='A')el.href=schoolWebsiteHref(school.website)});
 const favicon=document.querySelector('link[rel="icon"]');if(favicon)favicon.href=school.logo;
 applyAcademicsWatermark();
}
function applyAcademicsWatermark(){
 // Keep the school logo available only for printable schedule watermarks.
 // Do not place a watermark over every Academics screen.
 const school=schoolIdentityData();
 content.classList.remove('academics-watermark-page');
 content.removeAttribute('data-academic-watermark');
 const safe=String(school.logo||school.invoiceLogo||'assets/sr-logo.png').replace(/\\/g,'\\\\').replace(/"/g,'\\"');
 document.documentElement.style.setProperty('--academics-watermark-image',`url("${safe}")`);
}
function staffAttendanceStationToken(){
 let token=localStorage.getItem('scschool.staffAttendanceStationToken');
 if(!token){token='STAFF-'+Math.random().toString(36).slice(2,10).toUpperCase();localStorage.setItem('scschool.staffAttendanceStationToken',token)}
 return token;
}
function staffAttendanceQrUrl(){
 const u=new URL(window.location.href);u.searchParams.set('page','hr-scan');u.searchParams.set('station',staffAttendanceStationToken());u.hash='staff-attendance';return u.toString();
}
function activeSchoolBankAccount(currency=''){const rows=state.records?.['setting-bank-account']||[],code=currencyCode(currency);return rows.find(row=>row.Status!=='Inactive'&&String(row.Currency||code).toUpperCase()===code)||rows.find(row=>row.Status!=='Inactive')||null}
function invoiceBankQrMarkup(currency='USD',className='invoice-bank-payment'){const bank=activeSchoolBankAccount(currency);if(!bank)return `<div class="${className} invoice-bank-missing"><b>Bank QR is not configured</b><small>Settings → Bank Account Information</small></div>`;const payload=['Bank: '+(bank['Bank Name']||''),'Account Name: '+(bank['Account Name']||''),'Account Number: '+(bank['Account Number']||''),'Currency: '+(bank.Currency||currency),'SWIFT: '+(bank.SWIFT||'')].join('\n'),src=bank['QR Image']||('https://api.qrserver.com/v1/create-qr-code/?size=360x360&margin=12&data='+encodeURIComponent(payload)),admission=className.includes('admission-bank-payment'),details=admission?(bank['Account Number']||''):[bank['Account Name']||'',bank['Account Number']||'',bank.Currency||currency].filter(Boolean).join(' · ');return `<div class="${className}"><img src="${esc(src)}" alt="${esc(bank['Bank Name']||'School bank')} payment QR"><b>${esc(bank['Bank Name']||'Bank Account')}</b><small>${esc(details)}</small></div>`}
function qrImageUrl(value){const bank=!/^https?:\/\//i.test(String(value))?activeSchoolBankAccount('USD'):null;if(bank)return bank['QR Image']||'https://api.qrserver.com/v1/create-qr-code/?size=360x360&margin=12&data='+encodeURIComponent(['Bank: '+(bank['Bank Name']||''),'Account Name: '+(bank['Account Name']||''),'Account Number: '+(bank['Account Number']||''),'Currency: '+(bank.Currency||'USD')].join('\n'));return 'https://api.qrserver.com/v1/create-qr-code/?size=360x360&margin=12&data='+encodeURIComponent(value)}
function hrScanAttendanceView(){
 const school=schoolIdentityData(),qrValue=staffAttendanceQrUrl(),savedColor=localStorage.getItem('scschool.hrScanBrandColor')||'';
 return `<section class="hr-scan-school-page">
  <div class="front-breadcrumb"><span>⌂ Dashboard</span><i>/</i><span>Mini HR</span><i>/</i><span>Scan Attendance</span><button type="button" data-go="dashboard">← Back</button></div>
  <div class="hr-scan-school-card" ${savedColor?`style="--school-brand:${esc(savedColor)}"`:''}>
   <header class="hr-scan-school-head">
    <img class="hr-scan-school-logo" src="${esc(school.logo)}" alt="${esc(school.name)} logo" onerror="this.src='assets/sr-logo.png'">
    <h1>${esc(school.name)}</h1>
    ${school.nameEng&&school.nameEng!==school.name?`<p>${esc(school.nameEng)}</p>`:''}
   </header>
   <main class="hr-scan-qr-area">
    <div class="hr-scan-qr-frame"><img id="staffAttendanceQr" src="${qrImageUrl(qrValue)}" alt="Staff attendance QR code"><div id="staffQrFallback" class="hr-scan-qr-fallback" hidden>QR</div></div>
    <div class="hr-scan-actions"><button type="button" class="btn secondary" id="refreshStaffQr">↻ Refresh QR</button><button type="button" class="btn primary" id="copyStaffAttendanceLink">Copy Attendance Link</button><button type="button" class="btn secondary hr-color-edit-button" id="editHrScanColor">✎ Edit Color</button></div>
    <div class="hr-scan-color-editor" id="hrScanColorEditor" hidden>
      <label>Card Color <input type="color" id="hrScanColorPicker" value="${savedColor||'#24b34b'}"></label>
      <div class="hr-scan-color-presets">
       ${['#24b34b','#1769c2','#7c3aed','#0f766e','#dc2626','#ea580c','#17355c','#111827'].map(c=>`<button type="button" class="hr-color-preset" data-color="${c}" style="--preset:${c}" aria-label="Use ${c}"></button>`).join('')}
      </div>
      <div class="hr-scan-color-actions"><button type="button" class="btn primary" id="saveHrScanColor">Save Color</button><button type="button" class="btn secondary" id="useLogoHrScanColor">Use Logo Color</button></div>
    </div>
   </main>
   <footer class="hr-scan-school-footer">${esc(school.address)}</footer>
  </div>
 </section>`;
}
function logoBrandColor(img){
 try{
  const c=document.createElement('canvas'),ctx=c.getContext('2d',{willReadFrequently:true});if(!ctx)return '#17355c';
  c.width=72;c.height=72;ctx.drawImage(img,0,0,72,72);
  const data=ctx.getImageData(0,0,72,72).data;let best=null,bestScore=-1;
  for(let i=0;i<data.length;i+=16){const r=data[i],g=data[i+1],b=data[i+2],a=data[i+3];if(a<170)continue;const max=Math.max(r,g,b),min=Math.min(r,g,b),sat=max-min,lum=(r+g+b)/3;if(lum>238||lum<25||sat<18)continue;const score=sat*1.7-Math.abs(lum-115)*.35;if(score>bestScore){bestScore=score;best=[r,g,b]}}
  if(!best)return '#17355c';return `rgb(${best[0]}, ${best[1]}, ${best[2]})`;
 }catch{return '#17355c'}
}
function applyHrScanBrandColor(forceLogo=false){
 const logo=$('.hr-scan-school-logo'),card=$('.hr-scan-school-card');if(!logo||!card)return;
 const saved=localStorage.getItem('scschool.hrScanBrandColor');
 if(saved&&!forceLogo){card.style.setProperty('--school-brand',saved);return}
 const apply=()=>{const color=logoBrandColor(logo);card.style.setProperty('--school-brand',color);const picker=$('#hrScanColorPicker');if(picker)picker.value=rgbToHex(color)||picker.value};
 if(logo.complete&&logo.naturalWidth)apply();else logo.addEventListener('load',apply,{once:true});
}
function rgbToHex(color){
 if(/^#[0-9a-f]{6}$/i.test(color))return color;
 const m=String(color).match(/rgba?\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)/i);if(!m)return '';
 return '#'+[m[1],m[2],m[3]].map(v=>Math.max(0,Math.min(255,Number(v))).toString(16).padStart(2,'0')).join('');
}
function bindHrScanAttendance(){
 const qr=$('#staffAttendanceQr');if(!qr)return;
 const loadAttendanceStation=async()=>{try{const station=await api('attendance-station');qr.hidden=false;qr.src='https://api.qrserver.com/v1/create-qr-code/?size=360x360&margin=12&data='+encodeURIComponent(station.payload);qr.dataset.payload=station.payload;qr.dataset.expires=station.expires_at;const fallback=$('#staffQrFallback');if(fallback)fallback.hidden=true}catch(error){toast(error.message)}};
 loadAttendanceStation();
 applyHrScanBrandColor();
 qr.onerror=()=>{qr.hidden=true;const fallback=$('#staffQrFallback');if(fallback)fallback.hidden=false};
 const refresh=$('#refreshStaffQr');if(refresh)refresh.onclick=async()=>{await loadAttendanceStation();toast('Attendance QR refreshed')};
 const copy=$('#copyStaffAttendanceLink');if(copy)copy.onclick=async()=>{const value=qr.dataset.payload||'';try{await navigator.clipboard.writeText(value);toast('Attendance QR payload copied')}catch{prompt('Copy attendance QR payload:',value)}};
 const editor=$('#hrScanColorEditor'),edit=$('#editHrScanColor'),picker=$('#hrScanColorPicker'),card=$('.hr-scan-school-card');
 if(edit&&editor)edit.onclick=()=>{editor.hidden=!editor.hidden;if(!editor.hidden&&picker){const current=getComputedStyle(card).getPropertyValue('--school-brand').trim();picker.value=rgbToHex(current)||picker.value}};
 if(picker)picker.oninput=()=>card?.style.setProperty('--school-brand',picker.value);
 document.querySelectorAll('.hr-color-preset').forEach(button=>button.onclick=()=>{const color=button.dataset.color;if(picker)picker.value=color;card?.style.setProperty('--school-brand',color)});
 const save=$('#saveHrScanColor');if(save)save.onclick=()=>{const color=picker?.value||'#17355c';localStorage.setItem('scschool.hrScanBrandColor',color);card?.style.setProperty('--school-brand',color);if(editor)editor.hidden=true;toast('Attendance card color saved')};
 const logoColor=$('#useLogoHrScanColor');if(logoColor)logoColor.onclick=()=>{localStorage.removeItem('scschool.hrScanBrandColor');applyHrScanBrandColor(true);if(editor)editor.hidden=true;toast('Logo color restored')};
}
function settingsGeneralView(){const d={companyName:'សាលារៀន ហ្គ្រែនវីយូ',companyAddress:'',companyCountry:'Cambodia',timezone:'Asia/Phnom_Penh',companyEmail:'',companyNameEng:'Grandview School',phoneNumber:'',phoneNumber2:'',companyWebsite:'',urlMap:'',companyLogo:'',companyInvoice:'',...generalSettingsData()};return `<section class="general-settings-page"><div class="general-settings-head"><div><h1>General Settings</h1><button type="button" data-go="setting-organisation">Back</button></div><div class="general-settings-crumb"><span>Dashboard</span><i>/</i><span>General Settings</span></div></div><form id="generalSettingsForm" class="general-settings-card"><div class="general-settings-body"><aside class="general-logo-column">${generalLogoBox('companyLogo','Company Logo',d.companyLogo)}${generalLogoBox('companyInvoice','Company Invoice',d.companyInvoice)}</aside><div class="general-settings-fields"><label>School Name (Khmer)<input name="companyName" value="${esc(d.companyName)}"></label><label>@Company Address<textarea name="companyAddress">${esc(d.companyAddress)}</textarea></label><label>@Company Country<select name="companyCountry"><option ${d.companyCountry==='Cambodia'?'selected':''}>Cambodia</option><option ${d.companyCountry==='Thailand'?'selected':''}>Thailand</option><option ${d.companyCountry==='Vietnam'?'selected':''}>Vietnam</option><option ${d.companyCountry==='China'?'selected':''}>China</option><option ${d.companyCountry==='United States'?'selected':''}>United States</option></select></label><label>@Timezone<select name="timezone"><option ${d.timezone==='Asia/Phnom_Penh'?'selected':''}>Asia/Phnom_Penh</option><option ${d.timezone==='Asia/Bangkok'?'selected':''}>Asia/Bangkok</option><option ${d.timezone==='Asia/Ho_Chi_Minh'?'selected':''}>Asia/Ho_Chi_Minh</option><option ${d.timezone==='Asia/Shanghai'?'selected':''}>Asia/Shanghai</option><option ${d.timezone==='Europe/Berlin'?'selected':''}>Europe/Berlin</option></select></label><label>@Company Email<input type="email" name="companyEmail" value="${esc(d.companyEmail)}"></label><label>School Name (English)<input name="companyNameEng" value="${esc(d.companyNameEng)}"></label><label>@Phone Number<input name="phoneNumber" value="${esc(d.phoneNumber)}" placeholder="Primary school phone number"></label><label>@Phone Number 2<input name="phoneNumber2" value="${esc(d.phoneNumber2||'')}" placeholder="Second school phone number"></label><label>@Website<input name="companyWebsite" value="${esc(d.companyWebsite||'')}" placeholder="https://www.example.com"></label><label>@URL Map<input name="urlMap" value="${esc(d.urlMap)}" placeholder="Google Maps URL"></label></div></div><input type="hidden" name="companyLogo" value="${esc(d.companyLogo)}"><input type="hidden" name="companyInvoice" value="${esc(d.companyInvoice)}"><footer><button class="general-settings-save" type="submit">▣ Save</button></footer></form></section>`}
function bindGeneralSettings(){const form=$('#generalSettingsForm');if(!form)return;const heading=form.closest('.general-settings-page')?.querySelector('.general-settings-head>div:first-child');if(heading&&!heading.querySelector('[data-go="setting-bank-account"]'))heading.insertAdjacentHTML('beforeend','<button type="button" class="bank-account-link" data-go="setting-bank-account">Bank Account Information</button>');bindPage();const bindImage=(id,name)=>{const input=$('#'+id),preview=$('#'+id+'Preview'),hidden=form.querySelector(`input[name="${name}"]`);if(!input)return;input.onchange=async()=>{const file=input.files?.[0];if(!file)return;const data=await readSettingImage(file);if(hidden)hidden.value=data;if(preview)preview.innerHTML=`<img src="${data}" alt="${name}">`}};bindImage('companyLogo','companyLogo');bindImage('companyInvoice','companyInvoice');form.onsubmit=async e=>{e.preventDefault();const payload=Object.fromEntries(new FormData(form));try{let id=String((state.records['setting-general']||[])[0]?.id||'');if(state.server){const saved=await api('workflow',{workflow:'setting-general',id,payload});id=saved.id}state.records['setting-general']=[{id:id||String(Date.now()),...payload}];localStorage.setItem('scschool.generalSettings',JSON.stringify(payload));persist();applySystemBranding();toast('General settings saved');render()}catch(error){toast(error.message)}}}

function bankAccountSettingsView(){
 const rows=state.records['setting-bank-account']||[];
 return `<section class="bank-settings-page"><div class="general-settings-head"><div><h1>Bank Account Information</h1><button type="button" data-go="settings">General Settings</button></div><div class="general-settings-crumb"><span>Dashboard</span><i>/</i><span>Bank Account Information</span></div></div><div class="bank-settings-layout"><form id="bankAccountForm" class="bank-account-form"><input type="hidden" name="_id"><header><h2 id="bankAccountFormTitle">Add Bank Account</h2><p>Bank information can be reused for invoices and payment instructions.</p></header><div class="bank-account-fields"><label>Bank Name <em>*</em><input name="Bank Name" required></label><label>Account Name <em>*</em><input name="Account Name" required></label><label>Account Number <em>*</em><input name="Account Number" required></label><label>Currency <em>*</em><select name="Currency" required><option>USD</option><option>KHR</option></select></label><label>Branch<input name="Branch"></label><label>SWIFT / BIC<input name="SWIFT"></label><label>Status<select name="Status"><option>Active</option><option>Inactive</option></select></label><label class="bank-note">Note<textarea name="Note" rows="3"></textarea></label><label class="bank-qr-upload">QR Payment Image<input id="bankQrFile" type="file" accept="image/jpeg,image/png,image/webp"><input type="hidden" name="QR Image"><span id="bankQrPreview">Choose QR image</span></label></div><footer><button type="button" id="bankAccountCancel" hidden>Cancel</button><button type="submit">Save Bank Account</button></footer></form><section class="bank-account-list"><header><div><h2>Bank Accounts</h2><p>${rows.length} saved account${rows.length===1?'':'s'}</p></div><label>Search <input id="bankAccountSearch"></label></header><div class="table-scroll"><table><thead><tr><th>No.</th><th>Bank</th><th>Account Name</th><th>Account Number</th><th>Currency</th><th>Branch</th><th>Status</th><th>QR</th><th>Action</th></tr></thead><tbody id="bankAccountRows">${rows.length?rows.map((row,index)=>`<tr data-id="${esc(row.id)}"><td>${index+1}</td><td>${esc(row['Bank Name']||'')}</td><td>${esc(row['Account Name']||'')}</td><td>${esc(row['Account Number']||'')}</td><td>${esc(row.Currency||'')}</td><td>${esc(row.Branch||'')}</td><td><span class="bank-status ${row.Status==='Inactive'?'inactive':''}">${esc(row.Status||'Active')}</span></td><td>${row['QR Image']?`<img class="bank-qr-thumb" src="${esc(row['QR Image'])}" alt="QR">`:'—'}</td><td><button type="button" class="bank-edit" data-id="${esc(row.id)}">Edit</button><button type="button" class="bank-delete" data-id="${esc(row.id)}">Delete</button></td></tr>`).join(''):'<tr><td colspan="9" class="empty">No bank accounts found.</td></tr>'}</tbody></table></div></section></div></section>`
}
function bindBankAccountSettings(){
 const form=$('#bankAccountForm');if(!form)return;const rows=()=>state.records['setting-bank-account']||[],preview=$('#bankQrPreview');
 const reset=()=>{form.reset();form.elements._id.value='';form.elements['QR Image'].value='';preview.innerHTML='Choose QR image';$('#bankAccountFormTitle').textContent='Add Bank Account';$('#bankAccountCancel').hidden=true};
 $('#bankQrFile').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;try{const data=await readSettingImage(file);form.elements['QR Image'].value=data;preview.innerHTML=`<img src="${data}" alt="QR preview">`}catch(error){e.target.value='';toast(error.message)}};
 document.querySelectorAll('.bank-edit').forEach(button=>button.onclick=()=>{const row=rows().find(item=>String(item.id)===button.dataset.id);if(!row)return;reset();form.elements._id.value=row.id;['Bank Name','Account Name','Account Number','Currency','Branch','SWIFT','Status','Note','QR Image'].forEach(name=>{if(form.elements[name])form.elements[name].value=row[name]||''});preview.innerHTML=row['QR Image']?`<img src="${esc(row['QR Image'])}" alt="QR preview">`:'Choose QR image';$('#bankAccountFormTitle').textContent='Edit Bank Account';$('#bankAccountCancel').hidden=false;form.scrollIntoView({behavior:'smooth',block:'start'})});
 document.querySelectorAll('.bank-delete').forEach(button=>button.onclick=async()=>{if(!confirm('Delete this bank account?'))return;try{if(state.server)await api('delete-workflow',{workflow:'setting-bank-account',id:button.dataset.id});state.records['setting-bank-account']=rows().filter(item=>String(item.id)!==button.dataset.id);persist();render();toast('Bank account deleted')}catch(error){toast(error.message)}});
 $('#bankAccountCancel').onclick=reset;$('#bankAccountSearch').oninput=e=>document.querySelectorAll('#bankAccountRows tr[data-id]').forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(e.target.value.toLowerCase()));
 form.onsubmit=async event=>{event.preventDefault();const payload=Object.fromEntries(new FormData(form)),editId=payload._id||'';delete payload._id;try{let id=editId||String(Date.now());if(state.server){const saved=await api('workflow',{workflow:'setting-bank-account',id:editId,payload});id=saved.id}state.records['setting-bank-account']??=[];const found=state.records['setting-bank-account'].find(row=>String(row.id)===String(editId));if(found)Object.assign(found,payload,{id});else state.records['setting-bank-account'].unshift({id,...payload});persist();render();toast(editId?'Bank account updated':'Bank account saved')}catch(error){toast(error.message)}}
}
const bindPrintInvoicesWithoutBankQr=bindPrintInvoices;
bindPrintInvoices=function(){bindPrintInvoicesWithoutBankQr();document.querySelectorAll('.invoice-print').forEach(button=>button.onclick=()=>{const payment=state.payments.find(item=>String(item.id)===button.dataset.id);if(!payment)return;const popup=window.open('','invoice','width=820,height=780');if(!popup)return toast('Allow pop-ups to print invoices');const bank=invoiceBankQrMarkup(payment.currency||'USD','invoice-bank-payment popup-invoice-bank');popup.document.write(`<title>${esc(payment.receipt)}</title><style>body{font-family:Arial;padding:38px;color:#152238}header{border-bottom:2px solid #2679a7}table{width:100%;border-collapse:collapse;margin-top:25px}td,th{padding:11px;border:1px solid #d7dee7;text-align:left}.invoice-bank-payment{margin:28px auto 0;text-align:center;width:240px}.invoice-bank-payment img{display:block;width:150px;height:150px;object-fit:contain;margin:0 auto 8px}.invoice-bank-payment b,.invoice-bank-payment small{display:block;margin-top:4px}.invoice-bank-missing{border:1px dashed #dc3545;padding:20px;color:#b91c1c}</style><header><h1>WG SYSTEM</h1><h2>Invoice ${esc(payment.receipt)}</h2></header><p>Student: <b>${esc(payment.student_name||payment.student_id)}</b></p><p>Date Paid: ${String(payment.paid_at).slice(0,10)}</p><table><tr><th>Fees</th><th>Pay By</th><th>Currency</th><th>Amount Paid</th></tr><tr><td>${esc(payment.category)}</td><td>${esc(payment.method)}</td><td>${esc(payment.currency||'USD')}</td><td>${money(payment.amount)}</td></tr></table>${bank}<script>addEventListener('load',()=>print())<\/script>`);popup.document.close()})};

const renderWithBankSettings=render;
render=function(){if(state.page!=='setting-bank-account')return renderWithBankSettings();content.innerHTML=bankAccountSettingsView();bindPage();bindBankAccountSettings();enhanceActionIcons(content);translateDocument();applySystemBranding()};



