function schoolSetupData(){try{return {...schoolSetupSeed,...JSON.parse(localStorage.getItem('sc_school_setup_data')||'{}')}}catch(e){return structuredClone(schoolSetupSeed)}}
function saveSchoolSetupData(d){localStorage.setItem('sc_school_setup_data',JSON.stringify(d))}
function schoolSide(){const tabs=[['program','Program'],['time','Time'],['class','Class'],['classStart','Class Start'],['feeType','Fees Type'],['feeMaster','Fees Master'],['otherFee','Other Fee'],['carFee','Car Fee'],['room','Room'],['discount','Discount']];return `<aside class="school-setup-side"><h3>⚙ School Setup</h3>${tabs.map(([id,label])=>`<button type="button" data-school-tab="${id}" class="${schoolSetupTab===id?'active':''}">» ${label}</button>`).join('')}</aside>`}
function schoolToolbar(title,addLabel,filters=''){return `<header class="school-card-head"><strong>☷ ${title}</strong>${addLabel?`<button class="school-add" type="button" data-school-add="1">＋ ${addLabel}</button>`:''}</header>${filters?`<div class="school-filters">${filters}</div>`:''}<div class="school-table-tools"><label>Show <select><option>10</option><option>20</option><option>50</option></select> entries</label><label>Search: <input type="search" id="schoolSearch"></label></div>`}
function schoolAction(id){return `<div class="school-action-wrap"><button class="school-action" type="button" data-id="${esc(id)}">•••⌄</button><div class="school-action-menu" hidden><button type="button" class="school-action-edit" data-id="${esc(id)}">✎ Edit</button><button type="button" class="school-action-delete" data-id="${esc(id)}">🗑 Delete</button></div></div>`}
function schoolSetupTable(tab,d){
  if(tab==='program') return `${schoolToolbar('Curriculum List','Add Curriculum',`<select><option>Select branches</option><option>SC1</option></select>`)}<table><thead><tr><th>ID</th><th>Branch</th><th>Session</th><th>Program</th><th>Action</th></tr></thead><tbody>${d.program.map(r=>`<tr><td>${r.id}</td><td>${esc(r.branch)}</td><td>${esc(r.session)}</td><td>${esc(r.program)}</td><td>${schoolAction(r.id)}</td></tr>`).join('')}</tbody></table>`;
  if(tab==='time') return `${schoolToolbar('Section List','Add Section')}<table><thead><tr><th>ID</th><th>Section Name</th><th>Branches</th><th>Action</th></tr></thead><tbody>${d.time.map(r=>`<tr><td>${r.id}</td><td>${esc(r.name)}</td><td>${esc(r.branch)}</td><td>${schoolAction(r.id)}</td></tr>`).join('')}</tbody></table>`;
  if(tab==='class') return `${schoolToolbar('Class List','Create Class',`<select><option>Select Branch</option><option>SC1</option></select><select><option>Select Curriculum</option>${d.program.map(x=>`<option>${esc(x.program)}</option>`).join('')}</select>`)}<table><thead><tr><th>ID</th><th>Program</th><th>Class</th><th>Level</th><th>Time</th><th>Action</th></tr></thead><tbody>${d.class.map(r=>`<tr><td>${r.id}</td><td>${esc(r.program)}<small>${esc(r.branch)}</small></td><td>${esc(r.class)}</td><td>${esc(r.level)}</td><td>${esc(r.time)}</td><td>${schoolAction(r.id)}</td></tr>`).join('')}</tbody></table>`;
  if(tab==='classStart') return `${schoolToolbar('Class Start List','Add Class Start',`<select><option>Select Branch</option><option>SC1</option></select><select><option>Select Program</option>${d.program.map(x=>`<option>${esc(x.program)}</option>`).join('')}</select>`)}<table><thead><tr><th>ID</th><th>Branch</th><th>Program</th><th>Class</th><th>Start Date</th><th>End Date</th><th>Total Students</th><th>Available Seats</th><th>Status</th><th>Action</th></tr></thead><tbody>${d.classStart.map(r=>`<tr><td>${r.id}</td><td>${esc(r.branch)}</td><td>${esc(r.program)}</td><td>${esc(r.class)}</td><td>${esc(r.start)}</td><td>${esc(r.end)}</td><td>${r.students}</td><td>${r.seats}</td><td><span class="school-active">${esc(r.status)}</span></td><td>${schoolAction(r.id)}</td></tr>`).join('')}</tbody></table>`;
  if(tab==='feeType') return `${schoolToolbar('Fees Type List','Add Fees Type')}<table><thead><tr><th>ID</th><th>Fee Type Name</th><th>Account Name</th><th>Description</th><th>Action</th></tr></thead><tbody>${d.feeType.map(r=>`<tr><td>${r.id}</td><td>${esc(r.name)}<small>${esc(r.slug)}</small></td><td>${esc(r.account)}</td><td>${esc(r.description)}</td><td>${schoolAction(r.id)}</td></tr>`).join('')}</tbody></table>`;
  if(tab==='feeMaster') return `${schoolToolbar('Fees Master List','Add Fees Master',`<select><option>Select branches</option><option>SC1</option></select><select><option>Select curriculum</option>${d.program.map(x=>`<option>${esc(x.program)}</option>`).join('')}</select>`)}<table><thead><tr><th>ID</th><th>Branch</th><th>Program</th><th>Class</th><th>Level</th><th>Description</th><th>Action</th></tr></thead><tbody>${d.feeMaster.map(r=>`<tr><td>${r.id}</td><td>${esc(r.branch)}</td><td>${esc(r.program)}</td><td>${esc(r.class)}</td><td>${esc(r.level)}</td><td><ul class="fee-lines">${r.desc.map((x,i)=>`<li><b>${esc(x.split(' (')[0])}</b> ${esc('('+x.split(' (').slice(1).join(' ('))}</li>`).join('')}</ul></td><td>${schoolAction(r.id)}</td></tr>`).join('')}</tbody></table>`;
  if(tab==='otherFee') return `${schoolToolbar('Fees Master List','Add Other Fees',`<select><option>Select branches</option><option>SC1</option></select><select><option>Select fee</option>${d.feeType.map(x=>`<option>${esc(x.name)}</option>`).join('')}</select>`)}<table><thead><tr><th>ID</th><th>Branches</th><th>Fee Type</th><th>Description</th><th>Action</th></tr></thead><tbody>${d.otherFee.length?d.otherFee.map(r=>`<tr><td>${r.id}</td><td>${esc(r.branch)}</td><td>${esc(r.feeType)}</td><td>${esc(r.description)}</td><td>${schoolAction(r.id)}</td></tr>`).join(''):'<tr><td colspan="5" class="empty">No data available in table</td></tr>'}</tbody></table>`;
  if(tab==='carFee') return `${schoolToolbar('Fees Master List','Add Car Fee',`<select><option>Select branch</option><option>SC1</option></select><select><option>Select fee type</option><option>Transport Fee</option></select>`)}<table><thead><tr><th>#</th><th>Branch</th><th>Fee Type</th><th>Description</th><th>Action</th></tr></thead><tbody>${d.carFee.map(r=>`<tr><td>${r.id}</td><td>${esc(r.branch)}</td><td>${esc(r.feeType)}</td><td><ul class="fee-lines car">${r.description.map(x=>`<li><b>${esc(x.split(' (')[0])}</b> ${esc('('+x.split(' (').slice(1).join(' ('))}</li>`).join('')}</ul></td><td>${schoolAction(r.id)}</td></tr>`).join('')}</tbody></table>`;
  if(tab==='room') return `${schoolToolbar('Room List','Add Room')}<table><thead><tr><th>ID</th><th>Room Name</th><th>Action</th></tr></thead><tbody>${d.room.slice(0,10).map(r=>`<tr><td>${r.id}</td><td>${esc(r.name)}</td><td>${schoolAction(r.id)}</td></tr>`).join('')}</tbody></table><div class="school-pagination"><span>Showing 1 to 10 of ${d.room.length} entries</span><div><button>‹</button><b>1</b><button>2</button><button>3</button><button>4</button><button>›</button></div></div>`;
  return `${schoolToolbar('Discount List','Create Discount')}<table><thead><tr><th>ID</th><th>Discount Name</th><th>Discount Code</th><th>Discount Amount</th><th>Description</th><th>Action</th></tr></thead><tbody>${d.discount.map(r=>`<tr><td>${r.id}</td><td>${esc(r.name)}</td><td>${esc(r.code)}</td><td>${esc(r.amount)}</td><td>${esc(r.description)}</td><td>${schoolAction(r.id)}</td></tr>`).join('')}</tbody></table>`;
}
function schoolSetupView(){const d=schoolSetupData();return `<div class="school-crumb">⌂ Dashboard　/　⚙ Other settings　/　<span>${schoolSetupTab==='program'?'Add Curriculum':schoolSetupTab==='time'?'Add Section':schoolSetupTab==='class'?'Create Class':schoolSetupTab==='discount'?'Create Discount':'School Setup'}</span>　<a href="#" data-go="dashboard">← Back</a></div><div class="school-setup-layout">${schoolSide()}<section class="school-setup-card"><div class="school-table-scroll">${schoolSetupTable(schoolSetupTab,d)}</div></section></div>`}
function schoolModalField(label,html,required=false){return `<label class="school-modal-field"><span>${label}${required?' <em>*</em>':''}</span>${html}</label>`}
function schoolSelect(name,placeholder,items){return `<select name="${name}"><option value="">${placeholder}</option>${items.map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('')}</select>`}
function schoolFineBlock(){return `<div class="school-fine"><strong>Fine Type <em>*</em></strong><div class="school-radio-line"><label><input type="radio" name="fineType" value="None" checked> None</label><label><input type="radio" name="fineType" value="Percentage"> Percentage</label><label><input type="radio" name="fineType" value="Fix Amount"> Fix Amount</label></div><div class="school-two-col">${schoolModalField('Percentage','<input name="percentage" value="0.00">')}${schoolModalField('Fine Amount','<input name="fineAmount" value="0.00">')}</div></div>`}
function schoolMasterRows(){const ds=[[30,1],[90,3],[180,6],[360,12],['',''],['','']];return `<div class="school-master-grid"><div class="school-master-head"><b>Day <em>*</em></b><b>Month <em>*</em></b><b>Half Day <em>*</em></b><b>Full Day <em>*</em></b></div>${ds.map(v=>`<div class="school-master-row"><input name="day[]" value="${v[0]}" placeholder="Days"><input name="month[]" value="${v[1]}" placeholder="Month"><input name="half[]" placeholder="Amount"><input name="full[]" placeholder="Amount"></div>`).join('')}</div>`}
function schoolFeeRows(kind,count){const ds=[[30,1],[90,3],[180,6],[360,12],['',''],['','']].slice(0,count);return `<div class="school-fee-grid school-fee-${kind}" data-fee-grid="${kind}"><div class="school-fee-head">${kind==='car'?'<b>Fees</b><b>Day</b><b>Month</b><b>Round 1</b><b>Round 2</b><b>Round 3</b><b>Round 4</b><b></b>':'<b>Fees</b><b>Day</b><b>Month</b><b>Half Day</b><b>Full Day</b><b></b>'}</div>${ds.map(v=>kind==='car'?`<div class="school-fee-row"><input name="feeName[]" placeholder="Fee name"><input name="day[]" value="${v[0]}" placeholder="Days"><input name="month[]" value="${v[1]}" placeholder="Month"><input name="r1[]" placeholder="Round 1"><input name="r2[]" placeholder="Round 2"><input name="r3[]" placeholder="Round 3"><input name="r4[]" placeholder="Round 4"><button type="button" class="school-row-delete">▰</button></div>`:`<div class="school-fee-row"><input name="feeName[]" placeholder="Fee name"><input name="day[]" value="${v[0]}" placeholder="Days"><input name="month[]" value="${v[1]}" placeholder="Month"><input name="half[]" placeholder="Amount"><input name="full[]" placeholder="Amount"><button type="button" class="school-row-delete">▰</button></div>`).join('')}<div class="school-add-row-wrap"><button type="button" class="school-add-row" data-kind="${kind}">＋ Add Row</button></div></div>`}
function schoolModalTemplate(tab,d){
 const branch=schoolModalField('Branch','<select name="branch"><option>SC1</option></select>',true),branches=schoolModalField('Branches','<select name="branch"><option>SC1</option></select>',true),session=schoolModalField('Session','<select name="session"><option>2025-2026</option></select>',true),programs=d.program.map(x=>x.program),times=d.time.map(x=>x.name),classes=d.class.map(x=>x.class),levels=d.class.map(x=>x.level),fees=d.feeType.map(x=>x.name);let title='',body='',wide=false;
 if(tab==='program'){title='Add Curriculum';body=branch+session+schoolModalField('Program','<input name="program" required>',true)+schoolModalField('Description','<textarea name="description" rows="4"></textarea>')}
 else if(tab==='time'){title='Add Section';body='<label class="school-check"><input type="checkbox" name="all"> All</label>'+branches+schoolModalField('Section Name','<input name="name" placeholder="Ex. morning" required>',true)}
 else if(tab==='class'){title='Create Class';body=`<div class="school-branch-all">${branches}<label class="school-check"><input type="checkbox" name="all"> All</label></div>${session}${schoolModalField('Program',schoolSelect('program','Select curriculum',programs),true)}${schoolModalField('Time',schoolSelect('time','Select time',times))}${schoolModalField('Class','<input name="class" placeholder="Example: elementary khmer language" required>',true)}${schoolModalField('Level','<input name="level" placeholder="Example: Kindergarten Khmer 1" required>',true)}${schoolModalField('Description','<textarea name="description" rows="3" placeholder="Note"></textarea>')}`}
 else if(tab==='classStart'){title='Add Class Start';body=branches+session+schoolModalField('Program',schoolSelect('program','Select program',programs),true)+schoolModalField('Class',schoolSelect('class','Select class',classes),true)+`<div class="school-two-col">${schoolModalField('Start Date','<input type="date" name="start" required>',true)}${schoolModalField('End Date','<input type="date" name="end" required>',true)}</div>`+schoolModalField('Available Seats','<input type="number" name="seats" value="30" min="0" required>',true)}
 else if(tab==='feeType'){title='Add Fees Type';body=branch+schoolModalField('Fees Type','<input name="name" required>',true)+schoolModalField('Code','<input name="code">')+schoolModalField('Description','<textarea name="description" rows="4"></textarea>')}
 else if(tab==='feeMaster'){title='Add Fees Master';wide=true;body=`<div class="school-branch-all">${branches}<label class="school-check"><input type="checkbox" name="all"> All</label></div>${session}${schoolModalField('Program',schoolSelect('program','Select curriculum',programs),true)}${schoolModalField('Level',schoolSelect('level','Select level',levels),true)}${schoolMasterRows()}${schoolFineBlock()}`}
 else if(tab==='otherFee'){title='Add Other Fees';wide=true;body=`<div class="school-two-col">${branches}${session}</div>${schoolModalField('Fee Type',schoolSelect('feeType','Select fee type',fees),true)}${schoolFeeRows('other',6)}${schoolFineBlock()}`}
 else if(tab==='carFee'){title='Add Car Fee';wide=true;body=`<div class="school-two-col">${branches}${session}</div>${schoolModalField('Fee Type',schoolSelect('feeType','Select fee type',fees),true)}${schoolFeeRows('car',4)}${schoolFineBlock()}`}
 else if(tab==='room'){title='＋ core::general.add_room';body=branches+schoolModalField('Room Name','<input name="name" placeholder="Enter Room Name" required>',true)}
 else {title='＋ Create Discount';body=branches+schoolModalField('Discount Name','<input name="name" required>',true)+schoolModalField('Discount Code','<input name="code">')+schoolModalField('Discount Amount','<input name="amount" type="number" step="0.01">')+schoolModalField('Description','<textarea name="description" rows="4"></textarea>')}
 return `<div class="school-modal-backdrop" id="schoolModal"><section class="school-modal ${wide?'wide':''}"><header><h2>${title}</h2><button type="button" class="school-modal-x">×</button></header><form id="schoolModalForm" data-tab="${tab}"><div class="school-modal-body">${body}</div><footer><button type="button" class="school-modal-close">Close</button><button type="submit" class="school-modal-save">▣ Save</button></footer></form></section></div>`
}
function schoolDateInput(v){if(!v)return'';if(/^\d{4}-\d{2}-\d{2}$/.test(v))return v;const m={Jan:'01',Feb:'02',Mar:'03',Apr:'04',May:'05',Jun:'06',Jul:'07',Aug:'08',Sep:'09',Oct:'10',Nov:'11',Dec:'12'};const p=String(v).split('-');return p.length===3?`${p[2]}-${m[p[1]]||'01'}-${String(p[0]).padStart(2,'0')}`:''}
function schoolFillForm(form,tab,r){
 const set=(n,v)=>{const el=form.elements[n];if(el)el.value=v??''};
 set('branch',r.branch||'SC1');
 if(tab==='program'){set('session',r.session);set('program',r.program);set('description',r.description)}
 else if(tab==='time'){set('name',r.name)}
 else if(tab==='class'){set('session',r.session||'2025-2026');set('program',r.program);set('time',r.time);set('class',r.class);set('level',r.level);set('description',r.description)}
 else if(tab==='classStart'){set('session',r.session||'2025-2026');set('program',r.program);set('class',r.class);set('start',schoolDateInput(r.start));set('end',schoolDateInput(r.end));set('seats',r.seats)}
 else if(tab==='feeType'){set('name',r.name);set('code',r.slug||r.code||'');set('description',r.description)}
 else if(tab==='feeMaster'){
   set('session',r.session||'2025-2026');set('program',r.program);set('level',r.level);
   const rows=[...form.querySelectorAll('.school-master-row')];(r.desc||[]).forEach((x,i)=>{if(!rows[i])return;const mm=String(x).match(/(\d+) Month/),h=String(x).match(/Half \$([\d.]+)/),f=String(x).match(/Full \$([\d.]+)/);if(mm)rows[i].querySelector('[name="month[]"]').value=mm[1];if(h)rows[i].querySelector('[name="half[]"]').value=h[1];if(f)rows[i].querySelector('[name="full[]"]').value=f[1]})
 }
 else if(tab==='otherFee'){
   set('session',r.session||'2025-2026');set('feeType',r.feeType);const parts=Array.isArray(r.description)?r.description:String(r.description||'').split(';').map(x=>x.trim()).filter(Boolean),rows=[...form.querySelectorAll('.school-fee-row')];parts.forEach((x,i)=>{if(!rows[i])return;const nm=x.match(/^(.*?)\s*-\s*\d+ Month/),mo=x.match(/(\d+) Month/),h=x.match(/Half \$([\d.]+)/),f=x.match(/Full \$([\d.]+)/);if(nm)rows[i].querySelector('[name="feeName[]"]').value=nm[1];if(mo)rows[i].querySelector('[name="month[]"]').value=mo[1];if(h)rows[i].querySelector('[name="half[]"]').value=h[1];if(f)rows[i].querySelector('[name="full[]"]').value=f[1]})
 }
 else if(tab==='carFee'){
   set('session',r.session||'2025-2026');set('feeType',r.feeType);const rows=[...form.querySelectorAll('.school-fee-row')];(r.description||[]).forEach((x,i)=>{if(!rows[i])return;const nm=String(x).match(/^(.*?)\s*\(R1:/),vals=[1,2,3,4].map(n=>String(x).match(new RegExp(`R${n}: \$?([\d.]+)`)));if(nm)rows[i].querySelector('[name="feeName[]"]').value=nm[1];vals.forEach((m,j)=>{if(m)rows[i].querySelector(`[name="r${j+1}[]"]`).value=m[1]})})
 }
 else if(tab==='room'){set('name',r.name)}
 else {set('name',r.name);set('code',r.code);set('amount',r.amount);set('description',r.description)}
}
function openSchoolModal(id=''){const d=schoolSetupData(),r=id?(d[schoolSetupTab]||[]).find(x=>String(x.id)===String(id)):null;document.body.insertAdjacentHTML('beforeend',schoolModalTemplate(schoolSetupTab,d));const form=document.querySelector('#schoolModalForm');if(form){const h=document.createElement('input');h.type='hidden';h.name='_id';h.value=id;form.appendChild(h);if(r){schoolFillForm(form,schoolSetupTab,r);const title=document.querySelector('#schoolModal .school-modal h2');if(title)title.textContent=title.textContent.replace(/^Add /,'Edit ').replace(/^＋ Create /,'Edit ').replace(/^Create /,'Edit ')}}bindSchoolModal()}
function closeSchoolModal(){document.querySelector('#schoolModal')?.remove()}
function schoolArray(form,name){return [...form.querySelectorAll(`[name="${name}[]"]`)].map(x=>x.value.trim())}
function schoolDate(v){if(!v)return'';const [y,m,d]=v.split('-'),mo=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];return `${d}-${mo[Number(m)-1]}-${y}`}
function schoolSaveModal(form){const tab=form.dataset.tab,d=schoolSetupData(),fd=new FormData(form),editId=fd.get('_id')||'',next=editId||((d[tab]||[]).reduce((m,x)=>Math.max(m,Number(x.id)||0),0)+1),branch=fd.get('branch')||'SC1';let r={id:next,branch};
 if(tab==='program')r={...r,session:fd.get('session')||'2025-2026',program:fd.get('program')||'',description:fd.get('description')||''};
 else if(tab==='time')r={...r,name:fd.get('name')||''};
 else if(tab==='class')r={...r,program:fd.get('program')||'',class:fd.get('class')||'',level:fd.get('level')||'',time:fd.get('time')||'',description:fd.get('description')||''};
 else if(tab==='classStart')r={...r,program:fd.get('program')||'',class:fd.get('class')||'',start:schoolDate(fd.get('start')),end:schoolDate(fd.get('end')),students:0,seats:Number(fd.get('seats')||0),status:'Active'};
 else if(tab==='feeType'){const name=fd.get('name')||'';r={...r,name,slug:(fd.get('code')||name).toLowerCase().replace(/[^a-z0-9]+/g,'-'),account:'Other Fee (Admin Fee, Exam Fee, Registration Fee)',description:fd.get('description')||name}}
 else if(tab==='feeMaster'){const mo=schoolArray(form,'month'),half=schoolArray(form,'half'),full=schoolArray(form,'full'),level=fd.get('level')||'',cls=d.class.find(x=>x.level===level);r={...r,program:fd.get('program')||'',class:cls?.class||level,level,desc:mo.map((x,i)=>x?`${x} Month${Number(x)>1?'s':''} (Half $${Number(half[i]||0).toFixed(2)} | Full $${Number(full[i]||0).toFixed(2)})`:null).filter(Boolean)}}
 else if(tab==='otherFee'){const names=schoolArray(form,'feeName'),mo=schoolArray(form,'month'),half=schoolArray(form,'half'),full=schoolArray(form,'full');r={...r,feeType:fd.get('feeType')||'',description:names.map((n,i)=>n?`${n} - ${mo[i]||''} Month (Half $${Number(half[i]||0).toFixed(2)} | Full $${Number(full[i]||0).toFixed(2)})`:null).filter(Boolean).join('; ')}}
 else if(tab==='carFee'){const names=schoolArray(form,'feeName'),r1=schoolArray(form,'r1'),r2=schoolArray(form,'r2'),r3=schoolArray(form,'r3'),r4=schoolArray(form,'r4');r={...r,feeType:fd.get('feeType')||'Transport Fee',description:names.map((n,i)=>n?`${n} (R1: $${r1[i]||0}) | (R2: $${r2[i]||0}) | (R3: $${r3[i]||0}) | (R4: $${r4[i]||0})`:null).filter(Boolean)}}
 else if(tab==='room')r={...r,name:fd.get('name')||''};
 else r={...r,name:fd.get('name')||'',code:fd.get('code')||'',amount:Number(fd.get('amount')||0).toFixed(2),description:fd.get('description')||''};
 const idx=(d[tab]||[]).findIndex(x=>String(x.id)===String(editId));if(editId&&idx>=0)d[tab][idx]=r;else d[tab].push(r);saveSchoolSetupData(d);closeSchoolModal();toast(editId?'Updated successfully':'Saved successfully');render()}
function schoolAddFeeRow(kind){const grid=document.querySelector(`[data-fee-grid="${kind}"]`),wrap=grid?.querySelector('.school-add-row-wrap');if(!grid||!wrap)return;const row=document.createElement('div');row.className='school-fee-row';row.innerHTML=kind==='car'?'<input name="feeName[]" placeholder="Fee name"><input name="day[]" placeholder="Days"><input name="month[]" placeholder="Month"><input name="r1[]" placeholder="Round 1"><input name="r2[]" placeholder="Round 2"><input name="r3[]" placeholder="Round 3"><input name="r4[]" placeholder="Round 4"><button type="button" class="school-row-delete">▰</button>':'<input name="feeName[]" placeholder="Fee name"><input name="day[]" placeholder="Days"><input name="month[]" placeholder="Month"><input name="half[]" placeholder="Amount"><input name="full[]" placeholder="Amount"><button type="button" class="school-row-delete">▰</button>';grid.insertBefore(row,wrap);row.querySelector('.school-row-delete').onclick=()=>row.remove()}
function bindSchoolModal(){const modal=document.querySelector('#schoolModal'),form=document.querySelector('#schoolModalForm');if(!modal||!form)return;modal.querySelector('.school-modal-x').onclick=closeSchoolModal;modal.querySelector('.school-modal-close').onclick=closeSchoolModal;modal.onclick=e=>{if(e.target===modal)closeSchoolModal()};form.onsubmit=e=>{e.preventDefault();schoolSaveModal(form)};modal.querySelectorAll('.school-row-delete').forEach(b=>b.onclick=()=>b.closest('.school-fee-row')?.remove());modal.querySelectorAll('.school-add-row').forEach(b=>b.onclick=()=>schoolAddFeeRow(b.dataset.kind))}
function bindSchoolSetup(){if(state.page!=='setting-school')return;document.querySelectorAll('[data-school-tab]').forEach(b=>b.onclick=()=>{schoolSetupTab=b.dataset.schoolTab;localStorage.setItem('sc_school_setup_tab',schoolSetupTab);render()});const add=document.querySelector('[data-school-add]');if(add)add.onclick=()=>openSchoolModal();const search=document.querySelector('#schoolSearch');if(search)search.oninput=()=>{const q=search.value.toLowerCase();document.querySelectorAll('.school-setup-card tbody tr').forEach(tr=>tr.hidden=!tr.textContent.toLowerCase().includes(q))};document.querySelectorAll('.school-action').forEach(btn=>btn.onclick=e=>{e.stopPropagation();const menu=btn.nextElementSibling,open=menu.hidden;document.querySelectorAll('.school-action-menu').forEach(m=>m.hidden=true);menu.hidden=!open});document.querySelectorAll('.school-action-edit').forEach(btn=>btn.onclick=e=>{e.stopPropagation();openSchoolModal(btn.dataset.id)});document.querySelectorAll('.school-action-delete').forEach(btn=>btn.onclick=e=>{e.stopPropagation();const id=btn.dataset.id,d=schoolSetupData(),row=(d[schoolSetupTab]||[]).find(x=>String(x.id)===String(id));if(!row)return;if(!confirm('Delete this record? This action cannot be undone.'))return;d[schoolSetupTab]=(d[schoolSetupTab]||[]).filter(x=>String(x.id)!==String(id));saveSchoolSetupData(d);toast('Deleted successfully');render()});document.onclick=()=>document.querySelectorAll('.school-action-menu').forEach(m=>m.hidden=true)}


/* SR ADMIN live date and time */
function updateSRDateTime(){
  const dateEl=document.getElementById('liveDate');
  const timeEl=document.getElementById('liveTime');
  const modeEl=document.getElementById('dayNightLabel');
  if(!dateEl||!timeEl)return;
  const now=new Date();
  const hour=now.getHours();
  const isNight=hour<6||hour>=18;
  dateEl.textContent=now.toLocaleDateString('en-GB',{weekday:'short',day:'2-digit',month:'short',year:'numeric'});
  timeEl.textContent=now.toLocaleTimeString('en-US',{hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:true});
  if(modeEl){
    modeEl.textContent=isNight?'☾ Night Time':'☀ Day Time';
    modeEl.classList.toggle('night',isNight);
    modeEl.classList.toggle('day',!isNight);
  }
  // Keep the system's blue/white palette at all hours. The label still reports
  // the actual time period without turning forms, tables and pages black.
  document.body.classList.remove('night-time');
  document.body.classList.add('day-time');
}
