/* =========================================================
   SR ADMIN unified dashboard action styling
   Applies consistent classes to Add/Edit/Delete/Save/etc.
   across all dynamically rendered pages without changing logic.
   ========================================================= */
(function(){
  const classNames=['sr-action-add','sr-action-edit','sr-action-delete','sr-action-save','sr-action-back','sr-action-export','sr-action-print','sr-action-filter'];
  function normalized(el){
    return ((el.textContent||'')+' '+(el.getAttribute('title')||'')+' '+(el.getAttribute('aria-label')||'')+' '+(el.getAttribute('onclick')||'')).replace(/\s+/g,' ').trim().toLowerCase();
  }
  function decorate(root=document){
    root.querySelectorAll('button, a.btn, input[type="submit"], input[type="button"]').forEach(el=>{
      classNames.forEach(c=>el.classList.remove(c));
      const t=normalized(el);
      if(!t || /previous|next|•••|⌄/.test(t)) return;
      if(/delete|remove|trash/.test(t)) el.classList.add('sr-action-delete');
      else if(/\bedit\b|update/.test(t)) el.classList.add('sr-action-edit');
      else if(/save|submit|confirm|approve/.test(t)) el.classList.add('sr-action-save');
      else if(/add new|add |create|new record|register new|import employees?/.test(t)) el.classList.add('sr-action-add');
      else if(/export|excel|download/.test(t)) el.classList.add('sr-action-export');
      else if(/print|pdf/.test(t)) el.classList.add('sr-action-print');
      else if(/filter|search/.test(t) && el.tagName==='BUTTON') el.classList.add('sr-action-filter');
      else if(/back|cancel|close/.test(t)) el.classList.add('sr-action-back');
    });
  }
  function run(){decorate(document)}
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',run); else run();
  const observer=new MutationObserver(mutations=>{
    for(const m of mutations){
      for(const node of m.addedNodes){
        if(node.nodeType===1){decorate(node.matches?.('button,a.btn,input')?node.parentElement:node)}
      }
    }
  });
  observer.observe(document.documentElement,{childList:true,subtree:true});
  window.srRefreshActionStyles=run;
})();


/* =========================================================
   Single plus marker on Add/Create/New buttons
   Keeps one visible + only and removes duplicated + glyphs.
   ========================================================= */
(function(){
  const plusRE=/[+＋✚✛➕]/g;
  function cleanButton(btn){
    if(!btn || btn.nodeType!==1)return;
    const text=((btn.textContent||'')+' '+(btn.getAttribute('aria-label')||'')).toLowerCase();
    if(!/(add|create|new|register)/.test(text))return;
    const hasAddSvg=!!btn.querySelector('svg');
    let seen=0;
    [...btn.childNodes].forEach(node=>{
      if(node.nodeType!==3)return;
      let value=node.nodeValue||'';
      value=value.replace(plusRE,()=>{
        if(hasAddSvg)return '';
        seen++;
        return seen===1?'＋':'';
      });
      node.nodeValue=value.replace(/\s{2,}/g,' ');
    });
  }
  function run(root=document){root.querySelectorAll('button,a.btn,input[type="button"],input[type="submit"]').forEach(cleanButton)}
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>run());else run();
  new MutationObserver(ms=>ms.forEach(m=>m.addedNodes.forEach(n=>{if(n.nodeType===1){if(n.matches?.('button,a.btn'))cleanButton(n);run(n)}}))).observe(document.documentElement,{subtree:true,childList:true});
})();

/* Keep every currency selector synchronized with Settings → Currency. */
(function(){
  const sync=()=>applyCurrencyControls(document);
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',sync);else sync();
  new MutationObserver(changes=>{if(changes.some(change=>[...change.addedNodes].some(node=>node.nodeType===1)))sync()}).observe(document.documentElement,{childList:true,subtree:true});
})();

